BibliaDatos.agregar("PSA",{"cod":"PSA","nombre":"Salmos","caps":[{"i":[[0,"LIBRO 1"],[1,"Bienaventurado el hombre que no sigue el consejo de los impíos,\nni se detiene en la senda de los pecadores,\nni en la reunión de burladores se sienta;"],[2,"sino que en la ley de Yahvé está su delicia.\nEn su ley medita de día y de noche."],[3,"Será como un árbol plantado junto a corrientes de agua,\nque da su fruto a su tiempo,\ny cuya hoja no se marchita.\nTodo lo que hace, prosperará."],[4,"No así los impíos,\nque son como la paja que se lleva el viento."],[5,"Por tanto, no se sostendrán los impíos en el juicio,\nni los pecadores en la asamblea de los justos."],[6,"Porque Yahvé conoce el camino de los justos,\nmas la senda de los impíos perecerá."]],"l":[]},{"i":[[1,"¿Por qué se amotinan las naciones,\ny los pueblos trazan planes vanos?"],[2,"Se alzan los reyes de la tierra,\ny los príncipes conspiran a una\ncontra Yahvé y contra su Ungido, diciendo:"],[3,"«Rompamos sus ataduras,\ny sacudamos de nosotros sus cuerdas»."],[4,"El que mora en los cielos se ríe;\nel Señor se burla de ellos."],[5,"Luego les hablará en su indignación,\ny los aterrará con su furor:"],[6,"«Yo mismo he puesto a mi Rey\nsobre Sión, mi monte santo».",[[35,39,0]]],[7,"Proclamaré el decreto de Yahvé; él me dijo:\n«Tú eres mi hijo; yo te he engendrado hoy."],[8,"Pídeme, y te daré por herencia las naciones,\ny como posesión tuya los confines de la tierra."],[9,"Los quebrantarás con cetro de hierro;\ncomo vasija de alfarero los desmenuzarás»."],[10,"Ahora, pues, oh reyes, sed sabios;\nadmitid la corrección, jueces de la tierra."],[11,"Servid a Yahvé con temor,\ny alegraos con temblor."],[12,"Rendid homenaje al Hijo, no sea que se enoje y perezcáis en el camino;\npues se inflama de pronto su ira.\nBienaventurados todos los que en él confían."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Un salmo de David, cuando huyó de su hijo Absalón."],[1,"¡Yahvé, cómo han aumentado mis adversarios!\nMuchos son los que se levantan contra mí."],[2,"Son muchos los que dicen de mí,\n«No hay ayuda para él en Dios». Selah."],[3,"Pero tú, Yahvé, eres escudo en torno a mí,\nmi gloria, y el que levanta mi cabeza."],[4,"Con mi voz clamo a Yahvé,\ny él me responde desde su santo monte. Selah."],[5,"Yo me acosté y dormí;\ndesperté, porque Yahvé me sostiene."],[6,"No temeré a miríadas de gentes\nque se han puesto contra mí en derredor."],[7,"¡Levántate, Yahvé!\n¡Sálvame, Dios mío!\nPues tú has golpeado a todos mis enemigos en la mejilla;\nhas roto los dientes de los malvados."],[8,"De Yahvé es la salvación.\n¡Que tu bendición sea sobre tu pueblo! Selah."]],"l":[]},{"i":[[0,"Para el músico principal; con instrumentos de cuerda. Un salmo de David."],[1,"Respóndeme cuando clamo, Dios de mi justicia.\nEn la angustia me has dado alivio.\nTen piedad de mí y escucha mi oración."],[2,"Hijos de los hombres, ¿hasta cuándo convertiréis mi gloria en deshonra?\n¿Hasta cuándo amaréis la vanidad y buscaréis la falsedad? Selah."],[3,"Sabed, pues, que Yahvé ha apartado para sí al piadoso;\nYahvé oirá cuando yo a él clame."],[4,"Temblad, y no pequéis;\nmeditad en vuestro corazón sobre vuestro lecho, y guardad silencio. Selah."],[5,"Ofreced sacrificios de justicia,\ny confiad en Yahvé."],[6,"Muchos dicen: «¿Quién nos mostrará el bien?»\n¡Alza sobre nosotros, oh Yahvé, la luz de tu rostro!"],[7,"Has puesto alegría en mi corazón,\nmayor que la de ellos cuando abundan su grano y su mosto."],[8,"En paz me acostaré, y asimismo dormiré,\nporque solo tú, Yahvé, me haces vivir confiado."]],"l":[]},{"i":[[0,"Al director musical; para flautas. Salmo de David."],[1,"Escucha mis palabras, oh Yahvé;\nconsidera mi gemido."],[2,"Atiende a la voz de mi clamor, Rey mío y Dios mío,\nporque a ti oro."],[3,"Oh Yahvé, de mañana oirás mi voz;\nde mañana me presentaré ante ti, y esperaré."],[4,"Porque tú no eres un Dios que se complace en la maldad;\nel mal no habitará junto a ti."],[5,"Los arrogantes no se mantendrán delante de tus ojos;\naborreces a todos los que obran iniquidad."],[6,"Destruirás a los que hablan mentira;\nYahvé aborrece al hombre sanguinario y engañador."],[7,"Mas yo, por la abundancia de tu misericordia, entraré en tu casa;\nme postraré hacia tu santo templo en tu temor."],[8,"Guíame, Yahvé, en tu justicia a causa de mis enemigos;\nendereza tu camino delante de mí."],[9,"Porque no hay sinceridad en su boca;\nsus entrañas son maldad.\nSepulcro abierto es su garganta;\ncon su lengua lisonjean."],[10,"Decláralos culpables, oh Dios;\nque caigan por sus propios consejos.\nÉchalos por la multitud de sus transgresiones,\nporque se han rebelado contra ti."],[11,"Pero que se alegren todos los que en ti confían;\nque siempre den voces de júbilo, porque tú los defiendes.\nQue se regocijen en ti los que aman tu nombre."],[12,"Porque tú, oh Yahvé, bendecirás al justo;\ncomo con un escudo lo rodearás de tu favor."]],"l":[]},{"i":[[0,"Al director musical; con instrumentos de cuerda, sobre la lira de ocho cuerdas. Salmo de David."],[1,"Yahvé, no me reprendas en tu furor,\nni me castigues en tu ira."],[2,"Ten piedad de mí, Yahvé, porque estoy desfallecido;\nsáname, Yahvé, porque mis huesos están estremecidos."],[3,"Mi alma también está muy angustiada.\nY tú, Yahvé, ¿hasta cuándo?"],[4,"Vuélvete, Yahvé, libra mi alma;\nsálvame por tu misericordia."],[5,"Porque en la muerte no hay memoria de ti.\nEn el Seol, ¿quién te alabará?"],[6,"Estoy agotado de tanto gemir.\nCada noche inundo mi lecho;\nempapo mi cama con mis lágrimas."],[7,"Mis ojos se consumen por el dolor;\nhan envejecido a causa de todos mis adversarios."],[8,"Apartaos de mí, todos los hacedores de iniquidad,\nporque Yahvé ha escuchado la voz de mi llanto."],[9,"Yahvé ha escuchado mi súplica;\nYahvé ha recibido mi oración."],[10,"Que todos mis enemigos se avergüencen y se turben en gran manera;\nque retrocedan y sean deshonrados de repente."]],"l":[]},{"i":[[0,"Meditación de David, que cantó a Yahvé, sobre las palabras de Cus, el benjamita."],[1,"Yahvé, Dios mío, en ti me refugio.\nSálvame de todos los que me persiguen y líbrame,"],[2,"para que no desgarren mi alma como un león,\ndespedazándome sin que haya quien me libre."],[3,"Yahvé, Dios mío, si he hecho esto,\nsi hay iniquidad en mis manos,"],[4,"si he dado mal pago al que estaba en paz conmigo\n(yo que he librado al que sin causa era mi adversario),"],[5,"que el enemigo persiga mi alma y la alcance;\nsí, que pise mi vida hasta la tierra,\ny ponga mi gloria en el polvo. Selah."],[6,"Levántate, Yahvé, en tu ira.\nLevántate contra la furia de mis adversarios.\nDespierta en mi favor; tú has ordenado el juicio."],[7,"Que la asamblea de los pueblos te rodee.\nGobierna sobre ellos en las alturas."],[8,"Yahvé administra el juicio a los pueblos.\nJúzgame, Yahvé, según mi justicia,\ny conforme a la integridad que hay en mí."],[9,"Oh, que la maldad de los malvados llegue a su fin, y establece al justo;\npues las mentes y los corazones son escudriñados por el Dios justo."],[10,"Mi escudo es Dios,\nque salva a los rectos de corazón."],[11,"Dios es un juez justo,\nsí, un Dios que se indigna cada día."],[12,"Si el hombre no se arrepiente, él afilará su espada;\nha tensado y preparado su arco."],[13,"También ha preparado para sí mismo los instrumentos de muerte;\nprepara sus flechas ardientes."],[14,"He aquí que el malvado concibe iniquidad.\nSí, se preña de maldad,\ny da a luz la falsedad."],[15,"Ha cavado un pozo, y lo ha hecho profundo,\ny ha caído en la fosa que él mismo hizo."],[16,"Su iniquidad volverá sobre su propia cabeza.\nSu violencia caerá sobre su propia coronilla."],[17,"Daré gracias a Yahvé conforme a su justicia,\ny cantaré alabanzas al nombre de Yahvé el Altísimo."]],"l":[]},{"i":[[0,"Al director musical; sobre Gitit. Salmo de David."],[1,"¡Oh Yahvé, Señor nuestro, cuán glorioso es tu nombre en toda la tierra!\nHas puesto tu gloria sobre los cielos."],[2,"De la boca de los niños y de los que maman, fundaste la fortaleza,\na causa de tus adversarios, para hacer callar al enemigo y al vengativo."],[3,"Cuando contemplo tus cielos, obra de tus dedos,\nla luna y las estrellas que tú formaste,"],[4,"digo: ¿Qué es el hombre, para que tengas de él memoria?\n¿Y el hijo del hombre, para que lo visites?"],[5,"Pues lo has hecho un poco menor que los ángeles,\ny lo has coronado de gloria y honra."],[6,"Le hiciste señorear sobre las obras de tus manos;\ntodo lo pusiste debajo de sus pies:"],[7,"Ovejas y bueyes, todo ello,\ny asimismo las bestias del campo,"],[8,"las aves de los cielos y los peces del mar;\ntodo cuanto pasa por los senderos del mar."],[9,"¡Oh Yahvé, Señor nuestro,\ncuán glorioso es tu nombre en toda la tierra!"]],"l":[]},{"i":[[0,"Al director musical; sobre Mut-labén. Salmo de David."],[1,"Daré gracias a Yahvé de todo corazón;\ncontaré todas tus maravillas."],[2,"Me alegraré y me regocijaré en ti;\ncantaré alabanzas a tu nombre, oh Altísimo."],[3,"Cuando mis enemigos retroceden,\ntropiezan y perecen delante de ti."],[4,"Porque has defendido mi causa y mi derecho;\nte has sentado en el trono, juzgando con justicia."],[5,"Has reprendido a las naciones,\nhas destruido a los impíos;\nhas borrado su nombre para siempre."],[6,"Los enemigos han perecido, asolados para siempre;\nhas derribado sus ciudades, y hasta su recuerdo ha perecido."],[7,"Pero Yahvé permanece para siempre;\nha preparado su trono para el juicio."],[8,"Él juzgará al mundo con justicia;\nadministrará el juicio a los pueblos con rectitud."],[9,"Yahvé también será un alto refugio para los oprimidos;\nun refugio en tiempos de angustia."],[10,"Los que conocen tu nombre pondrán su confianza en ti,\nporque tú, Yahvé, no has abandonado a los que te buscan."],[11,"Cantad alabanzas a Yahvé, que habita en Sión,\ny declarad entre los pueblos sus obras.",[[40,44,0]]],[12,"Porque el que pide cuentas de la sangre se acuerda de ellos;\nno olvida el clamor de los afligidos."],[13,"Ten piedad de mí, Yahvé.\nMira la aflicción que padezco por los que me odian,\ntú que me levantas de las puertas de la muerte,"],[14,"para que pueda contar todas tus alabanzas.\nMe alegraré en tu salvación en las puertas de la hija de Sión.",[[100,104,0]]],[15,"Las naciones se han hundido en la fosa que hicieron;\nen la red que escondieron, fue atrapado su propio pie."],[16,"Yahvé se ha dado a conocer;\nha ejecutado juicio.\nEl impío es atrapado en la obra de sus propias manos. Higayón. Selah."],[17,"Los impíos volverán al Seol,\ny todas las naciones que se olvidan de Dios."],[18,"Porque el necesitado no será olvidado para siempre,\nni la esperanza de los pobres perecerá perpetuamente."],[19,"¡Levántate, Yahvé! No dejes que el hombre prevalezca;\nque las naciones sean juzgadas delante de ti."],[20,"Infúndeles temor, oh Yahvé;\nque las naciones sepan que no son más que hombres. Selah."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[1,"¿Por qué te mantienes lejos, oh Yahvé?\n¿Por qué te escondes en los tiempos de angustia?"],[2,"Con arrogancia, el impío persigue al desvalido.\nSean atrapados en las maquinaciones que han ideado."],[3,"Porque el impío se jacta del deseo de su alma.\nBendice al codicioso y desprecia a Yahvé."],[4,"El impío, por la altivez de su rostro, no busca a Dios;\nno hay lugar para Dios en todos sus pensamientos."],[5,"Sus caminos prosperan en todo tiempo.\nEs arrogante, y tus juicios están muy lejos de su vista.\nEn cuanto a todos sus adversarios, se burla de ellos."],[6,"Dice en su corazón: «No seré conmovido.\nJamás me alcanzará el infortunio»."],[7,"Su boca está llena de maldición, de engaño y de fraude.\nDebajo de su lengua hay vejación e iniquidad."],[8,"Se sienta al acecho en las aldeas.\nEn los escondrijos mata al inocente.\nSus ojos espían en secreto al desvalido."],[9,"Acecha en oculto como el león en su guarida.\nAcecha para arrebatar al pobre.\nArrebata al pobre atrayéndolo a su red."],[10,"Se encoge, se agacha.\nCaen los desvalidos.\nCaen bajo sus fuertes garras."],[11,"Dice en su corazón: «Dios ha olvidado.\nHa ocultado su rostro.\nNunca lo verá»."],[12,"¡Levántate, oh Yahvé!\n¡Oh Dios, alza tu mano!\nNo te olvides de los pobres."],[13,"¿Por qué desprecia el impío a Dios,\ny dice en su corazón: «¿Acaso Dios me pedirá cuentas?»"],[14,"Pero tú lo has visto, porque miras el trabajo y la aflicción.\nLo consideras para dar la recompensa con tu mano.\nA ti se acoge el desvalido; tú eres el amparo del huérfano."],[15,"Quebranta el brazo del impío.\nEn cuanto al hombre malo, busca su maldad hasta que no halles ninguna."],[16,"¡Yahvé es Rey eternamente y para siempre!\nLas naciones perecerán de su tierra."],[17,"Oh Yahvé, tú has oído el deseo de los humildes.\nConfortarás su corazón.\nHarás atento tu oído,"],[18,"para juzgar al huérfano y al oprimido,\na fin de que el hombre de la tierra no aterrorice más."]],"l":[]},{"i":[[0,"Al director musical. Salmo de David."],[1,"En Yahvé me refugio;\n¿cómo decís a mi alma: «Huid al monte como ave»?"],[2,"Porque he aquí, los impíos tensan el arco,\npreparan sus saetas sobre la cuerda,\npara asaetear en oculto a los rectos de corazón."],[3,"Si fuesen destruidos los fundamentos,\n¿qué ha de hacer el justo?"],[4,"Yahvé está en su santo templo;\nel trono de Yahvé está en el cielo.\nSus ojos contemplan,\nsus párpados examinan a los hijos de los hombres."],[5,"Yahvé prueba al justo,\npero su alma aborrece al impío y al que ama la violencia."],[6,"Sobre los impíos hará llover brasas;\nfuego, azufre y viento abrasador serán la porción de su cáliz."],[7,"Porque Yahvé es justo,\ny ama la justicia;\nlos rectos contemplarán su rostro."]],"l":[]},{"i":[[0,"Al director musical; sobre la lira de ocho cuerdas. Salmo de David."],[1,"Salva, oh Yahvé, porque se acaban los piadosos;\nporque han desaparecido los fieles de entre los hijos de los hombres."],[2,"Cada uno miente a su prójimo;\nhablan con labios lisonjeros y con doblez de corazón."],[3,"Corte Yahvé todos los labios lisonjeros,\ny la lengua que habla grandezas,"],[4,"los que han dicho: «Por nuestra lengua prevaleceremos;\nnuestros labios son nuestros;\n¿quién es señor sobre nosotros?»"],[5,"«Por la opresión de los pobres, por el gemido de los menesterosos,\nahora me levantaré», dice Yahvé;\n«los pondré a salvo de quienes los desprecian»."],[6,"Las palabras de Yahvé son palabras puras,\ncomo plata refinada en horno de tierra, purificada siete veces."],[7,"Tú los guardarás, oh Yahvé;\nlos preservarás para siempre de esta generación."],[8,"Rondan los impíos por todas partes,\ncuando la vileza es exaltada entre los hijos de los hombres."]],"l":[]},{"i":[[0,"Al director musical. Salmo de David."],[1,"¿Hasta cuándo, oh Yahvé?\n¿Me olvidarás para siempre?\n¿Hasta cuándo esconderás tu rostro de mí?"],[2,"¿Hasta cuándo pondré angustia en mi alma,\nteniendo tristeza en mi corazón cada día?\n¿Hasta cuándo se enaltecerá mi enemigo sobre mí?"],[3,"Mira y respóndeme, oh Yahvé, Dios mío.\nIlumina mis ojos, para que no duerma el sueño de la muerte;"],[4,"para que mi enemigo no diga: «Lo he vencido»;\npara que mis adversarios no se alegren si yo resbalo."],[5,"Mas yo confío en tu misericordia;\nmi corazón se regocijará en tu salvación."],[6,"Cantaré a Yahvé,\nporque me ha colmado de bienes."]],"l":[]},{"i":[[0,"Al director musical. Salmo de David."],[1,"El necio ha dicho en su corazón: «No hay Dios».\nSe han corrompido,\nhan cometido hechos abominables;\nno hay quien haga el bien."],[2,"Yahvé miró desde los cielos sobre los hijos de los hombres,\npara ver si había algún entendido\nque buscara a Dios."],[3,"Todos se han desviado,\na una se han corrompido;\nno hay quien haga lo bueno, no hay ni siquiera uno."],[4,"¿No tienen conocimiento todos los hacedores de iniquidad,\nque devoran a mi pueblo como si comieran pan,\ny a Yahvé no invocan?"],[5,"Allí temblaron de espanto,\nporque Dios está con la generación de los justos."],[6,"Vosotros os burláis del consejo del pobre,\npero Yahvé es su refugio."],[7,"¡Oh, que de Sión saliera la salvación de Israel!\nCuando Yahvé restaure la suerte de su pueblo,\nse regocijará Jacob, y se alegrará Israel.",[[12,16,0]]]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Salmo de David."],[1,"Yahvé, ¿quién habitará en tu santuario?\n¿Quién morará en tu santo monte?"],[2,"El que anda en integridad y hace justicia,\ny habla verdad en su corazón;"],[3,"el que no calumnia con su lengua,\nni hace mal a su prójimo,\nni admite reproche alguno contra su vecino;"],[4,"aquel a cuyos ojos el vil es menospreciado,\npero honra a los que temen a Yahvé;\nel que, aun jurando en daño suyo, no cambia;"],[5,"el que su dinero no da a usura,\nni acepta soborno contra el inocente.\nEl que hace estas cosas jamás será conmovido."]],"l":[]},{"i":[[0,"Mictam de David."],[1,"Guárdame, oh Dios, porque en ti me refugio."],[2,"Oh alma mía, dijiste a Yahvé: «Tú eres mi Señor.\nNo hay para mí bien fuera de ti»."],[3,"Para los santos que están en la tierra,\nellos son los excelentes en quienes está toda mi complacencia."],[4,"Se multiplicarán los dolores de los que corren tras otro dios.\nNo ofreceré sus libaciones de sangre,\nni tomaré sus nombres en mis labios."],[5,"Yahvé es la porción de mi herencia y de mi copa;\ntú sustentas mi suerte."],[6,"Las cuerdas me cayeron en lugares deleitosos;\ny es hermosa la heredad que me ha tocado."],[7,"Bendeciré a Yahvé, que me aconseja;\naun por las noches me enseña mi conciencia."],[8,"A Yahvé he puesto siempre delante de mí;\nporque él está a mi diestra, no seré conmovido."],[9,"Se alegró por tanto mi corazón, y se gozó mi lengua;\nmi carne también reposará confiadamente."],[10,"Porque no dejarás mi alma en el Seol,\nni permitirás que tu santo vea corrupción."],[11,"Me mostrarás la senda de la vida;\nen tu presencia hay plenitud de gozo,\ndelicias a tu diestra para siempre."]],"l":[]},{"i":[[0,"Oración de David."],[1,"Escucha, oh Yahvé, mi justa causa; atiende a mi clamor.\nPresta oído a mi oración, que no sale de labios engañosos."],[2,"De tu presencia proceda mi sentencia;\nmiren tus ojos la rectitud."],[3,"Tú has probado mi corazón, me has visitado de noche;\nme has puesto a prueba y nada malo hallaste;\nhe resuelto que mi boca no trasgreda."],[4,"En cuanto a las obras humanas, por la palabra de tus labios\nyo me he guardado de las sendas del violento."],[5,"Mis pasos se han mantenido firmes en tus caminos,\npara que mis pies no resbalen."],[6,"Yo te he invocado, por cuanto tú me oirás, oh Dios;\ninclina a mí tu oído, escucha mi palabra."],[7,"Muestra tus maravillosas misericordias,\ntú que salvas a los que se refugian a tu diestra de los que se levantan contra ellos."],[8,"Guárdame como a la niña de tus ojos;\nescóndeme bajo la sombra de tus alas,"],[9,"de la vista de los impíos que me oprimen,\nde mis enemigos mortales que me rodean."],[10,"Cerrados están en su propia gordura;\ncon su boca hablan con soberbia."],[11,"Han cercado ahora nuestros pasos;\nhan puesto sus ojos para derribarnos a tierra."],[12,"Son como leones ávidos de presa,\ncomo cachorros de león que acechan en escondrijos."],[13,"Levántate, oh Yahvé, sal a su encuentro, póstrales;\nlibra mi alma del impío con tu espada,"],[14,"de los hombres, con tu mano, oh Yahvé,\nde los hombres de este mundo, cuya porción está en esta vida,\ncuyo vientre llenas de tus tesoros.\nSus hijos se sacian,\ny dejan lo que les sobra a sus pequeñuelos."],[15,"En cuanto a mí, veré tu rostro en justicia;\nme saciaré cuando despierte a tu semejanza."]],"l":[]},{"i":[[0,"Al director musical. De David, siervo de Yahvé, el cual dirigió a Yahvé las palabras de este cántico el día en que Yahvé le libró de mano de todos sus enemigos, y de mano de Saúl. Dijo:"],[1,"Te amo, oh Yahvé, fortaleza mía."],[2,"Yahvé, roca mía y castillo mío, y mi libertador;\nDios mío, fortaleza mía, en él confiaré;\nmi escudo, y el cuerno de mi salvación, mi alto refugio."],[3,"Invocaré a Yahvé, que es digno de ser alabado,\ny seré salvo de mis enemigos."],[4,"Me rodearon ligaduras de muerte,\ny torrentes de perversidad me atemorizaron."],[5,"Ligaduras del Seol me rodearon,\nme tendieron lazos de muerte."],[6,"En mi angustia invoqué a Yahvé,\ny clamé a mi Dios.\nÉl oyó mi voz desde su templo,\ny mi clamor llegó delante de él, a sus oídos."],[7,"La tierra fue conmovida y tembló;\nse conmovieron los cimientos de los montes,\ny se estremecieron, porque se encendió su ira."],[8,"Humo subió de su nariz,\ny de su boca fuego consumidor;\ncarbones fueron por él encendidos."],[9,"Inclinó los cielos, y descendió;\ny había densas tinieblas debajo de sus pies."],[10,"Cabalgó sobre un querubín, y voló;\nvoló sobre las alas del viento."],[11,"Puso tinieblas por su escondedero, por cortina suya en derredor de sí;\noscuridad de aguas, nubes de los cielos."],[12,"Por el resplandor de su presencia, sus nubes pasaron;\ngranizo y carbones de fuego."],[13,"Tronó en los cielos Yahvé,\ny el Altísimo dio su voz;\ngranizo y carbones de fuego."],[14,"Envió sus saetas, y los dispersó;\nlanzó relámpagos, y los destruyó."],[15,"Entonces aparecieron los cauces de las aguas,\ny quedaron al descubierto los cimientos del mundo,\na tu reprensión, oh Yahvé, por el soplo del aliento de tu nariz."],[16,"Envió desde lo alto; me tomó,\nme sacó de las muchas aguas."],[17,"Me libró de mi vigoroso enemigo,\ny de los que me aborrecían; pues eran más fuertes que yo."],[18,"Me asaltaron en el día de mi quebranto,\nmas Yahvé fue mi apoyo."],[19,"Me sacó a lugar espacioso;\nme libró, porque se agradó de mí."],[20,"Yahvé me ha premiado conforme a mi justicia;\nconforme a la limpieza de mis manos me ha recompensado."],[21,"Porque yo he guardado los caminos de Yahvé,\ny no me aparté impíamente de mi Dios."],[22,"Pues todos sus juicios estuvieron delante de mí,\ny no he apartado de mí sus estatutos."],[23,"Fui recto para con él,\ny me guardé de mi iniquidad."],[24,"Por lo cual me ha recompensado Yahvé conforme a mi justicia;\nconforme a la limpieza de mis manos delante de sus ojos."],[25,"Con el misericordioso te mostrarás misericordioso,\ny recto para con el hombre íntegro."],[26,"Limpio te mostrarás para con el limpio,\ny severo serás para con el perverso."],[27,"Porque tú salvarás al pueblo afligido,\ny humillarás los ojos altivos."],[28,"Tú encenderás mi lámpara;\nYahvé mi Dios alumbrará mis tinieblas."],[29,"Contigo desbarataré ejércitos,\ny con mi Dios asaltaré muros."],[30,"En cuanto a Dios, perfecto es su camino,\ny acendrada la palabra de Yahvé;\nescudo es a todos los que en él esperan."],[31,"Porque ¿quién es Dios sino solo Yahvé?\n¿Y qué roca hay fuera de nuestro Dios?"],[32,"Dios es el que me ciñe de fuerza,\ny quien hace perfecto mi camino;"],[33,"quien hace mis pies como de ciervas,\ny me hace estar firme sobre mis alturas;"],[34,"quien adiestra mis manos para la batalla,\npara entesar con mis brazos el arco de bronce."],[35,"Me diste asimismo el escudo de tu salvación;\ntu diestra me sustentó,\ny tu benignidad me ha engrandecido."],[36,"Ensanchaste mis pasos debajo de mí,\ny mis pies no han resbalado."],[37,"Perseguí a mis enemigos, y los alcancé,\ny no volví hasta acabarlos."],[38,"Los herí de modo que no pudiesen levantarse;\ncayeron debajo de mis pies."],[39,"Pues me ceñiste de fuerzas para la pelea;\nhas humillado a mis enemigos debajo de mí."],[40,"Hiciste que mis enemigos me volviesen las espaldas,\npara que yo destruyese a los que me aborrecían."],[41,"Clamaron, y no hubo quien salvase;\naun a Yahvé, pero no los oyó."],[42,"Y los molí como polvo delante del viento;\nlos eché como lodo de las calles."],[43,"Me has librado de las contiendas del pueblo;\nme has hecho cabeza de las naciones;\npueblo que yo no conocía me sirvió."],[44,"Al oír de mí me obedecieron;\nlos hijos de extraños se sometieron a mí."],[45,"Los extraños desmayaron\ny salieron temblando de sus encierros."],[46,"¡Vive Yahvé, y bendita sea mi roca,\ny enaltecido sea el Dios de mi salvación!"],[47,"El Dios que por mí ejecuta venganza,\ny somete pueblos debajo de mí;"],[48,"que me libra de mis enemigos,\ny aun me eleva sobre los que se levantan contra mí;\nme libraste de varón violento."],[49,"Por tanto yo te confesaré entre las naciones, oh Yahvé,\ny cantaré a tu nombre."],[50,"Él salva gloriosamente a su rey,\ny hace misericordia a su ungido,\na David y a su descendencia para siempre."]],"l":[]},{"i":[[0,"Al director musical. Salmo de David."],[1,"Los cielos cuentan la gloria de Dios;\nel firmamento anuncia la obra de sus manos."],[2,"Un día emite palabra a otro día,\ny una noche a otra noche declara sabiduría."],[3,"No hay lenguaje, ni palabras,\ndonde no se escuche su voz."],[4,"Por toda la tierra salió su eco,\ny hasta el extremo del mundo sus palabras.\nEn ellos puso un tabernáculo para el sol,"],[5,"y este, como un esposo que sale de su tálamo,\nse regocija como un gigante para correr su camino."],[6,"De un extremo de los cielos es su salida,\ny su curso hasta el término de ellos;\ny nada hay que se esconda de su calor."],[7,"La ley de Yahvé es perfecta, que restaura el alma;\nel testimonio de Yahvé es fiel, que hace sabio al sencillo."],[8,"Los mandamientos de Yahvé son rectos, que alegran el corazón;\nel precepto de Yahvé es puro, que alumbra los ojos."],[9,"El temor de Yahvé es limpio, que permanece para siempre;\nlos juicios de Yahvé son verdad, todos justos."],[10,"Deseables son más que el oro, y más que mucho oro afinado;\ny dulces más que miel, y que la que destila del panal."],[11,"Tu siervo es además amonestado por ellos;\nen guardarlos hay grande galardón."],[12,"¿Quién podrá entender sus propios errores?\nLíbrame de los que me son ocultos."],[13,"Preserva también a tu siervo de las soberbias;\nque no se enseñoreen de mí.\nEntonces seré íntegro,\ny estaré limpio de gran rebelión."],[14,"Sean gratas las palabras de mi boca y la meditación de mi corazón\ndelante de ti,\noh Yahvé, roca mía, y redentor mío."]],"l":[]},{"i":[[0,"Al director musical. Salmo de David."],[1,"Que Yahvé te responda en el día de la angustia;\nque el nombre del Dios de Jacob te defienda,"],[2,"te envíe ayuda desde el santuario,\ny desde Sión te sostenga.",[[43,47,0]]],[3,"Recuerde todas tus ofrendas,\ny acepte tu holocausto. Selah."],[4,"Te conceda el deseo de tu corazón,\ny cumpla todo tu consejo."],[5,"Nosotros nos alegraremos en tu salvación,\ny alzaremos pendón en el nombre de nuestro Dios.\nQue Yahvé conceda todas tus peticiones."],[6,"Ahora conozco que Yahvé salva a su ungido;\nlo oirá desde sus santos cielos,\ncon la fuerza salvadora de su diestra."],[7,"Estos confían en carros, y aquellos en caballos;\nmas nosotros del nombre de Yahvé nuestro Dios tendremos memoria."],[8,"Ellos flaquean y caen,\nmas nosotros nos levantamos y nos mantenemos en pie."],[9,"¡Salva, oh Yahvé!\nQue el Rey nos escuche en el día que le invoquemos."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Al director musical. Salmo de David."],[1,"El rey se alegra en tu poder, oh Yahvé;\n¡y en tu salvación, cómo se regocija!"],[2,"Le has concedido el deseo de su corazón,\ny no le has negado la petición de sus labios. Selah."],[3,"Pues le sales al encuentro con bendiciones de bien;\ncorona de oro fino has puesto sobre su cabeza."],[4,"Vida te pidió, y se la diste;\nlargura de días eternamente y para siempre."],[5,"Grande es su gloria por tu salvación;\nhonra y majestad has puesto sobre él."],[6,"Porque lo has hecho bendición para siempre;\nlo llenas de gozo con tu presencia."],[7,"Por cuanto el rey confía en Yahvé,\ny en la misericordia del Altísimo, no será conmovido."],[8,"Alcanzará tu mano a todos tus enemigos;\ntu diestra alcanzará a los que te aborrecen."],[9,"Los pondrás como horno de fuego en el tiempo de tu ira;\nYahvé los deshará en su furor,\ny fuego los consumirá."],[10,"Destruirás su fruto de la tierra,\ny su simiente de entre los hijos de los hombres."],[11,"Porque intentaron el mal contra ti;\nfraguaron maquinaciones, mas no prevalecerán."],[12,"Pues tú los pondrás en fuga,\ncuando prepares tus saetas contra sus rostros."],[13,"Engrandécete, oh Yahvé, en tu poder;\ncantaremos y alabaremos tu poderío."]],"l":[]},{"i":[[0,"Al director musical; sobre «Ajelet-sahar». Salmo de David."],[1,"Dios mío, Dios mío, ¿por qué me has desamparado?\n¿Por qué estás tan lejos de mi salvación, y de las palabras de mi clamor?"],[2,"Dios mío, clamo de día, y no respondes;\ny de noche, y no hay para mí reposo."],[3,"Pero tú eres santo,\ntú que habitas entre las alabanzas de Israel."],[4,"En ti esperaron nuestros padres;\nesperaron, y tú los libraste."],[5,"Clamaron a ti, y fueron librados;\nconfiaron en ti, y no fueron avergonzados."],[6,"Mas yo soy gusano, y no hombre;\noprobio de los hombres, y despreciado del pueblo."],[7,"Todos los que me ven me escarnecen;\nestiran los labios, menean la cabeza, diciendo:"],[8,"«Se encomendó a Yahvé; líbrele él;\nsálvele, puesto que en él se complacía»."],[9,"Pero tú eres el que me sacó del vientre;\nel que me hizo estar confiado desde que estaba a los pechos de mi madre."],[10,"Sobre ti fui echado desde antes de nacer;\ndesde el vientre de mi madre, tú eres mi Dios."],[11,"No te alejes de mí, porque la angustia está cerca;\nporque no hay quien ayude."],[12,"Me han rodeado muchos toros;\nfuertes toros de Basán me han cercado.",[[46,51,0]]],[13,"Abrieron sobre mí su boca\ncomo león rapaz y rugiente."],[14,"He sido derramado como aguas,\ny todos mis huesos se descoyuntaron;\nmi corazón fue como cera,\nderritiéndose en medio de mis entrañas."],[15,"Como un tiesto se secó mi vigor,\ny mi lengua se pegó a mi paladar,\ny me has puesto en el polvo de la muerte."],[16,"Porque perros me han rodeado;\nme ha cercado cuadrilla de malignos;\nhoradaron mis manos y mis pies."],[17,"Contar puedo todos mis huesos;\nentre tanto, ellos me miran y me observan."],[18,"Repartieron entre sí mis vestidos,\ny sobre mi ropa echaron suertes."],[19,"Mas tú, Yahvé, no te alejes;\nfortaleza mía, apresúrate a socorrerme."],[20,"Libra de la espada mi alma,\ndel poder del perro mi vida."],[21,"Sálvame de la boca del león,\ny líbrame de los cuernos de los búfalos."],[22,"Anunciaré tu nombre a mis hermanos;\nen medio de la congregación te alabaré."],[23,"Los que teméis a Yahvé, alabadle;\nglorificadle, linaje todo de Jacob,\ny temedle vosotros, descendencia toda de Israel."],[24,"Porque no menospreció ni abominó la aflicción del afligido,\nni de él escondió su rostro;\nsino que cuando clamó a él, le oyó."],[25,"De ti será mi alabanza en la gran congregación;\nmis votos pagaré delante de los que le temen."],[26,"Comerán los humildes, y serán saciados;\nalabarán a Yahvé los que le buscan;\nvivirá vuestro corazón para siempre."],[27,"Se acordarán, y se volverán a Yahvé todos los confines de la tierra,\ny todas las familias de las naciones adorarán delante de ti."],[28,"Porque de Yahvé es el reino,\ny él regirá las naciones."],[29,"Comerán y adorarán todos los poderosos de la tierra;\nse postrarán delante de él todos los que descienden al polvo,\naun el que no puede conservar la vida a su propia alma."],[30,"La posteridad le servirá;\nserá contada a Yahvé la venidera generación."],[31,"Vendrán, y anunciarán su justicia;\na pueblo no nacido aún, anunciarán que él hizo esto."]],"l":[[154,"Basán",32.80007,35.9373]]},{"i":[[0,"Salmo de David."],[1,"Yahvé es mi pastor;\nnada me faltará."],[2,"En lugares de delicados pastos me hará descansar;\njunto a aguas de reposo me pastoreará."],[3,"Él conforta mi alma;\nme guía por sendas de justicia por amor de su nombre."],[4,"Aunque ande en valle de sombra de muerte,\nno temeré mal alguno, porque tú estarás conmigo.\nTu vara y tu cayado\nme infundirán aliento."],[5,"Aderezas mesa delante de mí\nen presencia de mis enemigos.\nUnges mi cabeza con aceite;\nmi copa está rebosando."],[6,"Ciertamente el bien y la misericordia me seguirán todos los días de mi vida,\ny en la casa de Yahvé moraré para siempre."]],"l":[]},{"i":[[0,"Salmo de David."],[1,"De Yahvé es la tierra y su plenitud;\nel mundo, y los que en él habitan."],[2,"Porque él la fundó sobre los mares,\ny la afirmó sobre los ríos."],[3,"¿Quién subirá al monte de Yahvé?\n¿Y quién estará en su lugar santo?"],[4,"El limpio de manos y puro de corazón;\nel que no ha elevado su alma a cosas vanas,\nni jurado con engaño."],[5,"Él recibirá bendición de Yahvé,\ny justicia del Dios de su salvación."],[6,"Tal es la generación de los que le buscan,\nde los que buscan tu rostro, oh Dios de Jacob. Selah."],[7,"Alzad, oh puertas, vuestras cabezas,\ny alzaos vosotras, puertas eternas,\ny entrará el Rey de gloria."],[8,"¿Quién es este Rey de gloria?\nYahvé el fuerte y valiente,\nYahvé el poderoso en batalla."],[9,"Alzad, oh puertas, vuestras cabezas,\nsí, alzaos, puertas eternas,\ny entrará el Rey de gloria."],[10,"¿Quién es este Rey de gloria?\n¡Yahvé de los ejércitos,\nél es el Rey de la gloria! Selah."]],"l":[]},{"i":[[0,"De David."],[1,"A ti, oh Yahvé, elevo mi alma."],[2,"Dios mío, en ti he confiado;\nno sea yo avergonzado,\nno se alegren de mí mis enemigos."],[3,"Ciertamente ninguno de cuantos en ti esperan será confundido;\nserán avergonzados los que se rebelan sin causa."],[4,"Muéstrame, oh Yahvé, tus caminos;\nenséñame tus sendas."],[5,"Encamíname en tu verdad, y enséñame,\nporque tú eres el Dios de mi salvación;\nen ti he esperado todo el día."],[6,"Acuérdate, oh Yahvé, de tus piedades y de tus misericordias,\nporque son perpetuas."],[7,"De los pecados de mi juventud, y de mis rebeliones, no te acuerdes;\nconforme a tu misericordia acuérdate de mí,\npor tu bondad, oh Yahvé."],[8,"Bueno y recto es Yahvé;\npor tanto, él enseñará a los pecadores el camino."],[9,"Encaminará a los humildes por la justicia,\ny enseñará a los mansos su carrera."],[10,"Todas las sendas de Yahvé son misericordia y verdad,\npara los que guardan su pacto y sus testimonios."],[11,"Por amor de tu nombre, oh Yahvé,\nperdonarás también mi pecado, que es grande."],[12,"¿Quién es el hombre que teme a Yahvé?\nÉl le enseñará el camino que ha de escoger."],[13,"Su alma reposará en el bien,\ny su descendencia heredará la tierra."],[14,"La comunión íntima de Yahvé es con los que le temen,\ny a ellos hará conocer su pacto."],[15,"Mis ojos están siempre hacia Yahvé,\nporque él sacará mis pies de la red."],[16,"Mírame, y ten misericordia de mí,\nporque estoy desolado y afligido."],[17,"Las angustias de mi corazón se han aumentado;\nsácame de mis congojas."],[18,"Mira mi aflicción y mi trabajo,\ny perdona todos mis pecados."],[19,"Mira mis enemigos, cómo se han multiplicado,\ny con odio violento me aborrecen."],[20,"Guarda mi alma, y líbrame;\nno sea yo avergonzado, porque en ti confié."],[21,"La integridad y la rectitud me guarden,\nporque en ti he esperado."],[22,"Redime, oh Dios, a Israel,\nde todas sus angustias."]],"l":[]},{"i":[[0,"De David."],[1,"Júzgame, oh Yahvé, porque en mi integridad he andado;\nhe confiado asimismo en Yahvé sin titubear."],[2,"Escudríñame, oh Yahvé, y pruébame;\nexamina mis íntimos pensamientos y mi corazón."],[3,"Porque tu misericordia está delante de mis ojos,\ny ando en tu verdad."],[4,"No me he sentado con hombres falsos,\nni me juntaré con los hipócritas."],[5,"Aborrezco la reunión de los malignos,\ny con los impíos no me sentaré."],[6,"Lavaré en inocencia mis manos,\ny andaré alrededor de tu altar, oh Yahvé,"],[7,"para hacer oír la voz de acción de gracias,\ny para contar todas tus maravillas."],[8,"Yahvé, la habitación de tu casa he amado,\ny el lugar de la morada de tu gloria."],[9,"No arrebates mi alma con los pecadores,\nni mi vida con hombres sanguinarios,"],[10,"en cuyas manos hay iniquidad;\ny cuya diestra está llena de sobornos."],[11,"Mas yo andaré en mi integridad;\nredímeme, y ten misericordia de mí."],[12,"Mi pie está firme en la rectitud;\nen las congregaciones bendeciré a Yahvé."]],"l":[]},{"i":[[0,"De David."],[1,"Yahvé es mi luz y mi salvación;\n¿a quién temeré?\nYahvé es la fortaleza de mi vida;\n¿de quién he de atemorizarme?"],[2,"Cuando se acercaron a mí los malignos para devorar mis carnes,\nmis adversarios y mis enemigos, ellos tropezaron y cayeron."],[3,"Aunque un ejército acampe contra mí,\nno temerá mi corazón;\naunque contra mí se levante guerra,\nyo estaré confiado."],[4,"Una cosa he demandado a Yahvé, esta buscaré:\nque esté yo en la casa de Yahvé todos los días de mi vida,\npara contemplar la hermosura de Yahvé,\ny para inquirir en su templo."],[5,"Porque él me esconderá en su tabernáculo en el día del mal;\nme ocultará en lo reservado de su morada;\nsobre una roca me pondrá en alto."],[6,"Y ahora levantará mi cabeza sobre mis enemigos que me rodean;\ny yo sacrificaré en su tabernáculo sacrificios de júbilo;\ncantaré y entonaré alabanzas a Yahvé."],[7,"Oye, oh Yahvé, mi voz con que a ti clamo;\nten misericordia de mí, y respóndeme."],[8,"Mi corazón ha dicho de ti: «Buscad mi rostro».\nTu rostro buscaré, oh Yahvé."],[9,"No escondas tu rostro de mí;\nno apartes con ira a tu siervo.\nMi ayuda has sido;\nno me dejes\nni me desampares, Dios de mi salvación."],[10,"Aunque mi padre y mi madre me dejaran,\ncon todo, Yahvé me recogerá."],[11,"Enséñame, oh Yahvé, tu camino,\ny guíame por senda de rectitud a causa de mis enemigos."],[12,"No me entregues a la voluntad de mis enemigos;\nporque se han levantado contra mí testigos falsos,\ny los que respiran crueldad."],[13,"Hubiera yo desmayado, si no creyese que\nveré la bondad de Yahvé en la tierra de los vivientes."],[14,"Aguarda a Yahvé;\nesfuérzate, y aliéntese tu corazón;\nsí, espera a Yahvé."]],"l":[]},{"i":[[0,"De David."],[1,"A ti clamo, oh Yahvé.\nRoca mía, no guardes silencio para conmigo;\nno sea que, si te callas ante mí,\nsea yo semejante a los que descienden al sepulcro."],[2,"Oye la voz de mis ruegos cuando clamo a ti,\ncuando alzo mis manos hacia tu santuario."],[3,"No me arrebates juntamente con los impíos,\ny con los hacedores de iniquidad, que hablan de paz con su prójimo,\npero la maldad está en su corazón."],[4,"Dales conforme a su obra, y conforme a la perversidad de sus hechos;\ndales conforme a la obra de sus manos.\nDales su merecido."],[5,"Por cuanto no atendieron a los hechos de Yahvé,\nni a la obra de sus manos,\nél los derribará, y no los edificará."],[6,"Bendito sea Yahvé,\nporque ha oído la voz de mis ruegos."],[7,"Yahvé es mi fortaleza y mi escudo;\nen él confió mi corazón, y fui ayudado,\npor lo que se gozó mi corazón.\nY con mi cántico le alabaré."],[8,"Yahvé es la fortaleza de su pueblo,\ny el refugio salvador de su ungido."],[9,"Salva a tu pueblo,\ny bendice a tu heredad.\nPastoréalos también,\ny enaltécelos para siempre."]],"l":[]},{"i":[[0,"Salmo de David."],[1,"Tributad a Yahvé, oh hijos de los poderosos,\ntributad a Yahvé la gloria y el poder."],[2,"Tributad a Yahvé la gloria debida a su nombre;\nadorad a Yahvé en la hermosura de la santidad."],[3,"Voz de Yahvé sobre las aguas;\ntruena el Dios de gloria, Yahvé sobre las muchas aguas."],[4,"La voz de Yahvé es potente;\nla voz de Yahvé es llena de majestad."],[5,"La voz de Yahvé quiebra los cedros;\nsí, Yahvé quiebra en pedazos los cedros del Líbano.",[[80,86,0]]],[6,"Los hace saltar como becerros;\nal Líbano y al Sirión como hijos de búfalo.",[[34,40,0],[46,52,1]]],[7,"La voz de Yahvé derrama llamas de fuego."],[8,"La voz de Yahvé hace temblar el desierto;\nhace temblar Yahvé el desierto de Cades.",[[76,81,2]]],[9,"La voz de Yahvé hace parir a las ciervas,\ny desnuda los bosques.\nEn su templo todo proclama: «¡Gloria!»"],[10,"Yahvé preside en el diluvio,\ny se sienta Yahvé como Rey para siempre."],[11,"Yahvé dará poder a su pueblo;\nYahvé bendecirá a su pueblo con paz."]],"l":[[707,"Líbano",33.75248,35.5908],[1079,"Sirión",33.41616,35.85726],[646,"Cades",30.68771,34.4948]]},{"i":[[0,"Salmo. Cántico para la dedicación de la Casa. De David."],[1,"Te exaltaré, oh Yahvé, porque me has levantado,\ny no permitiste que mis enemigos se burlaran de mí."],[2,"Yahvé Dios mío, a ti clamé,\ny tú me sanaste."],[3,"Oh Yahvé, hiciste subir mi alma del Seol;\nme diste vida, para que no descendiera a la fosa."],[4,"Cantad a Yahvé, vosotros sus santos,\ny dad gracias a su santo nombre."],[5,"Porque un momento dura su ira,\npero su favor es para toda la vida.\nPor la noche durará el lloro,\ny a la mañana vendrá la alegría."],[6,"En cuanto a mí, en mi prosperidad dije:\n«Jamás seré conmovido»."],[7,"Tú, oh Yahvé, por tu favor afirmaste mi monte;\npero escondiste tu rostro, y fui turbado."],[8,"A ti, oh Yahvé, clamé,\ny al Señor hice mi súplica:"],[9,"“¿Qué provecho hay en mi sangre, si desciendo a la fosa?\n¿Te alabará el polvo?\n¿Anunciará tu verdad?"],[10,"Escucha, oh Yahvé, y ten misericordia de mí;\noh Yahvé, sé tú mi socorro”."],[11,"Has cambiado mi lamento en baile;\nme quitaste el cilicio y me ceñiste de alegría,"],[12,"para que mi alma te cante alabanzas y no calle.\nOh Yahvé, Dios mío, te daré gracias para siempre."]],"l":[]},{"i":[[0,"Al director musical. Salmo de David."],[1,"En ti, oh Yahvé, me he refugiado;\nno sea yo avergonzado jamás;\nlíbrame en tu justicia."],[2,"Inclina a mí tu oído,\nlíbrame pronto;\nsé tú mi roca fuerte,\ny fortaleza para salvarme."],[3,"Porque tú eres mi roca y mi castillo;\npor tu nombre me guiarás y me encaminarás."],[4,"Sácame de la red que han escondido para mí,\npues tú eres mi refugio."],[5,"En tu mano encomiendo mi espíritu;\ntú me has redimido, oh Yahvé, Dios de verdad."],[6,"Aborrezco a los que esperan en ídolos vanos;\nmas yo en Yahvé he confiado."],[7,"Me gozaré y alegraré en tu misericordia,\nporque has visto mi aflicción;\nhas conocido mi alma en las angustias."],[8,"No me entregaste en mano del enemigo;\npusiste mis pies en lugar espacioso."],[9,"Ten misericordia de mí, oh Yahvé, porque estoy en angustia;\nse han consumido de tristeza mis ojos, mi alma también y mi cuerpo."],[10,"Porque mi vida se va gastando de dolor,\ny mis años de suspirar;\nse agotan mis fuerzas a causa de mi iniquidad,\ny mis huesos se han consumido."],[11,"De todos mis enemigos soy el oprobio,\ny de mis vecinos mucho más, y el horror de mis conocidos;\nlos que me ven en la calle huyen de mí."],[12,"He sido olvidado de su corazón como un muerto;\nhe venido a ser como una vasija quebrada."],[13,"Porque oigo la calumnia de muchos; el miedo me rodea,\nmientras consultan juntos contra mí\ne idean quitarme la vida."],[14,"Mas yo en ti confío, oh Yahvé;\ndigo: «Tú eres mi Dios»."],[15,"En tu mano están mis tiempos;\nlíbrame de la mano de mis enemigos y de mis perseguidores."],[16,"Haz resplandecer tu rostro sobre tu siervo;\nsálvame por tu misericordia."],[17,"No sea yo avergonzado, oh Yahvé, ya que te he invocado;\nsean avergonzados los impíos,\nestén mudos en el Seol."],[18,"Enmudezcan los labios mentirosos,\nque hablan contra el justo cosas duras con soberbia y desprecio."],[19,"¡Cuán grande es tu bondad,\nque has guardado para los que te temen,\nque has mostrado a los que esperan en ti,\ndelante de los hijos de los hombres!"],[20,"En lo secreto de tu presencia los esconderás de la conspiración del hombre;\nlos pondrás en un tabernáculo a cubierto de contención de lenguas."],[21,"Bendito sea Yahvé,\nporque ha hecho maravillosa su misericordia para conmigo en ciudad fortificada."],[22,"Decía yo en mi premura: «Cortado soy de delante de tus ojos»;\npero tú oíste la voz de mis ruegos cuando a ti clamaba."],[23,"Amad a Yahvé, todos vosotros sus santos;\na los fieles guarda Yahvé,\ny paga abundantemente al que procede con soberbia."],[24,"Esforzaos todos vosotros los que esperáis en Yahvé,\ny tome aliento vuestro corazón."]],"l":[]},{"i":[[0,"De David. Masquil."],[1,"Bienaventurado aquel cuya transgresión ha sido perdonada,\ny cubierto su pecado."],[2,"Bienaventurado el hombre a quien Yahvé no culpa de iniquidad,\ny en cuyo espíritu no hay engaño."],[3,"Mientras callé, se envejecieron mis huesos\nen mi gemir todo el día."],[4,"Porque de día y de noche se agravó sobre mí tu mano;\nse volvió mi verdor en sequedades de verano. Selah."],[5,"Mi pecado te declaré,\ny no encubrí mi iniquidad.\nDije: «Confesaré mis transgresiones a Yahvé»;\ny tú perdonaste la maldad de mi pecado. Selah."],[6,"Por esto orará a ti todo santo en el tiempo en que puedas ser hallado;\nciertamente en la inundación de muchas aguas no llegarán estas a él."],[7,"Tú eres mi refugio;\nme guardarás de la angustia;\ncon cánticos de liberación me rodearás. Selah."],[8,"Te haré entender, y te enseñaré el camino en que debes andar;\nsobre ti fijaré mis ojos."],[9,"No seáis como el caballo, o como el mulo, sin entendimiento,\nque han de ser sujetados con cabestro y con freno,\nporque si no, no se acercan a ti."],[10,"Muchos dolores habrá para el impío;\nmas al que espera en Yahvé, le rodea la misericordia."],[11,"Alegraos en Yahvé y gozaos, justos;\ny cantad con júbilo todos vosotros los rectos de corazón."]],"l":[]},{"i":[[1,"Alegraos, oh justos, en Yahvé;\na los rectos es hermosa la alabanza."],[2,"Aclamad a Yahvé con arpa;\ncantadle con salterio y decacordio."],[3,"Cantadle cántico nuevo;\nhacedlo bien, tañendo con júbilo."],[4,"Porque recta es la palabra de Yahvé,\ny toda su obra es hecha con fidelidad."],[5,"Él ama la justicia y el derecho;\nde la misericordia de Yahvé está llena la tierra."],[6,"Por la palabra de Yahvé fueron hechos los cielos,\ny todo el ejército de ellos por el aliento de su boca."],[7,"Él junta como montón las aguas del mar;\nél pone en depósitos los abismos."],[8,"Tema a Yahvé toda la tierra;\nteman delante de él todos los habitantes del mundo."],[9,"Porque él dijo, y fue hecho;\nél mandó, y existió."],[10,"Yahvé hace nulo el consejo de las naciones,\ny frustra las maquinaciones de los pueblos."],[11,"El consejo de Yahvé permanecerá para siempre;\nlos pensamientos de su corazón por todas las generaciones."],[12,"Bienaventurada la nación cuyo Dios es Yahvé,\nel pueblo que él escogió como heredad para sí."],[13,"Desde los cielos miró Yahvé;\nvio a todos los hijos de los hombres."],[14,"Desde el lugar de su morada miró\nsobre todos los moradores de la tierra."],[15,"Él formó el corazón de todos ellos;\natento está a todas sus obras."],[16,"El rey no se salva por la multitud del ejército,\nni escapa el valiente por la mucha fuerza."],[17,"Vano para salvarse es el caballo;\nla grandeza de su poder a nadie podrá librar."],[18,"He aquí el ojo de Yahvé sobre los que le temen,\nsobre los que esperan en su misericordia,"],[19,"para librar sus almas de la muerte,\ny para darles vida en tiempo de hambre."],[20,"Nuestra alma espera a Yahvé;\nnuestra ayuda y nuestro escudo es él."],[21,"Por tanto, en él se alegrará nuestro corazón,\nporque en su santo nombre hemos confiado."],[22,"Sea tu misericordia, oh Yahvé, sobre nosotros,\nsegún esperamos en ti."]],"l":[]},{"i":[[0,"Salmo de David, cuando mudó su semblante delante de Abimelec, y él lo echó, y se fue."],[1,"Bendeciré a Yahvé en todo tiempo;\nsu alabanza estará de continuo en mi boca."],[2,"En Yahvé se gloriará mi alma;\nlo oirán los mansos, y se alegrarán."],[3,"Engrandeced a Yahvé conmigo,\ny exaltemos a una su nombre."],[4,"Busqué a Yahvé, y él me oyó,\ny me libró de todos mis temores."],[5,"Los que miraron a él fueron alumbrados,\ny sus rostros no fueron avergonzados."],[6,"Este pobre clamó, y le oyó Yahvé,\ny lo libró de todas sus angustias."],[7,"El ángel de Yahvé acampa alrededor de los que le temen,\ny los defiende."],[8,"Gustad, y ved que es bueno Yahvé;\ndichoso el hombre que confía en él."],[9,"Temed a Yahvé, vosotros sus santos,\npues nada falta a los que le temen."],[10,"Los leoncillos necesitan y tienen hambre;\npero los que buscan a Yahvé no tendrán falta de ningún bien."],[11,"Venid, hijos, oídme;\nel temor de Yahvé os enseñaré."],[12,"¿Quién es el hombre que desea vida,\nque anhela muchos días para ver el bien?"],[13,"Guarda tu lengua del mal,\ny tus labios de hablar engaño."],[14,"Apártate del mal, y haz el bien;\nbusca la paz, y síguela."],[15,"Los ojos de Yahvé están sobre los justos,\ny atentos sus oídos al clamor de ellos."],[16,"La ira de Yahvé está contra los que hacen mal,\npara raer de la tierra su memoria."],[17,"Claman los justos, y Yahvé oye,\ny los libra de todas sus angustias."],[18,"Cercano está Yahvé a los quebrantados de corazón;\ny salva a los contritos de espíritu."],[19,"Muchas son las aflicciones del justo,\npero de todas ellas le librará Yahvé."],[20,"Él guarda todos sus huesos;\nni uno de ellos será quebrantado."],[21,"Matará al malo la maldad,\ny los que aborrecen al justo serán asolados."],[22,"Yahvé redime el alma de sus siervos,\ny no serán asolados cuantos en él confían."]],"l":[]},{"i":[[0,"De David."],[1,"Contiende, oh Yahvé, con los que contienden conmigo;\npelea contra los que me atacan."],[2,"Echa mano al escudo y al pavés,\ny levántate en mi ayuda."],[3,"Saca la lanza, cierra el paso a mis perseguidores;\ndi a mi alma: «Yo soy tu salvación»."],[4,"Sean avergonzados y confundidos los que buscan mi vida;\nsean vueltos atrás y avergonzados los que mi mal intentan."],[5,"Sean como el tamo delante del viento,\ny el ángel de Yahvé los acose."],[6,"Sea su camino tenebroso y resbaladizo,\ny el ángel de Yahvé los persiga."],[7,"Porque sin causa escondieron para mí su red en un hoyo;\nsin causa cavaron fosa para mi alma."],[8,"Venga sobre él destrucción sin que lo sepa,\ny la red que él escondió lo atrape;\ncon ruina caiga en ella."],[9,"Y mi alma se alegrará en Yahvé;\nse regocijará en su salvación."],[10,"Todos mis huesos dirán: “Yahvé, ¿quién como tú,\nque libras al afligido del más fuerte que él,\ny al pobre y menesteroso del que le despoja?”"],[11,"Se levantan testigos falsos;\nde lo que no sé me preguntan."],[12,"Me devuelven mal por bien,\npara aflicción de mi alma."],[13,"Pero yo, cuando ellos enfermaron, me vestí de cilicio;\nafligí con ayuno mi alma,\ny mi oración se volvía a mi seno."],[14,"Como por mi amigo, como por mi hermano andaba;\ncomo el que llora por su madre, enlutado me humillaba."],[15,"Pero ellos se alegraron en mi adversidad, y se juntaron;\nse juntaron contra mí gentes despreciables, y yo no lo entendía;\nme despedazaban sin cesar."],[16,"Como lisonjeros, escarnecedores y truhanes,\ncrujieron contra mí sus dientes."],[17,"Señor, ¿hasta cuándo verás esto?\nRescata mi alma de sus destrucciones,\nmi vida de los leones."],[18,"Te confesaré en la gran congregación;\nte alabaré entre numeroso pueblo."],[19,"No se alegren de mí los que sin causa son mis enemigos,\nni los que me aborrecen sin razón hagan guiños."],[20,"Porque no hablan paz;\ny contra los mansos de la tierra piensan palabras engañosas."],[21,"Ensancharon contra mí su boca;\ndijeron: «¡Ea, ea, nuestros ojos lo han visto!»"],[22,"Tú lo has visto, oh Yahvé; no calles;\nSeñor, no te alejes de mí."],[23,"Muévete y despierta para hacerme justicia,\nDios mío y Señor mío, para defender mi causa."],[24,"Júzgame conforme a tu justicia, oh Yahvé Dios mío,\ny no se alegren de mí."],[25,"No digan en su corazón: «¡Ea, alma nuestra!»\nNo digan: «¡Lo hemos devorado!»"],[26,"Sean avergonzados y confundidos a una los que de mi mal se alegran;\nvístanse de vergüenza y de confusión los que se engrandecen contra mí."],[27,"Canten y alégrense los que están a favor de mi justa causa,\ny digan siempre: «Sea exaltado Yahvé,\nque ama la paz de su siervo»."],[28,"Y mi lengua hablará de tu justicia\ny de tu alabanza todo el día."]],"l":[]},{"i":[[0,"Al director musical. De David, siervo de Yahvé."],[1,"La iniquidad del impío me dice al corazón:\n«No hay temor de Dios delante de sus ojos»."],[2,"Se lisonjea, por tanto, en sus propios ojos,\nde que su iniquidad no será hallada y aborrecida."],[3,"Las palabras de su boca son iniquidad y fraude;\nha dejado de ser cuerdo y de hacer el bien."],[4,"Medita iniquidad sobre su lecho;\nse pone en camino no bueno,\ny el mal no aborrece."],[5,"Oh Yahvé, hasta los cielos llega tu misericordia,\ny tu fidelidad alcanza hasta las nubes."],[6,"Tu justicia es como los montes de Dios,\ntus juicios, abismo grande.\nOh Yahvé, al hombre y al animal conservas."],[7,"¡Cuán preciosa, oh Dios, es tu misericordia!\nPor eso los hijos de los hombres se amparan bajo la sombra de tus alas."],[8,"Serán completamente saciados de la abundancia de tu casa,\ny tú los abrevarás del torrente de tus delicias."],[9,"Porque contigo está el manantial de la vida;\nen tu luz veremos la luz."],[10,"Extiende tu misericordia a los que te conocen,\ny tu justicia a los rectos de corazón."],[11,"No venga pie de soberbia contra mí,\ny mano de impíos no me mueva."],[12,"Allí cayeron los hacedores de iniquidad;\nfueron derribados, y no podrán levantarse."]],"l":[]},{"i":[[0,"De David."],[1,"No te impacientes a causa de los malignos,\nni tengas envidia de los que hacen iniquidad."],[2,"Porque como hierba serán pronto cortados,\ny como la hierba verde se secarán."],[3,"Confía en Yahvé, y haz el bien;\nhabitarás en la tierra, y te apacentarás de la verdad."],[4,"Deléitate asimismo en Yahvé,\ny él te concederá las peticiones de tu corazón."],[5,"Encomienda a Yahvé tu camino,\ny confía en él; y él hará."],[6,"Exhibirá tu justicia como la luz,\ny tu derecho como el mediodía."],[7,"Guarda silencio ante Yahvé, y espera en él.\nNo te alteres con motivo del que prospera en su camino,\npor el hombre que hace maldades."],[8,"Deja la ira, y desecha el enojo;\nno te excites en manera alguna a hacer lo malo."],[9,"Porque los malignos serán destruidos,\npero los que esperan en Yahvé, ellos heredarán la tierra."],[10,"Pues de aquí a poco no existirá el malo;\nobservarás su lugar, y no estará allí."],[11,"Pero los mansos heredarán la tierra,\ny se recrearán con abundancia de paz."],[12,"Maquina el impío contra el justo,\ny cruje contra él sus dientes;"],[13,"el Señor se reirá de él,\nporque ve que viene su día."],[14,"Los impíos desenvainan espada y entesan su arco,\npara derribar al pobre y al menesteroso,\npara matar a los de recto proceder."],[15,"Su espada entrará en su mismo corazón,\ny su arco será quebrado."],[16,"Mejor es lo poco del justo,\nque las riquezas de muchos pecadores."],[17,"Porque los brazos de los impíos serán quebrados,\nmas el que sostiene a los justos es Yahvé."],[18,"Conoce Yahvé los días de los perfectos,\ny la heredad de ellos será para siempre."],[19,"No serán avergonzados en el mal tiempo,\ny en los días de hambre serán saciados."],[20,"Mas los impíos perecerán,\ny los enemigos de Yahvé como la grasa de los carneros\nserán consumidos;\nse disiparán como el humo."],[21,"El impío toma prestado, y no paga;\nmas el justo tiene misericordia, y da."],[22,"Porque los benditos de él heredarán la tierra;\ny los malditos de él serán destruidos."],[23,"Por Yahvé son ordenados los pasos del hombre,\ny él aprueba su camino."],[24,"Cuando el hombre cayere, no quedará postrado,\nporque Yahvé sostiene su mano."],[25,"Joven fui, y he envejecido,\ny no he visto justo desamparado,\nni su descendencia que mendigue pan."],[26,"En todo tiempo tiene misericordia, y presta;\ny su descendencia es para bendición."],[27,"Apártate del mal, y haz el bien,\ny vivirás para siempre."],[28,"Porque Yahvé ama la rectitud,\ny no desampara a sus santos.\nPara siempre serán guardados,\nmas la descendencia de los impíos será destruida."],[29,"Los justos heredarán la tierra,\ny vivirán para siempre sobre ella."],[30,"La boca del justo habla sabiduría,\ny su lengua habla justicia."],[31,"La ley de su Dios está en su corazón;\npor tanto, sus pies no resbalarán."],[32,"Acecha el impío al justo,\ny procura matarlo."],[33,"Yahvé no lo dejará en sus manos,\nni lo condenará cuando le juzgaren."],[34,"Espera en Yahvé, y guarda su camino,\ny él te exaltará para heredar la tierra;\ncuando sean destruidos los pecadores, lo verás."],[35,"Vi yo al impío sumamente enaltecido,\ny que se extendía como laurel verde."],[36,"Pero él pasó, y he aquí ya no estaba;\nlo busqué, y no fue hallado."],[37,"Considera al íntegro, y mira al justo;\nporque hay un final dichoso para el hombre de paz."],[38,"Mas los transgresores serán todos a una destruidos;\nla posteridad de los impíos será extinguida."],[39,"Pero la salvación de los justos es de Yahvé,\ny él es su fortaleza en el tiempo de la angustia."],[40,"Yahvé los ayudará y los librará;\nlos libertará de los impíos, y los salvará,\npor cuanto en él esperaron."]],"l":[]},{"i":[[0,"Salmo de David. Para hacer memoria."],[1,"Oh Yahvé, no me reprendas en tu ira,\nni me castigues en tu furor."],[2,"Porque tus saetas cayeron sobre mí,\ny sobre mí ha descendido tu mano."],[3,"Nada hay sano en mi carne a causa de tu ira;\nni hay paz en mis huesos a causa de mi pecado."],[4,"Porque mis iniquidades han sobrepasado mi cabeza;\ncomo carga pesada, son demasiado pesadas para mí."],[5,"Hieden y supuran mis llagas,\na causa de mi necedad."],[6,"Estoy encorvado, estoy humillado en gran manera,\nando enlutado todo el día."],[7,"Porque mis lomos están llenos de ardor,\ny nada hay sano en mi carne."],[8,"Estoy debilitado y molido en gran manera;\ngimo a causa de la conmoción de mi corazón."],[9,"Señor, delante de ti están todos mis deseos,\ny mi suspiro no te es oculto."],[10,"Mi corazón palpita fuertemente, me ha dejado mi vigor,\ny aun la luz de mis ojos me falta ya."],[11,"Mis amigos y mis compañeros se mantienen lejos de mi plaga,\ny mis parientes se han alejado."],[12,"Los que buscan mi vida arman lazos,\ny los que procuran mi mal hablan iniquidades,\ny meditan engaños todo el día."],[13,"Mas yo, como si fuera sordo, no oigo;\ny soy como mudo que no abre la boca."],[14,"Soy, pues, como un hombre que no oye,\ny en cuya boca no hay reprensiones."],[15,"Porque en ti, oh Yahvé, he esperado;\ntú responderás, oh Señor Dios mío."],[16,"Porque dije: «No se alegren de mí;\ncuando mi pie resbale, no se engrandezcan sobre mí»."],[17,"Pero yo estoy a punto de caer,\ny mi dolor está delante de mí continuamente."],[18,"Por tanto, confesaré mi maldad,\ny me congojaré por mi pecado."],[19,"Porque mis enemigos están vivos y fuertes,\ny se han aumentado los que me aborrecen sin causa."],[20,"Los que pagan mal por bien\nme son contrarios, por seguir yo lo bueno."],[21,"No me desampares, oh Yahvé;\nDios mío, no te alejes de mí."],[22,"Apresúrate a ayudarme,\noh Señor, mi salvación."]],"l":[]},{"i":[[0,"Al director musical. Sobre Jedutún. Salmo de David."],[1,"Dije: «Atenderé a mis caminos, para no pecar con mi lengua;\nguardaré mi boca con freno, en tanto que el impío esté delante de mí»."],[2,"Enmudecí, guardé silencio,\ny me callé aun respecto de lo bueno;\ny se agravó mi dolor."],[3,"Se enardeció mi corazón dentro de mí;\nen mi meditación se encendió fuego,\ny así proferí con mi lengua:"],[4,"«Hazme saber, oh Yahvé, mi fin,\ny cuánta sea la medida de mis días;\nsepa yo cuán frágil soy."],[5,"He aquí, has hecho mis días cortos como palmos,\ny mi vida es como nada delante de ti.\nCiertamente es completa vanidad todo hombre que vive. Selah."],[6,"Ciertamente como una sombra es el hombre;\nciertamente en vano se afana;\namontona riquezas, y no sabe quién las recogerá."],[7,"Y ahora, Señor, ¿qué esperaré?\nMi esperanza está en ti."],[8,"Líbrame de todas mis transgresiones;\nno me pongas por escarnio del insensato."],[9,"Enmudecí, no abrí mi boca,\nporque tú lo hiciste."],[10,"Quita de sobre mí tu plaga;\nestoy consumido bajo los golpes de tu mano."],[11,"Con castigos por el pecado corriges al hombre,\ny deshaces como polilla lo más estimado de él.\nCiertamente, vanidad es todo hombre. Selah."],[12,"Escucha mi oración, oh Yahvé, y presta oído a mi clamor;\nno calles ante mis lágrimas.\nPorque forastero soy para ti,\ny advenedizo, como todos mis padres."],[13,"Déjame, y tomaré fuerzas,\nantes que me vaya y perezca»."]],"l":[]},{"i":[[0,"Al director musical. Salmo de David."],[1,"Pacientemente esperé a Yahvé,\ny se inclinó a mí, y oyó mi clamor."],[2,"Y me hizo sacar del pozo de la desesperación, del lodo cenagoso;\npuso mis pies sobre peña, y enderezó mis pasos."],[3,"Puso luego en mi boca cántico nuevo, alabanza a nuestro Dios.\nVerán esto muchos, y temerán, y confiarán en Yahvé."],[4,"Bienaventurado el hombre que puso en Yahvé su confianza,\ny no mira a los soberbios, ni a los que se desvían tras la mentira."],[5,"Has aumentado, oh Yahvé Dios mío, tus maravillas;\ny tus pensamientos para con nosotros, no es posible contarlos ante ti.\nSi yo anunciare y hablare de ellos,\nno pueden ser enumerados."],[6,"Sacrificio y ofrenda no te agrada;\nhas abierto mis oídos;\nholocausto y expiación no has demandado."],[7,"Entonces dije: «He aquí, vengo;\nen el rollo del libro está escrito de mí;"],[8,"el hacer tu voluntad, Dios mío, me ha agradado,\ny tu ley está en medio de mi corazón»."],[9,"He anunciado justicia en la grande congregación;\nhe aquí, no refrené mis labios, Yahvé, tú lo sabes."],[10,"No encubrí tu justicia dentro de mi corazón;\nhe publicado tu fidelidad y tu salvación;\nno oculté tu misericordia y tu verdad en la grande congregación."],[11,"Yahvé, no retengas de mí tus misericordias;\ntu misericordia y tu verdad me guarden siempre."],[12,"Porque me han rodeado males sin número;\nme han alcanzado mis maldades, y no puedo levantar la vista.\nSe han aumentado más que los cabellos de mi cabeza,\ny mi corazón me falla."],[13,"Quieras, oh Yahvé, librarme;\nYahvé, apresúrate a socorrerme."],[14,"Sean avergonzados y confundidos a una los que buscan mi vida para destruirla.\nVuelvan atrás y sean avergonzados los que mi mal desean;"],[15,"sean asolados en pago de su afrenta los que me dicen: «¡Ea, ea!»"],[16,"Gócense y alégrense en ti todos los que te buscan,\ny digan siempre los que aman tu salvación: «¡Yahvé sea enaltecido!»"],[17,"Aunque afligido yo y necesitado,\nYahvé pensará en mí.\nMi ayuda y mi libertador eres tú;\nDios mío, no te tardes."]],"l":[]},{"i":[[0,"Al director musical. Salmo de David."],[1,"Bienaventurado el que piensa en el pobre;\nen el día malo lo librará Yahvé."],[2,"Yahvé lo guardará, y le dará vida;\nserá bienaventurado en la tierra,\ny no lo entregarás a la voluntad de sus enemigos."],[3,"Yahvé lo sustentará sobre el lecho del dolor;\nmullirás toda su cama en su enfermedad."],[4,"Yo dije: «Yahvé, ten misericordia de mí;\nsana mi alma, porque contra ti he pecado»."],[5,"Mis enemigos dicen mal de mí, preguntando:\n«¿Cuándo morirá, y perecerá su nombre?»"],[6,"Y si alguno viene a verme, habla mentiras;\nsu corazón recoge para sí iniquidad,\ny al salir fuera la divulga."],[7,"Reunidos murmuran contra mí todos los que me aborrecen;\ncontra mí piensan mal, diciendo de mí:"],[8,"«Cosa pestilencial se ha apoderado de él;\ny el que cayó en cama no volverá a levantarse»."],[9,"Aun el hombre de mi paz, en quien yo confiaba,\nel que de mi pan comía,\nalzó contra mí el calcañar."],[10,"Mas tú, Yahvé, ten misericordia de mí, y hazme levantar,\ny les daré el pago."],[11,"En esto conoceré que te he agradado,\nen que mi enemigo no se huelgue de mí."],[12,"En cuanto a mí, en mi integridad me has sustentado,\ny me has hecho estar delante de tu rostro para siempre."],[13,"Bendito sea Yahvé, el Dios de Israel,\ndesde la eternidad y hasta la eternidad.\nAmén y amén."]],"l":[]},{"i":[[0,"LIBRO 2"],[0,"Al director musical. Masquil de los hijos de Coré."],[1,"Como el ciervo brama por las corrientes de las aguas,\nasí clama por ti, oh Dios, el alma mía."],[2,"Mi alma tiene sed de Dios, del Dios vivo;\n¿cuándo vendré, y me presentaré delante de Dios?"],[3,"Fueron mis lágrimas mi pan de día y de noche,\nmientras me dicen todos los días: «¿Dónde está tu Dios?»"],[4,"Me acuerdo de estas cosas, y derramo mi alma dentro de mí;\nde cómo yo fui con la multitud, y la conduje hasta la casa de Dios,\nentre voces de alegría y de alabanza del pueblo en fiesta."],[5,"¿Por qué te abates, oh alma mía,\ny te turbas dentro de mí?\nEspera en Dios;\nporque aún he de alabarle, salvación mía y Dios mío."],[6,"Dios mío, mi alma está abatida en mí;\nme acordaré, por tanto, de ti desde la tierra del Jordán,\ny de los hermonitas, desde el monte de Mizar.",[[88,94,0]]],[7,"Un abismo llama a otro a la voz de tus cascadas;\ntodas tus ondas y tus olas han pasado sobre mí."],[8,"Pero de día mandará Yahvé su misericordia,\ny de noche su cántico estará conmigo,\ny mi oración al Dios de mi vida."],[9,"Diré a Dios: Roca mía, «¿por qué te has olvidado de mí?\n¿Por qué andaré yo enlutado por la opresión del enemigo?»"],[10,"Como quebrantamiento de mis huesos, mis enemigos me afrentan,\ndiciéndome cada día: «¿Dónde está tu Dios?»"],[11,"¿Por qué te abates, oh alma mía,\ny por qué te turbas dentro de mí?\nEspera en Dios; porque aún he de alabarle,\nsalvación mía y Dios mío."]],"l":[[638,"Jordán",32.3091,35.5599],[551,"Hermón",33.41616,35.85726]]},{"i":[[1,"Júzgame, oh Dios, y defiende mi causa;\nlíbrame de gente impía, y del hombre engañoso e inicuo."],[2,"Pues que tú eres el Dios de mi fortaleza, ¿por qué me has desechado?\n¿Por qué andaré enlutado por la opresión del enemigo?"],[3,"Envía tu luz y tu verdad;\nestas me guiarán;\nme conducirán a tu santo monte,\ny a tus moradas."],[4,"Entraré al altar de Dios,\nal Dios de mi alegría y de mi gozo;\ny te alabaré con arpa, oh Dios, Dios mío."],[5,"¿Por qué te abates, oh alma mía,\ny por qué te turbas dentro de mí?\nEspera en Dios;\nporque aún he de alabarle,\nsalvación mía y Dios mío."]],"l":[]},{"i":[[0,"Al director musical. Masquil de los hijos de Coré."],[1,"Oh Dios, con nuestros oídos hemos oído,\nnuestros padres nos han contado,\nla obra que hiciste en sus días, en los tiempos antiguos."],[2,"Tú con tu mano echaste a las naciones, y a ellos los plantaste;\nafligiste a los pueblos, y los multiplicaste."],[3,"Porque no se apoderaron de la tierra por su espada,\nni su propio brazo los salvó;\nsino tu diestra, y tu brazo, y la luz de tu rostro,\nporque te complaciste en ellos."],[4,"Tú, oh Dios, eres mi Rey;\nmanda salvación a Jacob."],[5,"Por medio de ti sacudiremos a nuestros enemigos;\nen tu nombre hollaremos a los que se levantan contra nosotros."],[6,"Porque no confiaré en mi arco,\nni mi espada me salvará."],[7,"Pues tú nos has guardado de nuestros enemigos,\ny has avergonzado a los que nos aborrecían."],[8,"En Dios nos gloriaremos todo el tiempo,\ny para siempre alabaremos tu nombre. Selah."],[9,"Pero ahora nos has desechado y nos has avergonzado;\ny ya no sales con nuestros ejércitos."],[10,"Nos hiciste retroceder delante del enemigo,\ny nos saquean los que nos aborrecen."],[11,"Nos entregas como ovejas al matadero,\ny nos has esparcido entre las naciones."],[12,"Has vendido a tu pueblo de balde;\nno exigiste ningún precio por ellos."],[13,"Nos pones por afrenta de nuestros vecinos,\npor escarnio y por burla de los que nos rodean."],[14,"Nos pones por proverbio entre las naciones,\npor motivo de menear la cabeza entre los pueblos."],[15,"Cada día mi vergüenza está delante de mí,\ny la confusión de mi rostro me cubre,"],[16,"por la voz del que me vitupera y deshonra,\npor causa del enemigo y del vengativo."],[17,"Todo esto nos ha venido, y no nos hemos olvidado de ti;\nno hemos faltado a tu pacto."],[18,"No se ha vuelto atrás nuestro corazón,\nni se han apartado de tus caminos nuestros pasos,"],[19,"para que nos quebrantases en la guarida de los chacales,\ny nos cubrieses con sombra de muerte."],[20,"Si nos hubiésemos olvidado del nombre de nuestro Dios,\no alzado nuestras manos a un dios ajeno,"],[21,"¿no demandaría Dios esto?\nPorque él conoce los secretos del corazón."],[22,"Pero por causa de ti nos matan cada día;\nsomos contados como ovejas para el matadero."],[23,"¡Despierta!\n¿Por qué duermes, Señor?\n¡Levántate!\nNo nos deseches para siempre."],[24,"¿Por qué escondes tu rostro,\ny te olvidas de nuestra aflicción y de nuestra opresión?"],[25,"Porque nuestra alma está agobiada hasta el polvo;\nnuestro cuerpo está postrado hasta la tierra."],[26,"Levántate para ayudarnos,\ny redímenos por causa de tu misericordia."]],"l":[]},{"i":[[0,"Al director musical. Sobre Lirios. Masquil de los hijos de Coré. Canción de amores."],[1,"Rebosa mi corazón palabra buena;\ndirijo al rey mi canto;\nmi lengua es pluma de escribiente muy ligero."],[2,"Eres el más hermoso de los hijos de los hombres;\nla gracia se derramó en tus labios;\npor tanto, Dios te ha bendecido para siempre."],[3,"Ciñe tu espada sobre el muslo, oh valiente,\ncon tu gloria y con tu majestad."],[4,"En tu gloria sé prosperado; cabalga victorioso en nombre de la verdad, de la humildad y de la justicia;\ny tu diestra te enseñará cosas terribles."],[5,"Tus saetas agudas,\ncon que caerán pueblos debajo de ti,\npenetrarán en el corazón de los enemigos del rey."],[6,"Tu trono, oh Dios, es eterno y para siempre;\ncetro de justicia es el cetro de tu reino."],[7,"Has amado la justicia y aborrecido la maldad;\npor tanto, te ungió Dios, el Dios tuyo, con óleo de alegría más que a tus compañeros."],[8,"Mirra, áloe y casia exhalan todos tus vestidos;\ndesde palacios de marfil te recrean los instrumentos de cuerda."],[9,"Hijas de reyes están entre tus ilustres;\nestá la reina a tu diestra con oro de Ofir.",[[79,83,0]]],[10,"Oye, hija, y mira, e inclina tu oído;\nolvida tu pueblo, y la casa de tu padre;"],[11,"y deseará el rey tu hermosura;\ne inclínate a él, porque él es tu señor."],[12,"Y las hijas de Tiro vendrán con presentes;\nimplorarán tu favor los ricos del pueblo.",[[15,19,1]]],[13,"Toda gloriosa es la hija del rey en su morada;\nde brocado de oro es su vestido."],[14,"Con vestidos bordados será llevada al rey;\nvírgenes irán en pos de ella,\ncompañeras suyas serán traídas a ti."],[15,"Serán traídas con alegría y gozo;\nentrarán en el palacio del rey."],[16,"En lugar de tus padres serán tus hijos,\na quienes harás príncipes en toda la tierra."],[17,"Haré perpetua la memoria de tu nombre en todas las generaciones,\npor lo cual te alabarán los pueblos eternamente y para siempre."]],"l":[[892,"Ofir",22.0,77.0],[1162,"Tiro",33.27583,35.19257]]},{"i":[[0,"Al director musical. De los hijos de Coré. Sobre Alamot. Cántico."],[1,"Dios es nuestro amparo y fortaleza,\nnuestro pronto auxilio en las tribulaciones."],[2,"Por tanto, no temeremos, aunque la tierra sea removida,\ny se traspasen los montes al corazón del mar;"],[3,"aunque bramen y se turben sus aguas,\ny tiemblen los montes a causa de su braveza. Selah."],[4,"Del río sus corrientes alegran la ciudad de Dios,\nel santuario de las moradas del Altísimo."],[5,"Dios está en medio de ella; no será conmovida.\nDios la ayudará al clarear la mañana."],[6,"Bramaron las naciones, titubearon los reinos;\ndio él su voz, se derritió la tierra."],[7,"Yahvé de los ejércitos está con nosotros;\nnuestro refugio es el Dios de Jacob. Selah."],[8,"Venid, ved las obras de Yahvé,\nque ha puesto asolamientos en la tierra."],[9,"Que hace cesar las guerras hasta los fines de la tierra.\nQue quiebra el arco, corta la lanza,\ny quema los carros en el fuego."],[10,"«Estad quietos, y conoced que yo soy Dios;\nseré exaltado entre las naciones;\nenaltecido seré en la tierra»."],[11,"Yahvé de los ejércitos está con nosotros;\nnuestro refugio es el Dios de Jacob. Selah."]],"l":[]},{"i":[[0,"Al director musical. Salmo de los hijos de Coré."],[1,"Pueblos todos, batid las manos;\naclamad a Dios con voz de júbilo."],[2,"Porque Yahvé el Altísimo es temible;\nRey grande sobre toda la tierra."],[3,"Él someterá a los pueblos debajo de nosotros,\ny a las naciones debajo de nuestros pies."],[4,"Él nos elegirá nuestras heredades,\nla hermosura de Jacob, al cual amó. Selah."],[5,"Subió Dios con júbilo,\nYahvé con sonido de trompeta."],[6,"Cantad a Dios, cantad;\ncantad a nuestro Rey, cantad."],[7,"Porque Dios es el Rey de toda la tierra;\ncantad con inteligencia."],[8,"Reinó Dios sobre las naciones;\nse sentó Dios sobre su santo trono."],[9,"Los príncipes de los pueblos se reunieron,\ncomo pueblo del Dios de Abraham;\nporque de Dios son los escudos de la tierra;\nél es muy exaltado."]],"l":[]},{"i":[[0,"Cántico. Salmo de los hijos de Coré."],[1,"Grande es Yahvé, y digno de suprema alabanza,\nen la ciudad de nuestro Dios, en su santo monte."],[2,"¡Hermosa provincia, el gozo de toda la tierra,\nes el monte de Sion, a los lados del norte,\nla ciudad del gran Rey!",[[62,66,0]]],[3,"En sus palacios Dios es conocido por refugio."],[4,"Porque he aquí los reyes de la tierra se reunieron;\npasaron todos juntos."],[5,"Y viéndola ellos así, se maravillaron,\nse turbaron, se apresuraron a huir."],[6,"Les tomó allí temblor;\ndolor como de mujer que da a luz."],[7,"Con viento solano quiebras tú las naves de Tarsis.",[[43,49,1]]],[8,"Como lo oímos, así lo hemos visto\nen la ciudad de Yahvé de los ejércitos, en la ciudad de nuestro Dios;\nla afirmará Dios para siempre. Selah."],[9,"Nos acordamos de tu misericordia, oh Dios,\nen medio de tu templo."],[10,"Conforme a tu nombre, oh Dios,\nasí es tu loor hasta los fines de la tierra;\nde justicia está llena tu diestra."],[11,"Se alegrará el monte de Sion;\nse gozarán las hijas de Judá por tus juicios.",[[24,28,0]]],[12,"Andad alrededor de Sion, y rodeadla;\ncontad sus torres.",[[19,23,2]]],[13,"Considerad atentamente su antemuro,\nmirad sus palacios;\npara que lo contéis a la generación venidera."],[14,"Porque este Dios es Dios nuestro eternamente y para siempre;\nél nos guiará aun más allá de la muerte."]],"l":[[844,"Monte Sión",31.77744,35.23494],[1116,"Tarsis",36.953,-6.37934],[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Al director musical. Salmo de los hijos de Coré."],[1,"Oíd esto, pueblos todos;\nescuchad, habitantes todos del mundo,"],[2,"así los plebeyos como los nobles,\nel rico y el pobre juntamente."],[3,"Mi boca hablará sabiduría,\ny la meditación de mi corazón será inteligencia."],[4,"Inclinaré al proverbio mi oído;\ndeclararé con el arpa mi enigma."],[5,"¿Por qué he de temer en los días de adversidad,\ncuando la iniquidad de mis opresores me rodeare?"],[6,"Los que confían en sus bienes,\ny de la muchedumbre de sus riquezas se jactan,"],[7,"ninguno de ellos podrá en manera alguna redimir al hermano,\nni dar a Dios su rescate"],[8,"(porque la redención de su vida es de gran precio,\ny no se logrará jamás),"],[9,"para que viva en adelante para siempre,\ny nunca vea corrupción."],[10,"Pues verá que aun los sabios mueren;\nque perecen del mismo modo el insensato y el necio,\ny dejan a otros sus riquezas."],[11,"Su íntimo pensamiento es que sus casas serán eternas,\ny sus moradas para todas las generaciones;\nllaman a sus tierras con sus propios nombres."],[12,"Mas el hombre no permanecerá en honra;\nes semejante a las bestias que perecen."],[13,"Este su camino es locura;\ncon todo, sus descendientes se complacen en el dicho de ellos. Selah."],[14,"Como a rebaños que son conducidos al Seol,\nla muerte los pastoreará,\ny los rectos se enseñorearán de ellos por la mañana;\nse consumirá su buen parecer, y el Seol será su morada."],[15,"Pero Dios redimirá mi vida del poder del Seol,\nporque él me tomará consigo. Selah."],[16,"No temas cuando se enriquece alguno,\ncuando aumenta la gloria de su casa;"],[17,"porque cuando muera no llevará nada,\nni descenderá tras él su gloria."],[18,"Aunque mientras viva, llame dichosa a su alma\n(y los hombres te alaban cuando prosperas),"],[19,"irá a la generación de sus padres,\ny nunca más verá la luz."],[20,"El hombre que está en honra y no entiende,\nsemejante es a las bestias que perecen."]],"l":[]},{"i":[[0,"Salmo de Asaf."],[1,"El Dios de dioses, Yahvé, ha hablado,\ny convocado la tierra, desde el nacimiento del sol hasta donde se pone."],[2,"De Sion, perfección de hermosura,\nDios ha resplandecido.",[[3,7,0]]],[3,"Vendrá nuestro Dios, y no callará;\nfuego consumirá delante de él,\ny tempestad muy turbulenta le rodeará."],[4,"Convocará a los cielos de arriba,\ny a la tierra, para juzgar a su pueblo."],[5,"«Juntadme a mis santos,\nlos que hicieron conmigo pacto con sacrificio»."],[6,"Y los cielos declararán su justicia,\nporque Dios es el juez. Selah."],[7,"«Oye, pueblo mío, y hablaré;\nescucha, Israel, y testificaré contra ti:\nYo soy Dios, el Dios tuyo."],[8,"No te reprenderé por tus sacrificios,\nni por tus holocaustos, que están continuamente delante de mí."],[9,"No tomaré becerro de tu casa,\nni machos cabríos de tus apriscos."],[10,"Porque mía es toda bestia del bosque,\ny los millares de animales en los collados."],[11,"Conozco a todas las aves de los montes,\ny todo lo que se mueve en los campos me pertenece."],[12,"Si yo tuviese hambre, no te lo diría a ti;\nporque mío es el mundo y su plenitud."],[13,"¿He de comer yo carne de toros,\no de beber sangre de machos cabríos?"],[14,"Sacrifica a Dios alabanza,\ny paga tus votos al Altísimo;"],[15,"e invócame en el día de la angustia;\nte libraré, y tú me honrarás»."],[16,"Pero al impío dijo Dios:\n“¿Qué tienes tú que contar mis leyes,\ny que tomar mi pacto en tu boca,"],[17,"pues tú aborreces la corrección,\ny echas a tu espalda mis palabras?"],[18,"Si veías al ladrón, tú consentías con él,\ny con los adúlteros era tu parte."],[19,"Tu boca metías en mal,\ny tu lengua componía engaño."],[20,"Te sentabas y hablabas contra tu hermano;\ncontra el hijo de tu madre ponías infamia."],[21,"Estas cosas hiciste, y yo he callado;\npensabas que de cierto sería yo como tú;\npero te reprenderé, y las pondré delante de tus ojos."],[22,"Entended ahora esto, los que os olvidáis de Dios,\nno sea que os despedace, y no haya quien os libre."],[23,"El que sacrifica alabanza me honrará;\ny al que ordenare su camino, le mostraré la salvación de Dios”."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Para el músico principal. Salmo de David, cuando el profeta Natán acudió a él, después de haber entrado en casa de Betsabé."],[1,"Ten piedad de mí, oh Dios, según tu misericordia.\nSegún la multitud de tus piedades, borra mis transgresiones."],[2,"Lávame por completo de mi iniquidad.\nLímpiame de mi pecado."],[3,"Porque yo reconozco mis transgresiones.\nMi pecado está constantemente ante mí."],[4,"Contra ti, y solo contra ti, he pecado,\ny he hecho lo malo ante tus ojos,\nde modo que eres justo cuando hablas,\ny puro cuando juzgas."],[5,"He aquí que en iniquidad fui formado.\nMi madre me concibió en pecado."],[6,"He aquí que deseas la verdad en lo íntimo.\nMe enseñas la sabiduría en lo más secreto."],[7,"Purifícame con hisopo, y quedaré limpio.\nLávame, y quedaré más blanco que la nieve."],[8,"Hazme oír el gozo y la alegría,\npara que se regocijen los huesos que has quebrantado."],[9,"Esconde tu rostro de mis pecados,\ny borra todas mis iniquidades."],[10,"Crea en mí, oh Dios, un corazón limpio.\nRenueva un espíritu recto dentro de mí."],[11,"No me eches de tu presencia,\ny no me quites tu santo Espíritu."],[12,"Devuélveme el gozo de tu salvación.\nSosténme con un espíritu dispuesto."],[13,"Entonces enseñaré a los transgresores tus caminos.\nY los pecadores se convertirán a ti."],[14,"Líbrame del delito de sangre, oh Dios, Dios de mi salvación.\nMi lengua aclamará tu justicia."],[15,"Señor, abre mis labios.\nMi boca proclamará tu alabanza."],[16,"Porque no te complaces en el sacrificio, que yo lo daría.\nNo te agrada el holocausto."],[17,"Los sacrificios de Dios son el espíritu quebrantado.\nAl corazón contrito y humillado no despreciarás, oh Dios."],[18,"Haz bien a Sión en tu benevolencia.\nEdifica los muros de Jerusalén.",[[11,15,0],[57,66,1]]],[19,"Entonces te agradarán los sacrificios de justicia,\nel holocausto y la ofrenda del todo quemada.\nEntonces ofrecerán becerros sobre tu altar."]],"l":[[1239,"Sión",31.77744,35.23494],[622,"Jerusalén",31.77744,35.23494]]},{"i":[[0,"Para el músico principal. Contemplación de David, cuando Doeg el edomita vino y le dijo a Saúl: «David ha venido a la casa de Ahimelec»."],[1,"¿Por qué te jactas de la maldad, oh hombre poderoso?\nLa misericordia de Dios perdura continuamente."],[2,"Tu lengua trama destrucción;\nes como una navaja afilada, obrando con engaño."],[3,"Amas el mal más que el bien,\nla mentira en lugar de decir la verdad. Selah."],[4,"Amas todas las palabras perniciosas,\noh lengua engañosa."],[5,"Dios también te destruirá para siempre;\nte arrebatará y te sacará de tu morada,\ny te arrancará de la tierra de los vivientes. Selah."],[6,"Verán esto los justos y temerán,\ny se reirán de él, diciendo:"],[7,"«He aquí el hombre que no puso a Dios por su fortaleza,\nsino que confió en la abundancia de sus riquezas,\ny se fortaleció en su perversidad»."],[8,"Pero yo soy como un olivo verde en la casa de Dios;\nconfío en la misericordia de Dios eterna y para siempre."],[9,"Te alabaré para siempre por lo que has hecho;\ny esperaré en tu nombre, porque es bueno,\ndelante de tus santos."]],"l":[]},{"i":[[0,"Para el músico principal. Sobre Mahalat. Contemplación de David."],[1,"El necio ha dicho en su corazón: «No hay Dios».\nSe han corrompido y han cometido abominable iniquidad.\nNo hay quien haga el bien."],[2,"Dios mira desde el cielo a los hijos de los hombres,\npara ver si hay algún entendido,\nque busque a Dios."],[3,"Todos se han desviado.\nA una se han corrompido.\nNo hay quien haga el bien, no hay ni siquiera uno."],[4,"¿Acaso no tienen conocimiento los obradores de iniquidad,\nque devoran a mi pueblo como si comieran pan,\ny no invocan a Dios?"],[5,"Allí temblaron de gran pavor, donde no había pavor,\nporque Dios esparció los huesos del que acampó contra ti.\nTú los avergonzaste,\nporque Dios los ha desechado."],[6,"¡Oh, que de Sión saliera la salvación de Israel!\nCuando Dios restaure de la cautividad a su pueblo,\nse regocijará Jacob,\ny se alegrará Israel.",[[12,16,0]]]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Para el músico principal. Sobre instrumentos de cuerda. Contemplación de David, cuando los zifeos vinieron y dijeron a Saúl: «¿No se esconde David entre nosotros?»"],[1,"Oh Dios, sálvame por tu nombre.\nY con tu poder defiéndeme."],[2,"Oh Dios, escucha mi oración.\nPresta oído a las palabras de mi boca."],[3,"Porque extraños se han levantado contra mí.\nHombres violentos buscan mi vida.\nNo han puesto a Dios delante de sí. Selah."],[4,"He aquí, Dios es el que me ayuda.\nEl Señor es quien sostiene mi vida."],[5,"Él devolverá el mal a mis enemigos.\nDestrúyelos en tu verdad."],[6,"Voluntariamente te ofreceré sacrificios.\nAlabaré tu nombre, oh Yahvé, porque es bueno."],[7,"Porque me ha librado de toda angustia.\nY mis ojos han visto la ruina de mis enemigos."]],"l":[]},{"i":[[0,"Para el músico principal. Sobre instrumentos de cuerda. Contemplación de David."],[1,"Escucha mi oración, oh Dios.\nNo te escondas de mi súplica."],[2,"Atiéndeme y respóndeme.\nEstoy turbado en mi queja, y gimo"],[3,"a causa de la voz del enemigo,\npor la opresión del impío.\nPorque echan iniquidad sobre mí,\ny con furor me persiguen."],[4,"Mi corazón está gravemente dolorido en mi interior.\nLos terrores de la muerte han caído sobre mí."],[5,"Temor y temblor se han apoderado de mí.\nEl horror me ha abrumado."],[6,"Y dije: «¡Oh, si tuviera alas como la paloma!\nEntonces volaría y descansaría."],[7,"He aquí que huiría lejos.\nMe alojaría en el desierto». Selah."],[8,"«Me apresuraría a buscar refugio del viento tempestuoso y de la tormenta»."],[9,"Confúndelos, Señor, y divide sus lenguas,\nporque he visto violencia y rencilla en la ciudad."],[10,"Día y noche la rondan sobre sus muros.\nLa iniquidad y el abuso también están en medio de ella."],[11,"Fuerzas destructivas están en su interior.\nLa opresión y el engaño no se apartan de sus calles."],[12,"Porque si un enemigo me hubiera afrentado,\nentonces podría haberlo soportado.\nSi el que me odiaba se hubiera alzado contra mí,\nentonces me habría escondido de él."],[13,"Pero fuiste tú, un hombre de mi propio rango,\nmi compañero y mi amigo íntimo."],[14,"Juntos compartíamos dulce comunión.\nCaminábamos en la casa de Dios entre la multitud."],[15,"Que la muerte los sorprenda.\nQue desciendan vivos al Seol,\nporque la maldad está en sus moradas, en medio de ellos."],[16,"En cuanto a mí, a Dios clamaré.\nY Yahvé me salvará."],[17,"Tarde, mañana y a mediodía me quejaré y gemiré.\nY él escuchará mi voz."],[18,"Él ha redimido mi alma en paz de la guerra que se levantó contra mí,\naunque eran muchos mis adversarios."],[19,"Dios, que reina desde la antigüedad,\nlos escuchará y los humillará. Selah.\nPorque en ellos no hay cambio,\nni temen a Dios."],[20,"Extendió sus manos contra los que estaban en paz con él.\nHa violado su pacto."],[21,"Su boca era más suave que la mantequilla,\npero la guerra estaba en su corazón.\nSus palabras eran más suaves que el aceite,\nsin embargo, eran espadas desenvainadas."],[22,"Echa tu carga sobre Yahvé, y él te sostendrá.\nNo dejará para siempre caído al justo."],[23,"Pero tú, oh Dios, los harás descender al pozo de la perdición.\nLos hombres sanguinarios y engañadores no vivirán la mitad de sus días,\npero yo confiaré en ti."]],"l":[]},{"i":[[0,"Para el músico principal. Sobre «La paloma silenciosa en tierras lejanas». Mictam de David, cuando los filisteos lo apresaron en Gat."],[1,"Ten piedad de mí, oh Dios, porque el hombre quiere devorarme.\nTodo el día me ataca y me oprime."],[2,"Mis enemigos quieren devorarme todo el día,\nporque son muchos los que luchan con soberbia contra mí."],[3,"En el día que temo,\nyo pondré mi confianza en ti."],[4,"En Dios alabaré su palabra.\nEn Dios he puesto mi confianza.\nNo temeré.\n¿Qué puede hacerme la carne?"],[5,"Todo el día tuercen mis palabras.\nTodos sus pensamientos son contra mí para mal."],[6,"Se reúnen y se esconden,\nvigilan mis pasos,\nesperando para quitarme la vida."],[7,"¿Escaparán ellos con su iniquidad?\nEn tu ira, oh Dios, derriba a los pueblos."],[8,"Tú cuentas mis huidas.\nPon mis lágrimas en tu redoma.\n¿Acaso no están en tu libro?"],[9,"Entonces mis enemigos retrocederán el día en que yo clame.\nEsto sé: que Dios está por mí."],[10,"En Dios alabaré su palabra.\nEn Yahvé alabaré su palabra."],[11,"En Dios he puesto mi confianza.\nNo temeré.\n¿Qué puede hacerme el hombre?"],[12,"Sobre mí, oh Dios, están tus votos.\nTe pagaré ofrendas de acción de gracias."],[13,"Porque has librado mi alma de la muerte,\ny mis pies de la caída,\npara que ande delante de Dios en la luz de los que viven."]],"l":[]},{"i":[[0,"Para el músico principal. Sobre «No destruyas». Mictam de David, cuando huyó de delante de Saúl a la cueva."],[1,"Ten piedad de mí, oh Dios, ten piedad de mí,\nporque en ti se refugia mi alma.\nSí, a la sombra de tus alas me refugiaré,\nhasta que haya pasado el quebranto."],[2,"Clamaré al Dios Altísimo,\nal Dios que hace todo por mí."],[3,"Él enviará desde los cielos y me salvará;\nreprenderá al que me acosa. Selah.\nDios enviará su misericordia y su verdad."],[4,"Mi alma está entre leones.\nEstoy echado entre hombres que respiran fuego,\nlos hijos de los hombres, cuyos dientes son lanzas y flechas,\ny su lengua, una espada afilada."],[5,"¡Exaltado seas sobre los cielos, oh Dios!\n¡Sobre toda la tierra sea tu gloria!"],[6,"Han preparado una red para mis pasos;\nmi alma está abatida.\nCavaron una fosa delante de mí,\npero ellos mismos cayeron en ella. Selah."],[7,"Mi corazón está firme, oh Dios.\nMi corazón está firme.\nCantaré, sí, entonaré alabanzas."],[8,"¡Despierta, alma mía! ¡Despertad, salterio y arpa!\nDespertaré a la aurora."],[9,"Te alabaré, oh Señor, entre los pueblos.\nTe cantaré alabanzas entre las naciones."],[10,"Porque inmensa, hasta los cielos, es tu misericordia,\ny hasta las nubes tu verdad."],[11,"¡Exaltado seas sobre los cielos, oh Dios!\n¡Que tu gloria sea sobre toda la tierra!"]],"l":[]},{"i":[[0,"Para el músico principal. Sobre «No destruyas». Mictam de David."],[1,"¿Acaso habláis verdaderamente justicia, oh poderosos?\n¿Juzgáis con rectitud, hijos de los hombres?"],[2,"Antes bien, en el corazón tramáis iniquidad;\npesáis la violencia de vuestras manos en la tierra."],[3,"Se apartaron los impíos desde la matriz;\nse descarriaron desde que nacieron, hablando mentira."],[4,"Su veneno es semejante al veneno de la serpiente;\nson como un áspid sordo que cierra su oído,"],[5,"que no oye la voz de los encantadores,\npor muy hábil que sea el mago."],[6,"Oh Dios, quiebra sus dientes en sus bocas;\narranca, oh Yahvé, los colmillos de los leoncillos."],[7,"Que se desvanezcan como aguas que fluyen de continuo;\ncuando tensen el arco, que sus flechas queden despuntadas."],[8,"Pasen como el caracol que se deslíe en su camino;\ncomo el aborto de mujer, que no vean el sol."],[9,"Antes que vuestras ollas sientan el fuego de los espinos,\ntanto al verde como al encendido, los arrebatará el torbellino."],[10,"Se alegrará el justo cuando vea la venganza;\nlavará sus pies en la sangre de los impíos."],[11,"Entonces dirán los hombres: «Ciertamente hay galardón para el justo;\nciertamente hay un Dios que juzga en la tierra»."]],"l":[]},{"i":[[0,"Para el músico principal. Sobre «No destruyas». Mictam de David, cuando Saúl envió hombres a vigilar la casa para matarlo."],[1,"Líbrame de mis enemigos, oh Dios mío.\nPonme a salvo de los que se levantan contra mí."],[2,"Líbrame de los obradores de iniquidad.\nSálvame de los hombres sanguinarios."],[3,"Porque, he aquí, acechan mi vida.\nSe han reunido contra mí los poderosos,\nno por transgresión mía ni por pecado mío, oh Yahvé."],[4,"Sin falta de mi parte, corren y se preparan.\n¡Despierta para venir a mi encuentro, y mira!"],[5,"Y tú, Yahvé Dios de los ejércitos, Dios de Israel,\ndespierta para castigar a todas las naciones.\nNo tengas piedad de los pérfidos inicuos. Selah."],[6,"Vuelven al atardecer, aúllan como perros,\ny merodean por la ciudad."],[7,"He aquí, prorrumpen con su boca;\nespadas hay en sus labios,\nporque dicen: «¿Quién nos oye?»"],[8,"Pero tú, oh Yahvé, te reirás de ellos.\nTe burlarás de todas las naciones."],[9,"Oh fortaleza mía, en ti esperaré,\nporque Dios es mi alto refugio."],[10,"Mi Dios en su misericordia irá delante de mí.\nDios me hará ver la derrota de mis enemigos."],[11,"No los mates, para que mi pueblo no lo olvide.\nDispérsalos con tu poder y abátelos, oh Señor, escudo nuestro."],[12,"Por el pecado de su boca y la palabra de sus labios,\nsean atrapados en su soberbia,\ny por las maldiciones y mentiras que profieren."],[13,"Consúmelos en tu furor.\nConsúmelos para que no existan más.\nY sepan que Dios gobierna en Jacob,\nhasta los confines de la tierra. Selah."],[14,"Vuelvan al anochecer.\nAúllen como perros y rodeen la ciudad."],[15,"Anden errantes en busca de comida,\ny pasen la noche quejándose si no se sacian."],[16,"Pero yo cantaré de tu poder.\nSí, alabaré de mañana tu misericordia.\nPorque has sido mi alto refugio,\ny asilo en el día de mi angustia."],[17,"Oh fortaleza mía, a ti cantaré alabanzas.\nPorque Dios es mi alto refugio, el Dios de mi misericordia."]],"l":[]},{"i":[[0,"Para el músico principal. Sobre «El lirio del testimonio». Mictam de David, para enseñar, cuando luchó contra Aram-naharaim y contra Aram-zoba, y Joab volvió y mató a doce mil de Edom en el valle de la Sal."],[1,"Oh Dios, tú nos has rechazado.\nNos has quebrantado.\nTe has airado.\n¡Restáuranos, oh Dios!"],[2,"Has hecho temblar la tierra.\nLa has hendido.\nSana sus roturas,\nporque titubea."],[3,"Has hecho ver a tu pueblo cosas duras.\nNos has hecho beber vino de aturdimiento."],[4,"Has dado a los que te temen una bandera,\npara que se alce por causa de la verdad. Selah."],[5,"Para que tu amado sea librado,\nsalva con tu diestra, y respóndenos."],[6,"Dios ha hablado en su santuario:\n«Yo triunfaré.\nRepartiré a Siquem,\ny mediré el valle de Sucot.",[[60,66,0]]],[7,"Mío es Galaad y mío es Manasés.\nEfraín también es la fortaleza de mi cabeza.\nJudá es mi legislador.",[[7,13,1]]],[8,"Moab es la vasija en que me lavo.\nSobre Edom lanzaré mi calzado.\nGritaré triunfante sobre Filistea».",[[0,4,2],[40,44,3],[90,98,4]]],[9,"¿Quién me llevará a la ciudad fortificada?\n¿Quién me guiará hasta Edom?",[[66,70,3]]],[10,"¿No nos has rechazado tú, oh Dios?\nYa no sales, oh Dios, con nuestros ejércitos."],[11,"Danos socorro contra el adversario,\nporque vana es la ayuda del hombre."],[12,"En Dios haremos proezas,\nporque él es quien pisoteará a nuestros adversarios."]],"l":[[1047,"Siquem",32.21369,35.2818],[466,"Galaad",32.04252,35.72424],[800,"Moab",31.49685,35.78284],[348,"Edom",30.73469,35.60625],[922,"Filistea",33.56317,35.36635]]},{"i":[[0,"Para el músico principal. Sobre instrumentos de cuerda. De David."],[1,"Escucha, oh Dios, mi clamor.\nAtiende a mi oración."],[2,"Desde el extremo de la tierra clamaré a ti cuando mi corazón desmaye.\nLlévame a la roca que es más alta que yo."],[3,"Porque tú has sido mi refugio,\nuna torre fuerte delante del enemigo."],[4,"Yo habitaré en tu tabernáculo para siempre.\nMe refugiaré bajo la cubierta de tus alas. Selah."],[5,"Porque tú, oh Dios, has escuchado mis votos.\nMe has dado la heredad de los que temen tu nombre."],[6,"Días añadirás a los días del rey.\nSus años serán de generación en generación."],[7,"Estará entronizado en la presencia de Dios para siempre.\nOrdena a tu misericordia y a tu verdad que lo guarden."],[8,"Así cantaré alabanzas a tu nombre para siempre,\npara pagar mis votos cada día."]],"l":[]},{"i":[[0,"Para el músico principal. A Jedutún. Salmo de David."],[1,"En Dios solamente reposa mi alma;\nde él viene mi salvación."],[2,"Solo él es mi roca y mi salvación; es mi refugio,\nno seré grandemente conmovido."],[3,"¿Hasta cuándo maquinaréis contra un hombre,\ntratando todos vosotros de aplastarlo\ncomo a una pared inclinada o una cerca que se derrumba?"],[4,"Solamente consultan para derribarlo de su grandeza.\nSe deleitan en la mentira;\nbendicen con su boca, pero maldicen en su corazón. Selah."],[5,"Alma mía, reposa solamente en Dios,\nporque de él viene mi esperanza."],[6,"Solo él es mi roca y mi salvación; es mi refugio,\nno seré conmovido."],[7,"En Dios está mi salvación y mi gloria;\nen Dios está mi roca fuerte y mi refugio."],[8,"Confiad en él en todo tiempo, oh pueblos;\nderramad vuestro corazón delante de él.\nDios es nuestro refugio. Selah."],[9,"Por cierto, vanidad son los hombres de baja condición,\ny mentira los hombres de alta condición.\nPesados en balanza,\ntodos juntos son más leves que un soplo."],[10,"No confiéis en la extorsión,\nni os envanezcáis en la rapiña.\nSi se aumentan las riquezas,\nno pongáis el corazón en ellas."],[11,"Una vez habló Dios;\ndos veces he oído esto:\nQue de Dios es el poder,"],[12,"y tuya, oh Señor, es la misericordia;\npues tú pagas a cada uno conforme a su obra."]],"l":[]},{"i":[[0,"Un salmo de David, cuando estaba en el desierto de Judá."],[1,"Oh Dios, tú eres mi Dios.\nDe madrugada te buscaré.\nMi alma tiene sed de ti.\nMi carne te anhela,\nen tierra seca y árida, donde no hay agua."],[2,"Así te he mirado en el santuario,\npara ver tu poder y tu gloria."],[3,"Porque tu misericordia es mejor que la vida,\nmis labios te alabarán."],[4,"Así te bendeciré mientras viva.\nLevantaré mis manos en tu nombre."],[5,"Mi alma se saciará como de exquisito manjar.\nMi boca te alabará con labios de júbilo,"],[6,"cuando me acuerdo de ti en mi lecho,\ny medito en ti en las vigilias de la noche."],[7,"Porque tú has sido mi socorro.\nMe regocijaré a la sombra de tus alas."],[8,"Mi alma está apegada a ti.\nTu diestra me sostiene."],[9,"Pero los que buscan mi vida para destruirla\nirán a las profundidades de la tierra."],[10,"Serán entregados al poder de la espada.\nSerán porción para los chacales."],[11,"Pero el rey se alegrará en Dios.\nTodos los que juran por él se gloriarán,\nporque la boca de los que hablan mentiras será cerrada."]],"l":[]},{"i":[[0,"Para el músico principal. Salmo de David."],[1,"Escucha, oh Dios, la voz de mi queja;\nguarda mi vida del terror del enemigo."],[2,"Escóndeme del consejo secreto de los malignos,\nde la conspiración de los obradores de iniquidad;"],[3,"que afilan su lengua como espada,\ny preparan sus flechas, palabras amargas,"],[4,"para asaetear a escondidas al íntegro.\nDe repente le disparan, y no temen."],[5,"Se obstinan en su malvado designio;\nhablan de esconder lazos,\ny dicen: «¿Quién los verá?»"],[6,"Escudriñan iniquidades, dicen: «¡Hemos consumado un plan perfecto!»\nY el íntimo pensamiento y el corazón de cada hombre son profundos."],[7,"Mas Dios les disparará sus flechas;\nde repente serán heridos."],[8,"Su propia lengua los hará caer;\nsacudirán la cabeza todos los que los vean."],[9,"Entonces temerán todos los hombres;\nanunciarán la obra de Dios,\ny entenderán sabiamente su obrar."],[10,"Se alegrará el justo en Yahvé,\ny se refugiará en él;\ny se gloriarán todos los rectos de corazón."]],"l":[]},{"i":[[0,"Para el músico principal. Salmo de David. Cántico."],[1,"Tuya es la alabanza en Sión, oh Dios.\nY a ti se te cumplirán los votos."],[2,"Tú que escuchas la oración,\na ti vendrá toda carne."],[3,"Las iniquidades prevalecen contra mí,\npero tú expiarás nuestras transgresiones."],[4,"Bienaventurado el que tú eliges y acercas a ti,\npara que habite en tus atrios.\nSeremos saciados con el bien de tu casa,\nde tu santo templo."],[5,"Con tremendas maravillas nos responderás en justicia,\noh Dios de nuestra salvación.\nTú que eres la esperanza de todos los confines de la tierra,\ny de los más lejanos mares."],[6,"Tú, que con tu poder afirmas los montes,\nestando ceñido de poder."],[7,"Tú que calmas el estruendo de los mares,\nel estruendo de sus olas,\ny el tumulto de las naciones."],[8,"Por eso los que habitan en los confines de la tierra temen ante tus maravillas.\nTú haces alegrar las salidas de la mañana y de la tarde."],[9,"Visitas la tierra y la riegas.\nEn gran manera la enriqueces.\nEl río de Dios está lleno de aguas.\nTú les preparas el grano, pues así lo has ordenado."],[10,"Empapas sus surcos.\nAllanas sus terrones.\nLa ablandas con lluvias.\nBendices sus renuevos."],[11,"Tú coronas el año con tus bienes.\nY tus rodadas destilan grosura."],[12,"Destilan sobre los pastizales del desierto.\nY los collados se ciñen de alegría."],[13,"Los prados se visten de rebaños.\nLos valles también se cubren de grano.\n¡Dan voces de júbilo!\nY también cantan."]],"l":[]},{"i":[[0,"Para el músico principal. Cántico. Salmo."],[1,"¡Aclamad a Dios con alegría, toda la tierra!"],[2,"¡Cantad la gloria de su nombre!\n¡Dadle gloria y alabanza!"],[3,"Decid a Dios: «¡Cuán asombrosas son tus obras!\nPor la grandeza de tu poder, tus enemigos se someten a ti."],[4,"Toda la tierra te adorará,\ny te cantará;\ncantarán a tu nombre». Selah."],[5,"Venid y ved las obras de Dios,\ntemible en sus hechos sobre los hijos de los hombres."],[6,"Convirtió el mar en tierra seca.\nAtravesaron el río a pie.\nAllí nos regocijamos en él."],[7,"Él gobierna con su poderío para siempre.\nSus ojos vigilan a las naciones.\nQue no se enaltezcan los rebeldes. Selah."],[8,"¡Bendecid a nuestro Dios, oh pueblos!\nHaced que se escuche la voz de su alabanza,"],[9,"que preserva nuestra vida entre los vivos,\ny no permite que nuestros pies resbalen."],[10,"Porque tú, oh Dios, nos has puesto a prueba.\nNos has refinado, como se refina la plata."],[11,"Nos metiste en la red.\nHas puesto pesada carga sobre nuestros lomos."],[12,"Hiciste cabalgar hombres sobre nuestras cabezas.\nPasamos por el fuego y por el agua,\npero nos sacaste a un lugar de abundancia."],[13,"Entraré en tu casa con holocaustos.\nTe pagaré mis votos,"],[14,"que pronunciaron mis labios,\ny habló mi boca, cuando estaba angustiado."],[15,"Te ofreceré holocaustos de animales engordados,\ncon sahumerio de carneros;\nofreceré novillos y machos cabríos. Selah."],[16,"Venid y escuchad, todos los que teméis a Dios.\nDeclararé lo que ha hecho por mi vida."],[17,"A él clamé con mi boca,\ny fue exaltado con mi lengua."],[18,"Si en mi corazón yo hubiese mirado a la iniquidad,\nel Señor no me habría escuchado."],[19,"Pero, ciertamente, Dios me ha escuchado.\nÉl ha atendido a la voz de mi oración."],[20,"Bendito sea Dios, que no ha rechazado mi oración,\nni ha apartado de mí su misericordia."]],"l":[]},{"i":[[0,"Para el músico principal. En instrumentos de cuerda. Salmo. Cántico."],[1,"Dios tenga piedad de nosotros y nos bendiga;\ny haga resplandecer su rostro sobre nosotros. Selah."],[2,"Para que sea conocido en la tierra tu camino,\ny en todas las naciones tu salvación."],[3,"Te alaben los pueblos, oh Dios;\ntodos los pueblos te alaben."],[4,"Alégrense y canten con júbilo las naciones,\nporque juzgarás a los pueblos con equidad,\ny pastorearás a las naciones en la tierra. Selah."],[5,"Te alaben los pueblos, oh Dios;\ntodos los pueblos te alaben."],[6,"La tierra ha dado su fruto;\nnos bendecirá Dios, el Dios nuestro."],[7,"Bendíganos Dios,\ny témanle todos los confines de la tierra."]],"l":[]},{"i":[[0,"Para el músico principal. Salmo de David. Cántico."],[1,"¡Levántese Dios!\n¡Que sean esparcidos sus enemigos!\nQue huyan de su presencia los que le aborrecen."],[2,"Como es ahuyentado el humo,\nasí ahuyéntalos;\ncomo se derrite la cera ante el fuego,\nasí perezcan los impíos delante de Dios."],[3,"Pero que los justos se alegren.\nQue se regocijen delante de Dios.\nSí, que salten de alegría."],[4,"¡Cantad a Dios! ¡Cantad alabanzas a su nombre!\nExaltad al que cabalga sobre los cielos;\n¡Yah es su nombre!\nAlegraos delante de él."],[5,"Padre de huérfanos y defensor de viudas,\nes Dios en su santa morada."],[6,"Dios hace habitar en familia a los desamparados.\nSaca a los cautivos a la prosperidad,\npero los rebeldes habitan en tierra seca."],[7,"Oh Dios, cuando saliste al frente de tu pueblo,\ncuando marchaste por el desierto... Selah."],[8,"La tierra tembló.\nLos cielos también destilaron lluvia ante la presencia del Dios del Sinaí,\nante la presencia de Dios, el Dios de Israel."],[9,"Tú, oh Dios, enviaste abundante lluvia.\nConfirmaste tu heredad cuando estaba exhausta."],[10,"Tu congregación habitó en ella.\nTú, oh Dios, por tu bondad proveíste para el pobre."],[11,"El Señor dio la palabra.\nGrande es el ejército de las que anuncian las buenas nuevas."],[12,"«¡Huyen los reyes de los ejércitos! ¡Huyen!»\nY la que se queda en casa reparte el botín."],[13,"Aunque reposéis entre los apriscos,\nseréis como las alas de paloma cubiertas de plata,\ny sus plumas de oro resplandeciente."],[14,"Cuando el Omnipotente esparció a los reyes allí,\nnevó en el monte Salmón."],[15,"Monte de Dios es el monte de Basán.\nMonte escarpado es el monte de Basán.",[[29,34,0]]],[16,"¿Por qué miráis con envidia, oh montes escarpados,\nal monte en que Dios deseó habitar?\nCiertamente, Yahvé morará allí para siempre."],[17,"Los carros de Dios se cuentan por veintenas de miles, y por miles de miles.\nEl Señor está entre ellos, como en el Sinaí, en el santuario.",[[114,119,1]]],[18,"Has subido a lo alto.\nHas llevado cautiva a la cautividad.\nHas recibido dones entre los hombres,\nsí, también entre los rebeldes, para que Yah Dios habite allí."],[19,"Bendito sea el Señor, que cada día lleva nuestra carga,\nel Dios que es nuestra salvación. Selah."],[20,"Dios es para nosotros un Dios de salvación.\nY a Yahvé, el Señor, pertenece el libramiento de la muerte."],[21,"Ciertamente Dios herirá la cabeza de sus enemigos,\nla cabellera del que camina en sus pecados."],[22,"El Señor dijo: «De Basán los haré volver;\nlos haré volver de las profundidades del mar,",[[19,24,0]]],[23,"para que tu pie se bañe en sangre,\ny la lengua de tus perros tenga su porción de tus enemigos»."],[24,"Han visto tus marchas, oh Dios,\nlas marchas de mi Dios y mi Rey en el santuario."],[25,"Los cantores iban delante, los músicos detrás,\nen medio de las doncellas tocando panderos."],[26,"«Bendecid a Dios en las congregaciones,\nal Señor, vosotros de la estirpe de Israel»."],[27,"Allí va el pequeño Benjamín, que los guía,\nlos príncipes de Judá con su asamblea,\nlos príncipes de Zabulón y los príncipes de Neftalí."],[28,"Tu Dios ha ordenado tu fuerza.\nConfirma, oh Dios, lo que has obrado para nosotros."],[29,"Por causa de tu templo en Jerusalén,\nlos reyes te traerán presentes.",[[26,35,2]]],[30,"Reprende a la bestia de los cañaverales,\na la manada de toros con los becerros de los pueblos.\nQue se sometan con piezas de plata.\nDispersa a las naciones que se complacen en la guerra."],[31,"Vendrán príncipes de Egipto.\nEtiopía se apresurará a extender sus manos hacia Dios.",[[21,27,3]]],[32,"¡Cantad a Dios, oh reinos de la tierra!\nCantad alabanzas al Señor — Selah —"],[33,"al que cabalga sobre los cielos de los cielos, que son desde la antigüedad.\nHe aquí que él da su voz, voz poderosa."],[34,"¡Atribuid el poder a Dios!\nSu majestad está sobre Israel,\ny su poder está en los cielos."],[35,"Temible eres, oh Dios, desde tus santuarios.\nEl Dios de Israel es quien da fuerza y poder a su pueblo.\n¡Bendito sea Dios!"]],"l":[[154,"Basán",32.80007,35.9373],[1076,"Sinaí",28.53972,33.97333],[622,"Jerusalén",31.77744,35.23494],[353,"Egipto",30.10809,31.33822]]},{"i":[[0,"Para el músico principal. Sobre «Lirios». De David."],[1,"Sálvame, oh Dios,\n¡porque las aguas han entrado hasta el alma!"],[2,"Me hundo en lodo cenagoso, donde no hay donde hacer pie.\nHe llegado a aguas profundas, donde la corriente me anega."],[3,"Cansado estoy de llorar.\nMi garganta se ha secado.\nMis ojos desfallecen esperando a mi Dios."],[4,"Se han aumentado más que los cabellos de mi cabeza los que me odian sin causa.\nSon poderosos mis enemigos, los que injustamente quieren destruirme.\n¿He de pagar lo que no robé?"],[5,"Oh Dios, tú conoces mi insensatez.\nMis pecados no te son ocultos."],[6,"No sean avergonzados por mi causa los que en ti esperan, oh Señor, Yahvé de los ejércitos.\nNo sean deshonrados por mi causa los que te buscan, oh Dios de Israel."],[7,"Porque por amor a ti he sufrido afrenta.\nLa vergüenza ha cubierto mi rostro."],[8,"Me he convertido en un extraño para mis hermanos,\nen un forastero para los hijos de mi madre."],[9,"Porque el celo de tu casa me consume.\nY las afrentas de los que te vituperan han caído sobre mí."],[10,"Lloré y afligí mi alma con ayuno,\ny esto me sirvió de afrenta."],[11,"Cuando me vestí de cilicio,\nme convertí en un refrán para ellos."],[12,"Hablan de mí los que se sientan a la puerta.\nSoy la canción de los bebedores."],[13,"Pero en cuanto a mí, mi oración es a ti, oh Yahvé, en el tiempo propicio.\nOh Dios, por la abundancia de tu misericordia, respóndeme con la verdad de tu salvación."],[14,"Sácame del lodo y no dejes que me hunda.\nLíbrame de los que me odian, y de las aguas profundas."],[15,"No dejes que la corriente de las aguas me anegue,\nni que el abismo me trague.\nNo dejes que el pozo cierre sobre mí su boca."],[16,"Respóndeme, oh Yahvé, porque tu misericordia es buena.\nMírame conforme a la multitud de tus piedades."],[17,"No ocultes tu rostro de tu siervo,\nporque estoy angustiado.\n¡Respóndeme pronto!"],[18,"Acércate a mi alma y redímela.\nRescátame a causa de mis enemigos."],[19,"Tú conoces mi afrenta, mi vergüenza y mi deshonra.\nDelante de ti están todos mis adversarios."],[20,"La afrenta ha quebrantado mi corazón, y estoy acongojado.\nBusqué quien se compadeciera, y no hubo nadie;\nbusqué consoladores, y no hallé ninguno."],[21,"Me pusieron además hiel por comida.\nY en mi sed me dieron a beber vinagre."],[22,"Que su mesa se convierta en un lazo delante de ellos.\nQue se convierta en un tropiezo para su retribución."],[23,"Oscurézcanse sus ojos para que no vean.\nY haz que sus lomos tiemblen continuamente."],[24,"Derrama tu indignación sobre ellos.\nY que el ardor de tu ira los alcance."],[25,"Quede desolada su morada.\nQue nadie habite en sus tiendas."],[26,"Porque persiguen al que tú has herido.\nY cuentan del dolor de aquellos a quienes tú llagaste."],[27,"Añade iniquidad a su iniquidad.\nY no entren ellos en tu justicia."],[28,"Sean borrados del libro de la vida,\ny no sean inscritos con los justos."],[29,"Mas yo estoy afligido y dolorido.\nQue tu salvación, oh Dios, me ponga en alto."],[30,"Alabaré el nombre de Dios con cántico,\ny lo exaltaré con acción de gracias."],[31,"Esto agradará a Yahvé más que el sacrificio de un buey,\no de un novillo con cuernos y pezuñas."],[32,"Lo verán los humildes y se alegrarán.\nVosotros que buscáis a Dios, vivirá vuestro corazón."],[33,"Porque Yahvé escucha a los menesterosos,\ny no menosprecia a sus prisioneros."],[34,"Que lo alaben los cielos y la tierra;\n¡los mares, y todo lo que se mueve en ellos!"],[35,"Porque Dios salvará a Sión, y reedificará las ciudades de Judá.\nY habitarán allí, y la poseerán.",[[22,26,0]]],[36,"La descendencia de sus siervos la heredará.\nY los que aman su nombre habitarán en ella."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Para el músico principal. De David. Para hacer memoria."],[1,"Apresúrate, oh Dios, a librarme.\nVen pronto en mi ayuda, oh Yahvé."],[2,"Sean avergonzados y confundidos los que buscan mi vida.\nSean vueltos atrás y deshonrados los que desean mi ruina."],[3,"Retrocedan por causa de su vergüenza\nlos que dicen: «¡Ajá! ¡Ajá!»"],[4,"Gócense y alégrense en ti todos los que te buscan.\nY digan continuamente los que aman tu salvación:\n«¡Engrandecido sea Dios!»"],[5,"Mas yo estoy afligido y menesteroso.\nApresúrate a mí, oh Dios.\nTú eres mi ayuda y mi libertador.\nOh Yahvé, no te tardes."]],"l":[]},{"i":[[1,"En ti, oh Yahvé, me refugio.\nNo sea yo avergonzado jamás."],[2,"Líbrame en tu justicia y rescátame.\nInclina a mí tu oído, y sálvame."],[3,"Sé para mí una roca de refugio a la que pueda acudir continuamente.\nTú has dado mandamiento para salvarme,\nporque tú eres mi roca y mi fortaleza."],[4,"Rescátame, Dios mío, de la mano del impío,\nde la mano del hombre injusto y cruel."],[5,"Porque tú eres mi esperanza, Señor Yahvé,\nmi confianza desde mi juventud."],[6,"En ti he confiado desde el vientre materno.\nTú eres el que me sacó del vientre de mi madre.\nDe ti será siempre mi alabanza."],[7,"Soy como un prodigio para muchos,\npero tú eres mi refugio fuerte."],[8,"Mi boca se llenará de tu alabanza,\ny de tu gloria todo el día."],[9,"No me rechaces en el tiempo de la vejez.\nNo me abandones cuando me falten las fuerzas."],[10,"Porque mis enemigos hablan contra mí.\nLos que acechan mi vida conspiran juntos,"],[11,"diciendo: «Dios lo ha abandonado.\nPerseguidlo y atrapadlo, porque no hay quien lo rescate»."],[12,"Oh Dios, no te alejes de mí.\nDios mío, apresúrate a socorrerme."],[13,"Sean avergonzados y consumidos los adversarios de mi alma.\nCúbranse de ignominia y de escarnio los que buscan mi mal."],[14,"Pero yo esperaré continuamente,\ny te alabaré más y más."],[15,"Mi boca publicará tu justicia\ny tu salvación todo el día,\naunque no alcanzo a conocer su medida."],[16,"Caminaré en las proezas del Señor Yahvé.\nHaré memoria de tu justicia, de la tuya sola."],[17,"Oh Dios, me has enseñado desde mi juventud.\nY hasta ahora he manifestado tus maravillas."],[18,"Aun en la vejez y las canas, oh Dios, no me desampares,\nhasta que anuncie tu brazo a la posteridad,\ny tu poder a todos los que han de venir."],[19,"Tu justicia, oh Dios, llega hasta lo excelso.\nTú, que has hecho grandes cosas,\noh Dios, ¿quién como tú?"],[20,"Tú, que me has hecho ver muchas y graves angustias,\nvolverás a darme vida.\nY de los abismos de la tierra volverás a levantarme."],[21,"Aumentarás mi grandeza,\ny volverás a consolarme."],[22,"Asimismo yo te alabaré con el salterio, oh Dios mío, por tu fidelidad.\nTe cantaré alabanzas con el arpa, oh Santo de Israel."],[23,"¡Mis labios se alegrarán cuando te cante!\nY mi alma, la cual tú redimiste."],[24,"Mi lengua también hablará de tu justicia todo el día,\nporque han sido avergonzados y confundidos\nlos que buscaban mi mal."]],"l":[]},{"i":[[0,"Para Salomón."],[1,"Oh Dios, da tus juicios al rey,\ny tu justicia al hijo del rey."],[2,"Él juzgará a tu pueblo con justicia,\ny a tus afligidos con rectitud."],[3,"Los montes llevarán paz al pueblo,\ny los collados el fruto de la justicia."],[4,"Juzgará a los pobres del pueblo,\nsalvará a los hijos del menesteroso,\ny quebrantará al opresor."],[5,"Te temerán mientras duren el sol\ny la luna, de generación en generación."],[6,"Descenderá como la lluvia sobre la hierba cortada,\ncomo aguaceros que riegan la tierra."],[7,"Florecerá el justo en sus días,\ny habrá abundancia de paz, hasta que no haya luna."],[8,"Dominará de mar a mar,\ny desde el río hasta los confines de la tierra."],[9,"Ante él se postrarán los moradores del desierto,\ny sus enemigos lamerán el polvo."],[10,"Los reyes de Tarsis y de las costas traerán presentes;\nlos reyes de Sabá y de Seba ofrecerán dones.",[[13,19,0],[78,82,1]]],[11,"Todos los reyes se postrarán delante de él;\ntodas las naciones le servirán."],[12,"Porque él librará al menesteroso que clame,\ny al pobre que no tuviere quien le socorra."],[13,"Tendrá misericordia del pobre y del menesteroso,\ny salvará la vida de los necesitados."],[14,"De engaño y de violencia redimirá sus almas,\ny la sangre de ellos será preciosa ante sus ojos."],[15,"Vivirá, y se le dará del oro de Sabá.\nOrarán por él continuamente;\ntodo el día lo bendecirán.",[[32,36,1]]],[16,"Habrá abundancia de grano en la tierra, en las cumbres de los montes;\nsu fruto ondeará como el Líbano,\ny los de la ciudad florecerán como la hierba del campo.",[[95,101,3]]],[17,"Será su nombre para siempre,\nperdurará su nombre mientras dure el sol.\nSerán benditas en él todas las naciones;\nlo llamarán bienaventurado."],[18,"Bendito sea Yahvé Dios, el Dios de Israel,\nel único que hace maravillas."],[19,"¡Bendito sea su glorioso nombre para siempre!\n¡Toda la tierra sea llena de su gloria!\nAmén y amén."],[20,"Aquí terminan las oraciones de David, hijo de Jesé."]],"l":[[1116,"Tarsis",36.953,-6.37934],[1045,"Saba",9.02274,38.7468],[1016,"Seba",9.02274,38.7468],[707,"Líbano",33.75248,35.5908]]},{"i":[[0,"LIBRO 3"],[0,"Salmo de Asaf."],[1,"Ciertamente Dios es bueno para con Israel,\npara con los limpios de corazón."],[2,"Pero en cuanto a mí, casi se deslizaron mis pies.\nMis pasos estuvieron a punto de resbalar."],[3,"Porque tuve envidia de los arrogantes,\nal ver la prosperidad de los impíos."],[4,"Porque no tienen congojas en su muerte,\nsino que su vigor es firme."],[5,"No pasan trabajos como los demás mortales,\nni son azotados como los demás hombres."],[6,"Por tanto, la soberbia los ciñe como un collar.\nLa violencia los cubre como un vestido."],[7,"Los ojos se les saltan de gordura.\nLos antojos de su corazón se desbordan."],[8,"Se burlan y hablan con malicia.\nCon arrogancia amenazan con la opresión."],[9,"Ponen su boca contra los cielos.\nSu lengua se pasea por la tierra."],[10,"Por eso su pueblo se vuelve a ellos,\ny beben aguas en abundancia."],[11,"Y dicen: «¿Cómo lo sabe Dios?\n¿Acaso hay conocimiento en el Altísimo?»"],[12,"He aquí, estos son los impíos.\nSiempre tranquilos, aumentan sus riquezas."],[13,"Verdaderamente en vano he limpiado mi corazón,\ny lavado mis manos en inocencia,"],[14,"porque todo el día he sido azotado,\ny castigado cada mañana."],[15,"Si yo hubiera dicho: «Hablaré de esta manera»,\nhe aquí, habría traicionado a la generación de tus hijos."],[16,"Cuando traté de comprender esto,\nfue un trabajo demasiado arduo para mí..."],[17,"hasta que entré en el santuario de Dios,\ny comprendí el fin de ellos."],[18,"Ciertamente los has puesto en lugares resbaladizos.\nLos arrojas a la destrucción."],[19,"¡Cómo son destruidos en un momento!\nSon totalmente consumidos por los terrores."],[20,"Como un sueño al despertar,\nasí, oh Señor, cuando te levantes, despreciarás su apariencia."],[21,"Cuando mi alma se llenó de amargura,\ny sentía punzadas en mi corazón,"],[22,"yo era torpe e ignorante.\nEra como una bestia bruta delante de ti."],[23,"Sin embargo, yo estoy continuamente contigo.\nTú me has tomado de la mano derecha."],[24,"Me guiarás con tu consejo,\ny después me recibirás en gloria."],[25,"¿A quién tengo yo en los cielos sino a ti?\nY fuera de ti nada deseo en la tierra."],[26,"Mi carne y mi corazón desfallecen,\npero Dios es la fortaleza de mi corazón y mi porción para siempre."],[27,"Porque he aquí, los que se alejan de ti perecerán.\nTú destruyes a todo aquel que te es infiel."],[28,"Pero en cuanto a mí, el acercarme a Dios es el bien.\nHe puesto en el Señor Yahvé mi refugio,\npara contar todas tus obras."]],"l":[]},{"i":[[0,"Masquil de Asaf."],[1,"Oh Dios, ¿por qué nos has desechado para siempre?\n¿Por qué humea tu furor contra las ovejas de tu prado?"],[2,"Acuérdate de tu congregación, la cual adquiriste desde la antigüedad,\nla cual redimiste para que sea la tribu de tu heredad;\neste monte Sión, en el cual has habitado.",[[130,140,0]]],[3,"Dirige tus pasos a los asolamientos perpetuos;\ntodo el mal que el enemigo ha hecho en el santuario."],[4,"Tus adversarios han rugido en medio de tu asamblea;\nhan puesto sus propias enseñas por señales."],[5,"Parecían como los que levantan el hacha\nen medio de la espesura del bosque."],[6,"Y ahora, con hachas y martillos,\ndestrozan todas sus entalladuras."],[7,"Han prendido fuego a tu santuario;\nhan profanado hasta la tierra la morada de tu Nombre."],[8,"Dijeron en su corazón: «Destruyámoslos de una vez».\nHan quemado todos los lugares de asamblea de Dios en la tierra."],[9,"Ya no vemos nuestras señales milagrosas;\nya no hay profeta,\nni hay entre nosotros quien sepa hasta cuándo."],[10,"¿Hasta cuándo, oh Dios, nos afrentará el adversario?\n¿Blasfemará el enemigo tu nombre para siempre?"],[11,"¿Por qué retiras tu mano, tu mano derecha?\n¡Sácala de tu seno y destrúyelos!"],[12,"Pero Dios es mi Rey desde la antigüedad,\nel que obra salvación en medio de la tierra."],[13,"Tú dividiste el mar con tu poder;\nquebraste las cabezas de los monstruos en las aguas."],[14,"Tú aplastaste las cabezas del Leviatán,\ny lo diste por comida a los moradores del desierto."],[15,"Tú abriste la fuente y el arroyo;\ntú secaste ríos caudalosos."],[16,"Tuyo es el día, tuya también es la noche;\ntú has preparado la luz y el sol."],[17,"Tú estableciste todos los límites de la tierra;\nel verano y el invierno tú los formaste."],[18,"Acuérdate de esto: que el enemigo te ha afrentado, oh Yahvé,\ny que un pueblo insensato ha blasfemado tu nombre."],[19,"No entregues a las fieras el alma de tu tórtola,\ny no olvides para siempre la vida de tus pobres."],[20,"Mira tu pacto,\nporque los lugares tenebrosos de la tierra están llenos de moradas de violencia."],[21,"No vuelva avergonzado el oprimido;\nel afligido y el menesteroso alabarán tu nombre."],[22,"¡Levántate, oh Dios, aboga tu propia causa!\nAcuérdate de cómo el insensato te afrenta cada día."],[23,"No olvides las voces de tus enemigos;\nel tumulto de los que se levantan contra ti sube continuamente."]],"l":[[844,"Monte Sión",31.77744,35.23494]]},{"i":[[0,"Para el músico principal. Sobre «No destruyas». Salmo de Asaf. Cántico."],[1,"Te damos gracias, oh Dios, te damos gracias,\nporque tu Nombre está cerca;\nlos hombres cuentan tus obras maravillosas."],[2,"«Cuando llegue el tiempo señalado,\nyo juzgaré con rectitud."],[3,"Se estremece la tierra y todos sus habitantes,\npero yo sostengo firmemente sus columnas». Selah."],[4,"Dije a los arrogantes: «¡No os jactéis!»\nY a los impíos: «No levantéis el cuerno."],[5,"No levantéis en alto vuestro cuerno,\nni habléis con cerviz erguida»."],[6,"Porque ni del oriente, ni del occidente,\nni del desierto viene el enaltecimiento."],[7,"Mas Dios es el juez;\na uno humilla, y a otro exalta."],[8,"Porque en la mano de Yahvé hay un cáliz,\nlleno de vino espumoso mezclado con especias;\nél lo derrama,\ny todos los impíos de la tierra lo beberán hasta las heces."],[9,"Pero yo lo anunciaré para siempre;\ncantaré alabanzas al Dios de Jacob."],[10,"«Quebrantaré todo el poder de los impíos,\npero el poder de los justos será exaltado»."]],"l":[]},{"i":[[0,"Para el músico principal. Sobre instrumentos de cuerda. Salmo de Asaf. Cántico."],[1,"Dios es conocido en Judá.\nSu nombre es grande en Israel."],[2,"Su tabernáculo está en Salem,\ny su morada en Sión.",[[23,28,0],[45,49,1]]],[3,"Allí quebró las saetas encendidas del arco,\nel escudo, la espada y las armas de guerra. Selah."],[4,"Glorioso eres tú, y majestuoso,\nmás que los montes de caza."],[5,"Los fuertes de corazón fueron despojados,\ndurmieron su sueño;\na ninguno de los hombres de guerra le respondieron las manos."],[6,"A tu reprensión, oh Dios de Jacob,\ntanto el carro como el caballo cayeron en profundo sueño."],[7,"Tú, ciertamente tú, eres temible.\n¿Quién podrá estar en pie delante de ti cuando se enciende tu ira?"],[8,"Desde los cielos hiciste oír el juicio.\nLa tierra temió y guardó silencio,"],[9,"cuando Dios se levantó para juzgar,\npara salvar a todos los mansos de la tierra. Selah."],[10,"Ciertamente la ira del hombre te alabará.\nTú te ceñirás con el resto de la ira."],[11,"¡Haced votos a Yahvé vuestro Dios, y pagadlos!\nQue todos los que están a su alrededor traigan presentes al Temible."],[12,"Él cortará el espíritu de los príncipes.\nTemible es a los reyes de la tierra."]],"l":[[998,"Salem",31.77744,35.23494],[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Para el músico principal. A Jedutún. Salmo de Asaf."],[1,"Con mi voz clamé a Dios;\na Dios clamé, y él me escuchará."],[2,"Al Señor busqué en el día de mi angustia.\nMi mano se extendió de noche sin descanso.\nMi alma rehusaba el consuelo."],[3,"Me acordaba de Dios, y gemía.\nMe quejaba, y desmayaba mi espíritu. Selah."],[4,"Mantienes desvelados mis ojos.\nEstoy tan turbado que no puedo hablar."],[5,"Consideraba los días de antaño,\nlos años de los siglos pasados."],[6,"Me acordaba de mis cánticos de noche.\nMeditaba en mi corazón,\ny mi espíritu inquiría diligentemente:"],[7,"«¿Rechazará el Señor para siempre?\n¿Y no volverá a sernos propicio?"],[8,"¿Ha cesado para siempre su misericordia?\n¿Se ha acabado su promesa por todas las generaciones?"],[9,"¿Ha olvidado Dios el tener compasión?\n¿Ha encerrado con ira sus piedades?» Selah."],[10,"Entonces dije: «Enfermedad mía es esta;\ntraeré, pues, a la memoria los años de la diestra del Altísimo»."],[11,"Me acordaré de las obras de Yah;\nsí, haré memoria de tus maravillas antiguas."],[12,"Meditaré en todas tus obras,\ny hablaré de tus hechos."],[13,"Tu camino, oh Dios, es santo.\n¿Qué dios es tan grande como nuestro Dios?"],[14,"Tú eres el Dios que hace maravillas.\nHas hecho notorio tu poder entre los pueblos."],[15,"Con tu brazo redimiste a tu pueblo,\na los hijos de Jacob y de José. Selah."],[16,"Te vieron las aguas, oh Dios.\nTe vieron las aguas, y temieron.\nLos abismos también se estremecieron."],[17,"Las nubes derramaron aguas.\nTronaron los cielos.\nY tus saetas cruzaron como relámpagos."],[18,"La voz de tu trueno estaba en el torbellino.\nTus relámpagos iluminaron el mundo.\nSe estremeció y tembló la tierra."],[19,"En el mar fue tu camino,\ny tus sendas en las muchas aguas.\nY tus pisadas no fueron conocidas."],[20,"Condujiste a tu pueblo como a un rebaño,\npor mano de Moisés y de Aarón."]],"l":[]},{"i":[[0,"Masquil de Asaf."],[1,"Escucha mi enseñanza, pueblo mío;\ninclina tu oído a las palabras de mi boca."],[2,"Abriré mi boca en parábola;\npronunciaré dichos oscuros de la antigüedad,"],[3,"que hemos oído y conocido,\ny que nuestros padres nos han contado."],[4,"No los ocultaremos a sus hijos,\ncontando a la generación venidera las alabanzas de Yahvé,\nsu poder y las maravillas que ha hecho."],[5,"Porque él estableció un testimonio en Jacob,\ny puso una ley en Israel,\nla cual mandó a nuestros padres\nque la dieran a conocer a sus hijos;"],[6,"para que lo sepa la generación venidera, los niños que han de nacer;\ny los que se levanten lo cuenten a sus hijos,"],[7,"a fin de que pongan en Dios su confianza,\ny no se olviden de las obras de Dios,\nsino que guarden sus mandamientos;"],[8,"y no sean como sus padres,\ngeneración contumaz y rebelde,\ngeneración que no dispuso su corazón,\nni cuyo espíritu fue fiel a Dios."],[9,"Los hijos de Efraín, arqueros armados,\nvolvieron la espalda en el día de la batalla."],[10,"No guardaron el pacto de Dios,\ny se negaron a andar en su ley."],[11,"Se olvidaron de sus obras,\ny de sus maravillas que les había mostrado."],[12,"Cosas maravillosas hizo a la vista de sus padres,\nen la tierra de Egipto, en el campo de Zoán.",[[66,72,0],[89,93,1]]],[13,"Dividió el mar y los hizo pasar;\ne hizo que las aguas se levantaran como un muro."],[14,"De día los guió con una nube,\ny toda la noche con resplandor de fuego."],[15,"Hendió las rocas en el desierto,\ny les dio a beber abundantemente como de los abismos."],[16,"Sacó corrientes de la peña,\ne hizo que las aguas corrieran como ríos."],[17,"Sin embargo, volvieron a pecar contra él,\nrebelándose contra el Altísimo en el desierto."],[18,"Y tentaron a Dios en su corazón,\npidiendo comida a su gusto."],[19,"Sí, hablaron contra Dios,\ndiciendo: «¿Podrá Dios poner mesa en el desierto?"],[20,"He aquí, él hirió la peña y brotaron aguas,\ny torrentes se desbordaron;\n¿podrá también dar pan?\n¿Proveerá de carne a su pueblo?»"],[21,"Por tanto, lo oyó Yahvé y se indignó;\ny se encendió el fuego contra Jacob,\ny el furor subió también contra Israel,"],[22,"porque no creyeron en Dios,\nni confiaron en su salvación."],[23,"Sin embargo, mandó a las nubes de arriba,\ny abrió las puertas de los cielos."],[24,"Hizo llover sobre ellos maná para comer,\ny les dio trigo del cielo."],[25,"Pan de nobles comió el hombre;\nles envió comida hasta saciarles."],[26,"Hizo soplar el viento del este en el cielo,\ny con su poder trajo el viento del sur."],[27,"Hizo llover sobre ellos carne como polvo,\ny aves aladas como arena del mar."],[28,"Las hizo caer en medio de su campamento,\nalrededor de sus tiendas."],[29,"Comieron, pues, y se saciaron;\nles concedió su propio deseo."],[30,"Aún no se habían apartado de su antojo,\naún estaba la comida en sus bocas,"],[31,"cuando la ira de Dios subió contra ellos,\ny mató a los más robustos,\ny derribó a los jóvenes escogidos de Israel."],[32,"A pesar de todo esto, volvieron a pecar,\ny no creyeron en sus maravillas."],[33,"Por tanto, consumió sus días en vanidad,\ny sus años en tribulación."],[34,"Cuando los hería de muerte, entonces le buscaban;\nse volvían y buscaban a Dios con diligencia."],[35,"Se acordaban de que Dios era su roca,\ny el Dios Altísimo su redentor."],[36,"Pero le halagaban con su boca,\ny con su lengua le mentían."],[37,"Porque su corazón no era recto para con él,\nni fueron fieles a su pacto."],[38,"Pero él, siendo misericordioso, perdonaba la iniquidad y no los destruía;\nsí, muchas veces apartó su ira,\ny no despertó todo su furor."],[39,"Se acordó de que no eran más que carne,\nun soplo que pasa y no vuelve."],[40,"¡Cuántas veces se rebelaron contra él en el desierto,\ny lo entristecieron en el yermo!"],[41,"Volvían a tentar a Dios,\ny provocaban al Santo de Israel."],[42,"No se acordaron de su mano,\nni del día en que los redimió del adversario;"],[43,"de cómo puso sus señales en Egipto,\ny sus prodigios en el campo de Zoán.",[[28,34,0],[67,71,1]]],[44,"Convirtió en sangre sus ríos,\ny sus corrientes, para que no pudieran beber."],[45,"Envió entre ellos enjambres de moscas que los devoraban,\ny ranas que los destruían."],[46,"Entregó también a la oruga sus cosechas,\ny el fruto de su trabajo a la langosta."],[47,"Destruyó sus viñas con granizo,\ny sus sicómoros con la escarcha."],[48,"Entregó también su ganado al granizo,\ny sus rebaños a los rayos encendidos."],[49,"Arrojó sobre ellos el ardor de su ira,\nfuror, indignación y angustia,\nun ejército de ángeles destructores."],[50,"Abrió camino a su furor;\nno eximió sus almas de la muerte,\nsino que entregó sus vidas a la mortandad."],[51,"E hirió a todo primogénito en Egipto,\nlas primicias de su vigor en las tiendas de Cam.",[[30,36,0]]],[52,"Pero hizo salir a su pueblo como a ovejas,\ny los condujo por el desierto como a un rebaño."],[53,"Los guió con seguridad, para que no temieran;\npero el mar cubrió a sus enemigos."],[54,"Los trajo a las fronteras de su tierra santa,\na este monte que ganó su diestra."],[55,"Expulsó a las naciones de delante de ellos,\nles repartió una heredad por cordel,\ne hizo habitar en sus tiendas a las tribus de Israel."],[56,"Sin embargo, tentaron y se rebelaron contra el Dios Altísimo,\ny no guardaron sus testimonios;"],[57,"sino que se volvieron atrás y fueron desleales como sus padres;\nse desviaron como un arco engañoso."],[58,"Porque le enojaron con sus lugares altos,\ny le provocaron a celos con sus imágenes esculpidas."],[59,"Lo oyó Dios y se enojó,\ny aborreció en gran manera a Israel."],[60,"Dejó, por tanto, el tabernáculo de Silo,\nla tienda en que habitó entre los hombres.",[[35,39,2]]],[61,"Y entregó su fuerza al cautiverio,\ny su gloria en manos del enemigo."],[62,"Entregó también su pueblo a la espada,\ny se airó contra su heredad."],[63,"El fuego devoró a sus jóvenes,\ny sus vírgenes no tuvieron cantos nupciales."],[64,"Sus sacerdotes cayeron a espada,\ny sus viudas no hicieron lamentación."],[65,"Entonces despertó el Señor como de un sueño,\ncomo un valiente que grita excitado por el vino."],[66,"E hirió a sus enemigos por la espalda;\nlos cubrió de afrenta perpetua."],[67,"Además desechó la tienda de José,\ny no escogió a la tribu de Efraín;"],[68,"sino que escogió a la tribu de Judá,\nel monte Sión, al cual amó.",[[40,50,3]]],[69,"Edificó su santuario como las alturas,\ncomo la tierra que ha cimentado para siempre."],[70,"Eligió a David su siervo,\ny lo tomó de las majadas de las ovejas;"],[71,"de andar tras las ovejas paridas lo trajo,\npara pastorear a Jacob su pueblo,\ny a Israel su heredad."],[72,"Y él los pastoreó según la integridad de su corazón,\ny los guió con la destreza de sus manos."]],"l":[[353,"Egipto",30.10809,31.33822],[1245,"Zoán",30.97462,31.88417],[1059,"Silo",32.0557,35.28953],[844,"Monte Sión",31.77744,35.23494]]},{"i":[[0,"Salmo de Asaf."],[1,"Oh Dios, las naciones han invadido tu heredad.\nHan profanado tu santo templo.\nHan reducido a Jerusalén a montones de ruinas.",[[93,102,0]]],[2,"Han entregado los cadáveres de tus siervos para que sean alimento de las aves del cielo,\nla carne de tus santos a las fieras de la tierra."],[3,"Han derramado su sangre como agua alrededor de Jerusalén,\ny no hubo quien los enterrara.",[[47,56,0]]],[4,"Nos hemos convertido en afrenta para nuestros vecinos,\nen escarnio y burla de los que nos rodean."],[5,"¿Hasta cuándo, oh Yahvé?\n¿Estarás airado para siempre?\n¿Arderá tu celo como el fuego?"],[6,"Derrama tu ira sobre las naciones que no te conocen,\nsobre los reinos que no invocan tu nombre,"],[7,"porque han devorado a Jacob,\ny han asolado su morada."],[8,"No recuerdes contra nosotros las iniquidades de nuestros antepasados.\nQue tus tiernas misericordias nos alcancen pronto,\nporque estamos muy abatidos."],[9,"Ayúdanos, oh Dios de nuestra salvación, por la gloria de tu nombre.\nLíbranos y perdona nuestros pecados, por amor de tu nombre."],[10,"¿Por qué han de decir las naciones: «Dónde está su Dios»?\nSea notoria en las naciones, delante de nuestros ojos,\nla venganza de la sangre derramada de tus siervos."],[11,"Llegue hasta ti el gemido de los cautivos.\nSegún la grandeza de tu poder, preserva a los sentenciados a muerte."],[12,"Y devuelve a nuestros vecinos siete veces en su seno\nla afrenta con que te han afrentado, oh Señor."],[13,"Así nosotros, pueblo tuyo y ovejas de tu prado,\nte daremos gracias para siempre.\nTe alabaremos de generación en generación."]],"l":[[622,"Jerusalén",31.77744,35.23494]]},{"i":[[0,"Para el músico principal. Sobre «Los lirios del testimonio». Salmo de Asaf."],[1,"Escucha, oh Pastor de Israel,\ntú que pastoreas a José como a un rebaño;\ntú que estás sentado entre los querubines, resplandece."],[2,"Despierta tu poder delante de Efraín, de Benjamín y de Manasés,\ny ven a salvarnos."],[3,"¡Restáuranos, oh Dios!\nHaz resplandecer tu rostro,\ny seremos salvos."],[4,"Oh Yahvé, Dios de los ejércitos,\n¿hasta cuándo estarás airado contra la oración de tu pueblo?"],[5,"Les has dado a comer pan de lágrimas,\ny les has dado a beber lágrimas en gran abundancia."],[6,"Nos pones por contienda a nuestros vecinos,\ny nuestros enemigos se burlan entre sí."],[7,"¡Restáuranos, oh Dios de los ejércitos!\nHaz resplandecer tu rostro,\ny seremos salvos."],[8,"Hiciste venir una vid de Egipto;\nexpulsaste a las naciones, y la plantaste.",[[25,31,0]]],[9,"Limpiaste el terreno delante de ella,\ne echó raíces profundas y llenó la tierra."],[10,"Los montes fueron cubiertos con su sombra,\ny sus ramas eran como cedros de Dios."],[11,"Extendió sus ramas hasta el mar,\ny sus renuevos hasta el río."],[12,"¿Por qué has derribado sus vallados,\npara que la arranquen todos los que pasan por el camino?"],[13,"El jabalí del bosque la destroza,\ny las bestias del campo se alimentan de ella."],[14,"Vuélvete, te rogamos, oh Dios de los ejércitos;\nmira desde el cielo, y ve, y visita esta vid,"],[15,"la cepa que plantó tu diestra,\ny el renuevo que hiciste fuerte para ti."],[16,"Quemada está al fuego, está talada;\nperezcan por la reprensión de tu rostro."],[17,"Sea tu mano sobre el varón de tu diestra,\nsobre el hijo de hombre que para ti afirmaste."],[18,"Así no nos apartaremos de ti;\ndanos vida, e invocaremos tu nombre."],[19,"¡Restáuranos, oh Yahvé, Dios de los ejércitos!\nHaz resplandecer tu rostro, y seremos salvos."]],"l":[[353,"Egipto",30.10809,31.33822]]},{"i":[[0,"Para el músico principal. Sobre Gitit. De Asaf."],[1,"¡Cantad con gozo a Dios, fortaleza nuestra!\n¡Aclamad con júbilo al Dios de Jacob!"],[2,"Entonad canción, y traed el pandero,\nel arpa deliciosa y el salterio."],[3,"Tocad la trompeta en la nueva luna,\nen el día de la luna llena, en el día de nuestra fiesta solemne."],[4,"Porque estatuto es de Israel,\nordenanza del Dios de Jacob."],[5,"Lo estableció como testimonio en José,\ncuando salió por la tierra de Egipto.\nOí un lenguaje que no entendía:",[[69,75,0]]],[6,"«Aparté su hombro de la carga;\nsus manos fueron libradas del cesto."],[7,"En la angustia clamaste, y yo te libré;\nte respondí en el escondedero del trueno;\nte probé en las aguas de Meribá. Selah.",[[107,113,1]]],[8,"Oye, pueblo mío, y te amonestaré;\n¡Israel, si me oyeres!"],[9,"No habrá en ti dios ajeno,\nni te inclinarás a dios extranjero."],[10,"Yo soy Yahvé tu Dios,\nque te hizo subir de la tierra de Egipto;\nabre tu boca, y yo la llenaré.",[[56,62,0]]],[11,"Pero mi pueblo no oyó mi voz,\ne Israel no me quiso a mí."],[12,"Los dejé, por tanto, a la dureza de su corazón,\npara que caminaran en sus propios consejos."],[13,"¡Oh, si me hubiera oído mi pueblo,\nsi Israel hubiera andado en mis caminos!"],[14,"En un momento yo habría sometido a sus enemigos,\ny habría vuelto mi mano contra sus adversarios."],[15,"Los que aborrecen a Yahvé se le habrían sometido,\ny su castigo sería para siempre."],[16,"Pero a ti te habría alimentado con lo mejor del trigo,\ny con miel de la peña te habría saciado»."]],"l":[[353,"Egipto",30.10809,31.33822],[768,"Meribá",30.68771,34.4948]]},{"i":[[0,"Salmo de Asaf."],[1,"Dios está en la asamblea de los dioses;\nen medio de los dioses él juzga:"],[2,"«¿Hasta cuándo juzgaréis injustamente,\ny aceptaréis a las personas de los impíos? Selah."],[3,"Defended al débil y al huérfano;\nhaced justicia al afligido y al menesteroso."],[4,"Librad al afligido y al necesitado;\nrescatadlo de la mano de los impíos»."],[5,"No saben, ni entienden.\nAndan en tinieblas;\ntiemblan todos los cimientos de la tierra."],[6,"Yo dije: «Vosotros sois dioses,\ny todos vosotros hijos del Altísimo;"],[7,"pero como hombres moriréis,\ny caeréis como cualquiera de los príncipes»."],[8,"Levántate, oh Dios, juzga la tierra;\nporque tú heredarás todas las naciones."]],"l":[]},{"i":[[0,"Cántico. Salmo de Asaf."],[1,"Oh Dios, no guardes silencio;\nno calles, oh Dios, ni te quedes quieto."],[2,"Porque he aquí que braman tus enemigos,\ny los que te aborrecen han alzado la cabeza."],[3,"Contra tu pueblo han consultado astuta y secretamente;\nhan conspirado contra tus protegidos."],[4,"Han dicho: «Venid, y destruyámoslos para que no sean nación,\ny no haya más memoria del nombre de Israel»."],[5,"Porque se han confabulado de un mismo corazón;\ncontra ti han hecho alianza"],[6,"las tiendas de los edomitas y de los ismaelitas,\nMoab y los agarenos;",[[49,53,1]]],[7,"Gebal, Amón y Amalec,\nlos filisteos y los habitantes de Tiro.",[[0,5,2],[7,11,3],[14,20,4],[56,60,5]]],[8,"También Asiria se ha juntado con ellos;\nsirven de brazo a los hijos de Lot. Selah."],[9,"Hazles como a Madián,\ncomo a Sísara, como a Jabín en el arroyo de Cisón;",[[14,20,6]]],[10,"que perecieron en Endor,\ny fueron hechos como estiércol para la tierra.",[[18,23,7]]],[11,"Pon a sus nobles como a Oreb y a Zeeb;\na todos sus príncipes como a Zeba y a Zalmuna,"],[12,"que dijeron: «Heredemos para nosotros las moradas de Dios»."],[13,"Dios mío, ponlos como hojarasca,\ncomo paja delante del viento."],[14,"Como fuego que quema el monte,\ncomo llama que abrasa el bosque."],[15,"Persíguelos así con tu tempestad,\ny aterrorízalos con tu huracán."],[16,"Llena sus rostros de vergüenza,\npara que busquen tu nombre, oh Yahvé."],[17,"Sean afrentados y turbados para siempre;\nsean deshonrados, y perezcan."],[18,"Y conozcan que tu nombre es Yahvé;\n¡tú solo eres Altísimo sobre toda la tierra!"]],"l":[[348,"Edom",30.73469,35.60625],[800,"Moab",31.49685,35.78284],[441,"Gebal",34.1191,35.64614],[56,"Amón",31.95019,35.92413],[51,"Amalec",30.65977,34.83555],[1162,"Tiro",33.27583,35.19257],[781,"Madián",28.93288,34.90832],[372,"Endor",32.6257,35.38567]]},{"i":[[0,"Para el músico principal. Sobre Gitit. Salmo de los hijos de Coré."],[1,"¡Cuán amables son tus moradas,\noh Yahvé de los ejércitos!"],[2,"Anhela mi alma y aun ardientemente desea los atrios de Yahvé;\nmi corazón y mi carne cantan al Dios vivo."],[3,"Aun el gorrión halla casa,\ny la golondrina nido para sí, donde ponga sus polluelos,\ncerca de tus altares, oh Yahvé de los ejércitos, Rey mío y Dios mío."],[4,"Bienaventurados los que habitan en tu casa;\nperpetuamente te alabarán. Selah."],[5,"Bienaventurado el hombre que tiene en ti sus fuerzas,\nen cuyo corazón están tus caminos."],[6,"Atravesando el valle de lágrimas lo cambian en fuente,\ncuando la lluvia temprana lo cubre de bendiciones.",[[15,32,0]]],[7,"Irán de poder en poder;\nverán a Dios en Sión.",[[40,44,1]]],[8,"Yahvé Dios de los ejércitos, oye mi oración;\nescucha, oh Dios de Jacob. Selah."],[9,"Mira, oh Dios, escudo nuestro,\ny pon los ojos en el rostro de tu ungido."],[10,"Porque mejor es un día en tus atrios que mil fuera de ellos.\nEscogería antes estar a la puerta de la casa de mi Dios,\nque habitar en las moradas de maldad."],[11,"Porque sol y escudo es Yahvé Dios;\ngracia y gloria dará Yahvé.\nNo quitará el bien a los que andan en integridad."],[12,"Yahvé de los ejércitos,\ndichoso el hombre que en ti confía."]],"l":[[1177,"Valle de lágrimas",31.76908,35.22799],[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Para el músico principal. Salmo de los hijos de Coré."],[1,"Fuiste propicio a tu tierra, oh Yahvé;\nhas hecho volver a Jacob de su cautiverio."],[2,"Perdonaste la iniquidad de tu pueblo;\ncubriste todos sus pecados. Selah."],[3,"Reprimiste todo tu enojo;\nte apartaste del ardor de tu ira."],[4,"Restáuranos, oh Dios de nuestra salvación,\ny haz cesar tu indignación contra nosotros."],[5,"¿Estarás airado con nosotros para siempre?\n¿Prolongarás tu ira de generación en generación?"],[6,"¿No volverás a darnos vida,\npara que tu pueblo se regocije en ti?"],[7,"Muéstranos, oh Yahvé, tu misericordia,\ny concédenos tu salvación."],[8,"Escucharé lo que hablará Yahvé Dios,\nporque hablará paz a su pueblo y a sus santos,\npara que no se vuelvan a la insensatez."],[9,"Ciertamente cercana está su salvación a los que le temen,\npara que habite la gloria en nuestra tierra."],[10,"La misericordia y la verdad se encontraron;\nla justicia y la paz se besaron."],[11,"La verdad brotará de la tierra,\ny la justicia mirará desde los cielos."],[12,"Yahvé también dará el bien,\ny nuestra tierra dará su fruto."],[13,"La justicia irá delante de él,\ny nos pondrá en el camino de sus pasos."]],"l":[]},{"i":[[0,"Oración de David."],[1,"Inclina, oh Yahvé, tu oído, y escúchame,\nporque soy pobre y menesteroso."],[2,"Guarda mi alma, porque soy piadoso;\nsalva tú, oh Dios mío, a tu siervo que en ti confía."],[3,"Ten misericordia de mí, oh Señor,\nporque a ti clamo todo el día."],[4,"Alegra el alma de tu siervo,\nporque a ti, oh Señor, elevo mi alma."],[5,"Porque tú, Señor, eres bueno y perdonador,\ny grande en misericordia para con todos los que te invocan."],[6,"Escucha, oh Yahvé, mi oración,\ny atiende a la voz de mis ruegos."],[7,"En el día de mi angustia te invocaré,\nporque tú me respondes."],[8,"Oh Señor, ninguno hay como tú entre los dioses,\nni obras que igualen tus obras."],[9,"Todas las naciones que hiciste vendrán y adorarán delante de ti, Señor,\ny glorificarán tu nombre."],[10,"Porque tú eres grande, y hacedor de maravillas;\nsólo tú eres Dios."],[11,"Enséñame, oh Yahvé, tu camino;\ncaminaré en tu verdad.\nAfirma mi corazón para que tema tu nombre."],[12,"Te alabaré, oh Señor Dios mío, con todo mi corazón,\ny glorificaré tu nombre para siempre."],[13,"Porque tu misericordia es grande para conmigo,\ny has librado mi alma de las profundidades del Seol."],[14,"Oh Dios, los soberbios se levantaron contra mí,\ny conspiración de violentos ha buscado mi vida,\ny no te pusieron delante de sí."],[15,"Mas tú, Señor, Dios misericordioso y clemente,\nlento para la ira, y grande en misericordia y verdad,"],[16,"mírame, y ten misericordia de mí.\nDa tu fortaleza a tu siervo,\ny salva al hijo de tu sierva."],[17,"Haz conmigo señal para bien,\ny véanla los que me aborrecen, y sean avergonzados;\nporque tú, Yahvé, me ayudaste y me consolaste."]],"l":[]},{"i":[[0,"Salmo de los hijos de Coré. Cántico."],[1,"Su cimiento está en los montes santos."],[2,"Ama Yahvé las puertas de Sión\nmás que todas las moradas de Jacob.",[[25,29,0]]],[3,"Cosas gloriosas se han dicho de ti,\noh ciudad de Dios. Selah."],[4,"“Mencionaré a Rahab y a Babilonia entre los que me conocen;\nhe aquí Filistea y Tiro, con Etiopía;\nse dirá: «Este nació allá»».",[[14,19,1],[24,33,2],[68,76,3],[79,83,4]]],[5,"Y de Sión se dirá: «Este y aquel han nacido en ella»;\ny el Altísimo mismo la establecerá.",[[5,9,0]]],[6,"Yahvé contará al inscribir a los pueblos:\n«Este nació allí». Selah."],[7,"Y cantores y tañedores en ella dirán:\n«Todas mis fuentes están en ti»."]],"l":[[1239,"Sión",31.77744,35.23494],[948,"Rahab",30.10809,31.33822],[146,"Babilonia",32.5365,44.42088],[922,"Filistea",33.56317,35.36635],[1162,"Tiro",33.27583,35.19257]]},{"i":[[0,"Cántico. Salmo de los hijos de Coré. Para el músico principal. Sobre Mahalat Leamot. Masquil de Hemán ezraíta."],[1,"Oh Yahvé, Dios de mi salvación,\ndía y noche clamo delante de ti."],[2,"Llegue mi oración a tu presencia;\ninclina tu oído a mi clamor."],[3,"Porque mi alma está hastiada de males,\ny mi vida cercana al Seol."],[4,"Soy contado entre los que descienden al foso;\nsoy como hombre sin fuerza,"],[5,"abandonado entre los muertos,\ncomo los pasados a espada que yacen en el sepulcro,\nde quienes no te acuerdas ya,\ny que han sido arrebatados de tu mano."],[6,"Me has puesto en el hoyo profundo,\nen las tinieblas, en los abismos."],[7,"Sobre mí reposa tu ira,\ny me has afligido con todas tus olas. Selah."],[8,"Has alejado de mí a mis conocidos;\nme has hecho abominable para ellos.\nEstoy encerrado y no puedo salir."],[9,"Mis ojos languidecen a causa de la aflicción.\nTe he invocado, oh Yahvé, cada día;\nhe extendido mis manos hacia ti."],[10,"¿Manifestarás tus maravillas a los muertos?\n¿Se levantarán los muertos para alabarte? Selah."],[11,"¿Será declarada en el sepulcro tu misericordia,\no tu fidelidad en el Abadón?"],[12,"¿Serán conocidas en las tinieblas tus maravillas,\ny tu justicia en la tierra del olvido?"],[13,"Mas yo a ti he clamado, oh Yahvé,\ny de mañana mi oración se presenta delante de ti."],[14,"¿Por qué, oh Yahvé, desechas mi alma?\n¿Por qué escondes de mí tu rostro?"],[15,"Yo estoy afligido y a punto de morir desde mi juventud;\nsufro tus terrores, y estoy consternado."],[16,"Sobre mí han pasado tus iras,\ny tus terrores me han destruido."],[17,"Me han rodeado como aguas continuamente;\na una me han cercado."],[18,"Has alejado de mí al amigo y al compañero,\ny las tinieblas son mis conocidas."]],"l":[]},{"i":[[0,"Masquil de Etán ezraíta."],[1,"Las misericordias de Yahvé cantaré perpetuamente;\nde generación en generación haré notoria tu fidelidad con mi boca."],[2,"Porque dije: Para siempre será edificada la misericordia;\nen los cielos mismos establecerás tu fidelidad."],[3,"“Hice pacto con mi escogido;\njuré a David mi siervo:"],[4,"«Para siempre estableceré tu descendencia,\ny edificaré tu trono por todas las generaciones»». Selah."],[5,"Celebrarán los cielos tus maravillas, oh Yahvé,\ntu fidelidad también en la congregación de los santos."],[6,"Porque ¿quién en los cielos se igualará a Yahvé?\n¿Quién será semejante a Yahvé entre los hijos de los potentados?"],[7,"Dios temible en la gran congregación de los santos,\ny formidable sobre todos cuantos están a su alrededor."],[8,"Oh Yahvé, Dios de los ejércitos, ¿quién como tú?\nPoderoso eres, Yahvé, y tu fidelidad te rodea."],[9,"Tú dominas la furia del mar;\ncuando se levantan sus olas, tú las sosiegas."],[10,"Tú quebrantaste a Rahab como a un herido de muerte;\ncon tu brazo poderoso esparciste a tus enemigos.",[[18,23,0]]],[11,"Tuyos son los cielos, tuya también la tierra;\nel mundo y su plenitud, tú los fundaste."],[12,"El norte y el sur, tú los creaste;\nel Tabor y el Hermón cantan gozosos a tu nombre.",[[38,43,1],[49,55,2]]],[13,"Tuyo es el brazo poderoso;\nfuerte es tu mano, exaltada tu diestra."],[14,"Justicia y juicio son el cimiento de tu trono;\nmisericordia y verdad van delante de tu rostro."],[15,"Bienaventurado el pueblo que sabe aclamarte;\nandarán, oh Yahvé, a la luz de tu rostro."],[16,"En tu nombre se alegrarán todo el día,\ny en tu justicia serán enaltecidos."],[17,"Porque tú eres la gloria de su poder,\ny por tu buena voluntad exaltarás nuestro cuerno."],[18,"Porque Yahvé es nuestro escudo,\ny nuestro rey es el Santo de Israel."],[19,"Entonces hablaste en visión a tus santos,\ny dijiste: “He puesto el socorro sobre un valiente;\nhe exaltado a un escogido de mi pueblo."],[20,"Hallé a David mi siervo;\nlo ungí con mi santo aceite."],[21,"Mi mano estará siempre con él,\ny mi brazo lo fortalecerá."],[22,"No lo sorprenderá el enemigo,\nni el hijo de iniquidad lo quebrantará."],[23,"Sino que quebrantaré delante de él a sus enemigos,\ny heriré a los que le aborrecen."],[24,"Mi fidelidad y mi misericordia estarán con él,\ny en mi nombre será exaltado su cuerno."],[25,"Pondré también su mano sobre el mar,\ny su diestra sobre los ríos."],[26,"Él me clamará: «Mi Padre eres tú,\nmi Dios, y la roca de mi salvación»."],[27,"Yo también le haré mi primogénito,\nel más excelso de los reyes de la tierra."],[28,"Para siempre le conservaré mi misericordia,\ny mi pacto será firme con él."],[29,"Estableceré su descendencia para siempre,\ny su trono como los días de los cielos."],[30,"Si dejaren sus hijos mi ley,\ny no anduvieren en mis juicios;"],[31,"si profanaren mis estatutos,\ny no guardaren mis mandamientos,"],[32,"entonces castigaré con vara su rebelión,\ny con azotes sus iniquidades."],[33,"Mas no quitaré de él mi misericordia,\nni falsearé mi fidelidad."],[34,"No olvidaré mi pacto,\nni alteraré lo que ha salido de mis labios."],[35,"Una vez he jurado por mi santidad,\ny no mentiré a David:"],[36,"Su descendencia será para siempre,\ny su trono como el sol delante de mí."],[37,"Como la luna será firme para siempre,\ny como un testigo fiel en el cielo”. Selah."],[38,"Mas tú lo has desechado y menospreciado;\nte has airado contra tu ungido."],[39,"Has roto el pacto de tu siervo;\nhas profanado su corona arrojándola por tierra."],[40,"Has derribado todos sus vallados;\nhas convertido en ruinas sus fortalezas."],[41,"Lo saquean todos los que pasan por el camino;\nes oprobio a sus vecinos."],[42,"Has exaltado la diestra de sus enemigos;\nhas alegrado a todos sus adversarios."],[43,"También embotaste el filo de su espada,\ny no lo levantaste en la batalla."],[44,"Hiciste cesar su esplendor,\ny echaste su trono por tierra."],[45,"Has acortado los días de su juventud;\nlo has cubierto de vergüenza. Selah."],[46,"¿Hasta cuándo, oh Yahvé?\n¿Te esconderás para siempre?\n¿Arderá tu ira como el fuego?"],[47,"Recuerda cuán breve es mi tiempo;\n¿por qué habrás creado en vano a todos los hijos del hombre?"],[48,"¿Qué hombre vivirá y no verá la muerte?\n¿Librará su vida del poder del Seol? Selah."],[49,"Señor, ¿dónde están tus antiguas misericordias,\nque juraste a David por tu fidelidad?"],[50,"Acuérdate, Señor, del oprobio de tus siervos;\noprobio de muchos pueblos, que llevo en mi seno;"],[51,"con el cual tus enemigos, oh Yahvé, te han deshonrado;\ncon el cual han deshonrado los pasos de tu ungido."],[52,"¡Bendito sea Yahvé para siempre!\nAmén, y amén."]],"l":[[948,"Rahab",30.10809,31.33822],[1107,"Tabor",32.68696,35.39091],[551,"Hermón",33.41616,35.85726]]},{"i":[[0,"LIBRO 4"],[0,"Oración de Moisés, varón de Dios."],[1,"Señor, tú has sido nuestro refugio de generación en generación."],[2,"Antes que naciesen los montes,\ny formases la tierra y el mundo,\ndesde la eternidad y hasta la eternidad, tú eres Dios."],[3,"Tú reduces al hombre a polvo, y dices:\n«¡Volved, hijos de los hombres!»"],[4,"Porque mil años delante de tus ojos son como el día de ayer, que ya pasó,\ny como una de las vigilias de la noche."],[5,"Los arrebatas como con torrente de aguas; son como un sueño.\nPor la mañana son como la hierba que crece."],[6,"Por la mañana florece y crece;\na la tarde es cortada y se seca."],[7,"Porque con tu furor somos consumidos,\ny con tu ira somos turbados."],[8,"Has puesto nuestras iniquidades delante de ti,\nnuestros pecados ocultos a la luz de tu rostro."],[9,"Porque todos nuestros días declinan a causa de tu ira;\nacabamos nuestros años como un suspiro."],[10,"Los días de nuestra edad son setenta años;\ny si en los más robustos son ochenta años,\ncon todo, su mayor orgullo es fatiga y trabajo,\nporque pronto pasan, y volamos."],[11,"¿Quién conoce el poder de tu ira,\ny tu indignación según el temor que te es debido?"],[12,"Enséñanos de tal modo a contar nuestros días,\nque traigamos al corazón sabiduría."],[13,"¡Vuelve, oh Yahvé! ¿Hasta cuándo?\n¡Ten compasión de tus siervos!"],[14,"Sácianos de mañana con tu misericordia,\npara que nos regocijemos y nos alegremos todos nuestros días."],[15,"Alégranos conforme a los días que nos afligiste,\ny los años en que hemos visto el mal."],[16,"Manifiéstese tu obra a tus siervos,\ny tu gloria a sus hijos."],[17,"Sea la luz del Señor nuestro Dios sobre nosotros,\ny confirma en nosotros la obra de nuestras manos.\nSí, la obra de nuestras manos confirma."]],"l":[]},{"i":[[1,"El que habita al abrigo del Altísimo\nmorará bajo la sombra del Todopoderoso."],[2,"Diré yo a Yahvé: «Esperanza mía, y castillo mío;\nmi Dios, en quien confiaré»."],[3,"Él te librará del lazo del cazador,\ny de la peste destructora."],[4,"Con sus plumas te cubrirá,\ny debajo de sus alas estarás seguro;\nescudo y adarga es su verdad."],[5,"No temerás el terror nocturno,\nni saeta que vuele de día,"],[6,"ni pestilencia que ande en oscuridad,\nni mortandad que en medio del día destruya."],[7,"Caerán a tu lado mil,\ny diez mil a tu diestra;\nmas a ti no llegará."],[8,"Ciertamente con tus ojos mirarás,\ny verás la recompensa de los impíos."],[9,"Porque has puesto a Yahvé, que es mi esperanza,\nal Altísimo por tu habitación,"],[10,"no te sobrevendrá mal,\nni plaga tocará tu morada."],[11,"Pues a sus ángeles mandará acerca de ti,\nque te guarden en todos tus caminos."],[12,"En las manos te llevarán,\npara que tu pie no tropiece en piedra."],[13,"Sobre el león y el áspid pisarás;\nhollarás al cachorro del león y a la serpiente."],[14,"«Por cuanto en mí ha puesto su amor, yo también lo libraré;\nle pondré en alto, por cuanto ha conocido mi nombre."],[15,"Me invocará, y yo le responderé;\ncon él estaré yo en la angustia;\nlo libraré y le glorificaré."],[16,"Lo saciaré de larga vida,\ny le mostraré mi salvación»."]],"l":[]},{"i":[[0,"Salmo. Cántico para el día de reposo."],[1,"Bueno es dar gracias a Yahvé,\ny cantar alabanzas a tu nombre, oh Altísimo;"],[2,"anunciar por la mañana tu misericordia,\ny tu fidelidad cada noche,"],[3,"con el decacordio y con el salterio,\nen tono suave con el arpa."],[4,"Por cuanto me has alegrado, oh Yahvé, con tus obras;\nen las obras de tus manos me gozaré."],[5,"¡Cuán grandes son tus obras, oh Yahvé!\nMuy profundos son tus pensamientos."],[6,"El hombre insensato no lo sabe,\ny el necio no entiende esto:"],[7,"que brotan los impíos como la hierba,\ny florecen todos los que hacen iniquidad,\npara ser destruidos eternamente."],[8,"Mas tú, Yahvé, para siempre eres Altísimo."],[9,"Porque he aquí tus enemigos, oh Yahvé,\nporque he aquí, perecerán tus enemigos;\nserán esparcidos todos los que hacen maldad."],[10,"Pero tú exaltarás mi cuerno como el del búfalo;\nseré ungido con aceite fresco."],[11,"Y mirarán mis ojos la ruina de mis enemigos;\noirán mis oídos de la caída de los malignos que se levantaron contra mí."],[12,"El justo florecerá como la palmera;\ncrecerá como cedro en el Líbano.",[[61,67,0]]],[13,"Plantados en la casa de Yahvé,\nen los atrios de nuestro Dios florecerán."],[14,"Aun en la vejez fructificarán;\nestarán llenos de savia y verdor,"],[15,"para anunciar que Yahvé mi fortaleza es recto,\ny que en él no hay injusticia."]],"l":[[707,"Líbano",33.75248,35.5908]]},{"i":[[1,"¡Yahvé reina! Se ha vestido de majestad;\nYahvé se ha vestido, se ha ceñido de poder.\nAfirmó también el mundo,\ny no será conmovido."],[2,"Tu trono está establecido desde la antigüedad;\ntú eres desde la eternidad."],[3,"Alzaron los ríos, oh Yahvé,\nlos ríos alzaron su voz;\nalzaron los ríos sus ondas."],[4,"Más que el estruendo de las muchas aguas,\nmás que las recias olas del mar,\npoderoso es Yahvé en las alturas."],[5,"Tus testimonios son muy firmes;\nla santidad conviene a tu casa,\noh Yahvé, por los siglos y para siempre."]],"l":[]},{"i":[[1,"Oh Yahvé, Dios de las venganzas,\nDios de las venganzas, ¡muéstrate!"],[2,"Levántate, Juez de la tierra;\nda el pago a los soberbios."],[3,"¿Hasta cuándo los impíos, oh Yahvé,\nhasta cuándo triunfarán los impíos?"],[4,"Pronuncian y hablan insolencias;\nse jactan todos los que hacen iniquidad."],[5,"A tu pueblo, oh Yahvé, quebrantan,\ny a tu heredad afligen."],[6,"Matan a la viuda y al extranjero,\ny asesinan a los huérfanos."],[7,"Y dicen: «No lo verá Yah,\nni lo entenderá el Dios de Jacob»."],[8,"Entended, necios del pueblo;\ny vosotros, fatuos, ¿cuándo seréis sabios?"],[9,"El que hizo el oído, ¿no oirá?\nEl que formó el ojo, ¿no verá?"],[10,"El que castiga a las naciones, ¿no reprenderá?\n¿No sabrá el que enseña al hombre la ciencia?"],[11,"Yahvé conoce los pensamientos de los hombres,\nque son vanidad."],[12,"Bienaventurado el hombre a quien tú disciplinas, oh Yah,\ny a quien instruyes en tu ley,"],[13,"para darle descanso en los días de aflicción,\nen tanto que para el impío se cava el hoyo."],[14,"Porque Yahvé no rechazará a su pueblo,\nni desamparará su heredad."],[15,"Sino que el juicio será vuelto a la justicia,\ny en pos de ella irán todos los rectos de corazón."],[16,"¿Quién se levantará por mí contra los malignos?\n¿Quién me defenderá de los que hacen iniquidad?"],[17,"Si Yahvé no me hubiera ayudado,\npronto habría habitado mi alma en el silencio."],[18,"Cuando yo decía: «¡Mi pie resbala!»,\ntu misericordia, oh Yahvé, me sustentaba."],[19,"En la multitud de mis pensamientos íntimos,\ntus consolaciones alegraban mi alma."],[20,"¿Se aliará contigo el trono de iniquidad,\nque forja agravios bajo forma de ley?"],[21,"Se juntan contra la vida del justo,\ny condenan la sangre inocente."],[22,"Mas Yahvé ha sido mi alto refugio,\ny mi Dios la roca de mi confianza."],[23,"Él hará volver sobre ellos su propia iniquidad,\ny los destruirá en su propia maldad;\nlos destruirá Yahvé nuestro Dios."]],"l":[]},{"i":[[1,"¡Venid, aclamemos alegremente a Yahvé!\n¡Cantemos con júbilo a la roca de nuestra salvación!"],[2,"Lleguemos ante su presencia con alabanza;\n¡aclamémosle con cánticos!"],[3,"Porque Yahvé es Dios grande,\ny Rey grande sobre todos los dioses."],[4,"Porque en su mano están las profundidades de la tierra,\ny las alturas de los montes son suyas."],[5,"Suyo también es el mar, pues él lo hizo;\ny sus manos formaron la tierra seca."],[6,"Venid, adoremos y postrémonos;\narrodillémonos delante de Yahvé nuestro Hacedor."],[7,"Porque él es nuestro Dios;\nnosotros el pueblo de su prado, y ovejas de su mano.\nSi oyereis hoy su voz,"],[8,"no endurezcáis vuestro corazón, como en Meribá,\ncomo en el día de Masah en el desierto,"],[9,"donde me tentaron vuestros padres,\nme probaron, y vieron mis obras."],[10,"Cuarenta años estuve disgustado con aquella generación,\ny dije: «Es un pueblo que divaga de corazón,\ny no han conocido mis caminos»."],[11,"Por tanto, juré en mi furor\nque no entrarían en mi reposo."]],"l":[]},{"i":[[1,"¡Cantad a Yahvé un cántico nuevo!\n¡Cantad a Yahvé, toda la tierra!"],[2,"¡Cantad a Yahvé!\n¡Bendecid su nombre!\n¡Proclamad su salvación de día en día!"],[3,"Anunciad su gloria entre las naciones,\nsus obras maravillosas entre todos los pueblos."],[4,"Porque grande es Yahvé, y digno de suprema alabanza;\ntemible sobre todos los dioses."],[5,"Porque todos los dioses de los pueblos son ídolos;\npero Yahvé hizo los cielos."],[6,"Alabanza y magnificencia hay delante de él;\npoder y hermosura en su santuario."],[7,"Tributad a Yahvé, oh familias de los pueblos,\ntributad a Yahvé la gloria y el poder."],[8,"Dad a Yahvé la honra debida a su nombre;\ntraed ofrendas, y venid a sus atrios."],[9,"Adorad a Yahvé en la hermosura de la santidad;\ntemblad delante de él, toda la tierra."],[10,"Decid entre las naciones: «¡Yahvé reina!»\nAfirmó también el mundo,\ny no será conmovido;\nél juzgará a los pueblos con equidad."],[11,"Alégrense los cielos, y gócese la tierra;\n¡ruja el mar y su plenitud!"],[12,"¡Regocíjese el campo, y todo lo que en él hay!\nEntonces todos los árboles del bosque cantarán de júbilo"],[13,"delante de Yahvé; porque él viene,\nporque viene a juzgar la tierra.\nÉl juzgará al mundo con justicia,\ny a los pueblos con su verdad."]],"l":[]},{"i":[[1,"¡Yahvé reina! ¡Regocíjese la tierra!\n¡Alégrense las muchas costas!"],[2,"Nubes y oscuridad le rodean;\njusticia y juicio son el cimiento de su trono."],[3,"Fuego va delante de él,\ny abrasa a sus enemigos en derredor."],[4,"Sus relámpagos iluminaron el mundo;\nla tierra lo vio y se estremeció."],[5,"Los montes se derritieron como cera delante de Yahvé,\ndelante del Señor de toda la tierra."],[6,"Los cielos anuncian su justicia,\ny todos los pueblos ven su gloria."],[7,"Avergüéncense todos los que sirven a las imágenes de talla,\nlos que se glorían en los ídolos.\n¡Póstrense ante él todos los dioses!"],[8,"Sión lo oyó y se alegró,\ny las hijas de Judá se regocijaron\na causa de tus juicios, oh Yahvé.",[[0,4,0]]],[9,"Porque tú, Yahvé, eres excelso sobre toda la tierra;\neres muy exaltado sobre todos los dioses."],[10,"Los que amáis a Yahvé, aborreced el mal;\nél guarda las almas de sus santos;\nde mano de los impíos los libra."],[11,"Luz está sembrada para el justo,\ny alegría para los rectos de corazón."],[12,"¡Alegraos, justos, en Yahvé!\nY dad gracias a su santo Nombre."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Salmo."],[1,"Cantad a Yahvé cántico nuevo,\nporque ha hecho maravillas;\nsu diestra y su santo brazo le han dado la victoria."],[2,"Yahvé ha hecho notoria su salvación;\na vista de las naciones ha descubierto su justicia."],[3,"Se ha acordado de su misericordia y de su fidelidad para con la casa de Israel;\ntodos los confines de la tierra han visto la salvación de nuestro Dios."],[4,"¡Aclamad con júbilo a Yahvé, toda la tierra!\n¡Prorrumpid, alegraos y cantad salmos!"],[5,"Cantad salmos a Yahvé con arpa,\ncon arpa y voz de cántico."],[6,"Con trompetas y sonido de bocina,\naclamad con júbilo delante del Rey Yahvé."],[7,"Ruja el mar y su plenitud,\nel mundo y los que en él habitan;"],[8,"los ríos batan las palmas,\nlos montes se regocijen a una,"],[9,"delante de Yahvé, porque viene a juzgar la tierra.\nJuzgará al mundo con justicia,\ny a los pueblos con equidad."]],"l":[]},{"i":[[1,"¡Yahvé reina! Temblarán los pueblos.\nÉl está sentado sobre los querubines; conmuévase la tierra."],[2,"Yahvé en Sión es grande,\ny excelso sobre todos los pueblos.",[[9,13,0]]],[3,"Alaben tu nombre grande y temible;\n¡Él es santo!"],[4,"El poder del rey ama la justicia;\ntú confirmas la equidad.\nTú has ejecutado el derecho y la justicia en Jacob."],[5,"Exaltad a Yahvé nuestro Dios,\ny postraos ante el estrado de sus pies.\n¡Él es santo!"],[6,"Moisés y Aarón entre sus sacerdotes,\ny Samuel entre los que invocaron su nombre;\ninvocaban a Yahvé, y él les respondía."],[7,"En columna de nube hablaba con ellos;\nguardaban sus testimonios,\ny el estatuto que les había dado."],[8,"Yahvé Dios nuestro, tú les respondías;\nles fuiste un Dios perdonador,\npero vengador de sus malas obras."],[9,"Exaltad a Yahvé nuestro Dios,\ny postraos ante su santo monte,\nporque Yahvé nuestro Dios es santo."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Salmo de acción de gracias."],[1,"¡Cantad alegres a Yahvé, habitantes de toda la tierra!"],[2,"Servid a Yahvé con alegría;\nvenid ante su presencia con regocijo."],[3,"Reconoced que Yahvé es Dios;\nél nos hizo, y suyos somos;\npueblo suyo somos, y ovejas de su prado."],[4,"Entrad por sus puertas con acción de gracias,\npor sus atrios con alabanza;\nalabadle, bendecid su nombre."],[5,"Porque Yahvé es bueno;\npara siempre es su misericordia,\ny su fidelidad por todas las generaciones."]],"l":[]},{"i":[[0,"Un salmo de David."],[1,"Cantaré a la misericordia y a la justicia.\nA ti, Yahvé, te cantaré alabanzas."],[2,"Me esforzaré en seguir el camino de la integridad.\n¿Cuándo vendrás a mí?\nCaminaré dentro de mi casa con un corazón íntegro."],[3,"No pondré cosa vil delante de mis ojos.\nAborrezco las obras de los que se desvían.\nNada de ello se me pegará."],[4,"El corazón perverso se apartará de mí.\nNo querré conocer el mal."],[5,"Al que solapadamente calumnia a su prójimo, yo lo silenciaré.\nNo soportaré al de ojos altaneros y corazón soberbio."],[6,"Pondré mis ojos en los fieles de la tierra,\npara que moren conmigo.\nEl que camina por la senda de la perfección,\nese me servirá."],[7,"No habitará dentro de mi casa quien practique el fraude.\nEl que habla con mentiras no se sostendrá ante mis ojos."],[8,"Cada mañana destruiré a todos los impíos de la tierra,\npara extirpar de la ciudad de Yahvé a todos los que hacen el mal."]],"l":[]},{"i":[[0,"Oración del afligido, cuando está agobiado y derrama su queja ante Yahvé."],[1,"¡Escucha mi oración, Yahvé!\nDeja que mi clamor llegue a ti."],[2,"No escondas tu rostro de mí en el día de mi angustia.\nInclina a mí tu oído.\nRespóndeme pronto el día que te invoque."],[3,"Porque mis días se desvanecen como el humo.\nMis huesos arden como un tizón."],[4,"Mi corazón se ha marchitado y secado como la hierba,\nde tal modo que olvido comer mi pan."],[5,"A causa de la voz de mis gemidos,\nmis huesos se pegan a mi piel."],[6,"Soy como el pelícano del desierto.\nMe he vuelto como el búho de las ruinas."],[7,"Paso las noches en vela, y me he vuelto como un pájaro solitario en el tejado."],[8,"Mis enemigos me ofenden todo el día.\nLos que están enfurecidos conmigo usan mi nombre como maldición."],[9,"Porque he comido cenizas como pan,\ny mezclé mi bebida con lágrimas,"],[10,"a causa de tu indignación y tu ira;\nporque me has cogido y me has arrojado."],[11,"Mis días son como una sombra que se alarga.\nMe he marchitado como la hierba."],[12,"Pero tú, Yahvé, permaneces para siempre;\ntu recuerdo perdura por todas las generaciones."],[13,"Te levantarás y tendrás piedad de Sión,\npues es tiempo de apiadarse de ella.\nSí, ha llegado el momento fijado.",[[34,38,0]]],[14,"Porque tus siervos aman sus piedras,\ny se compadecen de su polvo."],[15,"Así las naciones temerán el nombre de Yahvé,\ny todos los reyes de la tierra tu gloria."],[16,"Porque Yahvé habrá edificado a Sión.\nSe habrá manifestado en su gloria.",[[31,35,0]]],[17,"Habrá atendido a la oración de los desvalidos,\ny no habrá despreciado sus ruegos."],[18,"Esto se escribirá para la generación venidera.\nUn pueblo aún por ser creado alabará a Yah,"],[19,"porque ha mirado desde lo alto de su santuario.\nDesde el cielo, Yahvé observó la tierra,"],[20,"para escuchar los gemidos de los cautivos,\npara liberar a los condenados a muerte,"],[21,"para que los hombres anuncien el nombre de Yahvé en Sión,\ny su alabanza en Jerusalén,",[[52,56,0],[75,84,1]]],[22,"cuando los pueblos se reúnan,\njunto con los reinos, para servir a Yahvé."],[23,"Él debilitó mis fuerzas en el camino.\nAcortó mis días."],[24,"Dije: «Dios mío, no me lleves a la mitad de mis días.\nTus años son por todas las generaciones»."],[25,"Desde la antigüedad tú fundaste la tierra.\nLos cielos son obra de tus manos."],[26,"Ellos perecerán, pero tú permanecerás.\nSí, todos ellos se desgastarán como una vestidura.\nLos cambiarás como un manto, y serán transformados."],[27,"Pero tú eres el mismo.\nTus años no tendrán fin."],[28,"Los hijos de tus siervos habitarán seguros.\nSu descendencia se establecerá delante de ti."]],"l":[[1239,"Sión",31.77744,35.23494],[622,"Jerusalén",31.77744,35.23494]]},{"i":[[0,"Por David."],[1,"¡Bendice a Yahvé, alma mía!\nY bendiga todo mi ser su santo nombre."],[2,"Bendice a Yahvé, alma mía,\ny no olvides ninguno de sus beneficios."],[3,"Él es quien perdona todas tus iniquidades,\nquien sana todas tus dolencias,"],[4,"quien rescata tu vida del sepulcro,\nquien te corona de favores y misericordias,"],[5,"quien sacia de bien tus anhelos,\nde modo que te rejuvenezcas como el águila."],[6,"Yahvé ejecuta obras de justicia,\ny defiende el derecho de todos los oprimidos."],[7,"Dio a conocer sus caminos a Moisés,\ny sus proezas a los hijos de Israel."],[8,"Clemente y compasivo es Yahvé,\nlento para la ira, y grande en misericordia."],[9,"No contenderá para siempre,\nni guardará su enojo perpetuamente."],[10,"No nos ha tratado según nuestros pecados,\nni nos ha pagado conforme a nuestras iniquidades."],[11,"Porque como se alzan los cielos sobre la tierra,\nasí de grande es su misericordia para con los que le temen."],[12,"Tan lejos como está el oriente del occidente,\nasí hizo alejar de nosotros nuestras rebeliones."],[13,"Como un padre se compadece de sus hijos,\nasí se compadece Yahvé de los que le temen."],[14,"Porque él conoce nuestra condición.\nSe acuerda de que somos polvo."],[15,"En cuanto al hombre, sus días son como la hierba.\nFlorece como la flor del campo,"],[16,"pero pasa el viento sobre ella, y desaparece,\ny su lugar no la vuelve a conocer."],[17,"Mas la misericordia de Yahvé es desde la eternidad y hasta la eternidad sobre los que le temen,\ny su justicia sobre los hijos de los hijos,"],[18,"sobre los que guardan su pacto,\ny los que se acuerdan de sus preceptos para ponerlos por obra."],[19,"Yahvé ha establecido su trono en los cielos,\ny su reino domina sobre todo."],[20,"Bendecid a Yahvé, vosotros sus ángeles,\npoderosos en fortaleza, que ejecutáis su palabra,\nobedeciendo la voz de su precepto."],[21,"Bendecid a Yahvé, vosotros todos sus ejércitos,\nministros suyos, que hacéis su voluntad."],[22,"Bendecid a Yahvé, vosotras todas sus obras,\nen todos los lugares de su señorío.\n¡Bendice a Yahvé, alma mía!"]],"l":[]},{"i":[[1,"Bendice a Yahvé, alma mía.\nYahvé, Dios mío, eres inmensamente grande.\nEstás revestido de gloria y majestad."],[2,"Te cubres de luz como de una vestidura.\nExtiendes los cielos como una cortina."],[3,"Estableces las vigas de tus aposentos en las aguas.\nHaces de las nubes tu carro.\nCaminas sobre las alas del viento."],[4,"Haces de los vientos tus mensajeros,\ny de las llamas de fuego tus servidores."],[5,"Tú pusiste los cimientos de la tierra,\npara que no sea conmovida jamás."],[6,"La cubriste con el abismo como con un manto.\nLas aguas estaban por encima de los montes."],[7,"Ante tu reprensión huyeron.\nA la voz de tu trueno se apresuraron a alejarse."],[8,"Se elevaron los montes,\ndescendieron los valles,\nal lugar que les habías asignado."],[9,"Has establecido un límite que no pueden traspasar,\npara que no vuelvan a cubrir la tierra."],[10,"Tú envías manantiales a los valles.\nCorren entre los montes."],[11,"Dan de beber a todas las bestias del campo.\nLos asnos monteses sacian su sed."],[12,"Junto a ellos anidan las aves del cielo.\nCantan entre las ramas."],[13,"Riegas los montes desde tus aposentos.\nLa tierra se sacia del fruto de tus obras."],[14,"Haces crecer la hierba para el ganado,\ny las plantas para que el hombre las cultive,\npara sacar de la tierra el alimento:"],[15,"el vino que alegra el corazón del hombre,\nel aceite para hacer brillar su rostro,\ny el pan que fortalece el corazón del hombre."],[16,"Los árboles de Yahvé están bien regados,\nlos cedros del Líbano que él plantó,",[[56,62,0]]],[17,"donde los pájaros hacen sus nidos.\nLa cigüeña tiene su morada en los cipreses."],[18,"Las altas montañas son para las cabras monteses.\nLas rocas son un refugio para los damanes."],[19,"Él designó la luna para medir las estaciones.\nEl sol sabe cuándo ponerse."],[20,"Traes las tinieblas, y cae la noche,\nen la que merodean todas las fieras del bosque."],[21,"Los leoncillos rugen tras su presa,\ny buscan en Dios su alimento."],[22,"Sale el sol y se retiran,\ny se acuestan en sus guaridas."],[23,"El hombre sale a su obra,\na su labor hasta el atardecer."],[24,"¡Yahvé, cuán numerosas son tus obras!\nA todas las hiciste con sabiduría.\nLa tierra está llena de tus criaturas."],[25,"Allí está el mar, grande y vasto,\nen el que hay innumerables seres vivos,\nanimales tanto pequeños como grandes."],[26,"Allí surcan las naves,\ny el Leviatán, que formaste para jugar en él."],[27,"Todos ellos esperan en ti,\npara que les des su comida a su debido tiempo."],[28,"Tú les das, y ellos recogen.\nAbres tu mano, y se sacian de bienes."],[29,"Escondes tu rostro, y se turban.\nLes quitas el aliento, mueren y vuelven al polvo."],[30,"Envías tu Espíritu, y son creados.\nAsí renuevas la faz de la tierra."],[31,"Que la gloria de Yahvé sea eterna.\nQue Yahvé se regocije en sus obras."],[32,"Él mira la tierra y ésta tiembla.\nToca los montes y éstos echan humo."],[33,"Cantaré a Yahvé mientras viva.\nCantaré alabanzas a mi Dios mientras exista."],[34,"Que mi meditación le sea agradable.\nYo me regocijaré en Yahvé."],[35,"Que los pecadores desaparezcan de la tierra.\nQue los malvados dejen de existir.\nBendice a Yahvé, alma mía.\n¡Alabado sea Yah!"]],"l":[[707,"Líbano",33.75248,35.5908]]},{"i":[[1,"¡Dad gracias a Yahvé! ¡Invocad su nombre!\nHaced notorias sus obras entre los pueblos."],[2,"¡Cantadle, cantadle alabanzas!\nHablad de todas sus maravillas."],[3,"Gloriaos en su santo nombre.\nAlégrese el corazón de los que buscan a Yahvé."],[4,"Buscad a Yahvé y su poder.\nBuscad su rostro continuamente."],[5,"Acordaos de las maravillas que ha hecho:\nde sus prodigios, y de los juicios de su boca,"],[6,"oh vosotros, descendencia de Abraham, su siervo,\nvosotros, hijos de Jacob, sus elegidos."],[7,"Él es Yahvé, nuestro Dios.\nSus juicios están en toda la tierra."],[8,"Se ha acordado de su pacto para siempre,\nde la palabra que mandó para mil generaciones,"],[9,"del pacto que hizo con Abraham,\nde su juramento a Isaac,"],[10,"el cual confirmó a Jacob por estatuto,\na Israel por pacto eterno,"],[11,"diciendo: «A ti te daré la tierra de Canaán,\ncomo la porción de tu heredad».",[[37,43,0]]],[12,"Cuando no eran más que unos pocos hombres,\nsí, muy pocos, y forasteros en ella,"],[13,"y andaban de nación en nación,\nde un reino a otro pueblo,"],[14,"no permitió que nadie les oprimiera.\nSí, por amor a ellos reprendió a los reyes:"],[15,"«¡No toquéis a mis ungidos!\nNo hagáis daño a mis profetas»."],[16,"Llamó al hambre sobre la tierra.\nDestruyó todo el sustento de pan."],[17,"Envió a un hombre delante de ellos.\nJosé fue vendido como esclavo."],[18,"Afligieron sus pies con grillos.\nSu cuello fue puesto entre cadenas de hierro,"],[19,"hasta el momento en que se cumplió su palabra,\ny el oráculo de Yahvé lo probó."],[20,"El rey envió y lo liberó,\nel soberano de los pueblos lo dejó libre."],[21,"Lo hizo señor de su casa,\ny gobernador de todas sus posesiones,"],[22,"para instruir a sus príncipes a su antojo,\ny para enseñar sabiduría a sus ancianos."],[23,"Entonces Israel también llegó a Egipto.\nJacob moró en la tierra de Cam.",[[32,38,1],[67,70,2]]],[24,"Multiplicó a su pueblo en gran manera,\ny los hizo más fuertes que sus adversarios."],[25,"Cambió el corazón de ellos para que odiaran a su pueblo,\npara que conspiraran contra sus siervos."],[26,"Envió a Moisés, su siervo,\ny a Aarón, a quien había elegido."],[27,"Pusieron entre ellos sus señales,\ny prodigios en la tierra de Cam.",[[62,65,2]]],[28,"Envió tinieblas y oscureció la tierra,\ny no fueron rebeldes a sus palabras."],[29,"Convirtió sus aguas en sangre,\ny mató a sus peces."],[30,"Su tierra se llenó de ranas,\nincluso en los aposentos de sus reyes."],[31,"Habló, y vinieron enjambres de moscas,\ny mosquitos en todas sus fronteras."],[32,"Les dio granizo por lluvia,\ncon llamas de fuego en su tierra."],[33,"Hirió sus viñas y también sus higueras,\ny destrozó los árboles de su territorio."],[34,"Él habló, y vinieron las langostas\ncon los saltamontes, innumerables."],[35,"Se comieron toda la hierba de su país,\ny devoraron el fruto de su tierra."],[36,"También hirió a todos los primogénitos de su tierra,\nlas primicias de todo su vigor."],[37,"Los sacó con plata y oro,\ny no hubo en sus tribus quien tropezara."],[38,"Egipto se alegró cuando partieron,\nporque el terror hacia ellos había caído sobre los egipcios.",[[0,6,1]]],[39,"Extendió una nube para cubrirlos,\ny fuego para alumbrar la noche."],[40,"Pidieron, y él hizo venir codornices,\ny los sació con pan del cielo."],[41,"Abrió la roca y brotaron las aguas.\nCorrieron por los sequedales como un río."],[42,"Porque se acordó de su santa palabra,\ny de Abraham, su siervo."],[43,"Sacó a su pueblo con alegría,\na sus elegidos con cantos de júbilo."],[44,"Les entregó las tierras de las naciones.\nTomaron en posesión el fruto del trabajo de los pueblos,"],[45,"para que guardaran sus estatutos,\ny observaran sus leyes.\n¡Alabado sea Yah!"]],"l":[[265,"Canaán",31.69353,34.84388],[353,"Egipto",30.10809,31.33822],[503,"Cam",30.10809,31.33822]]},{"i":[[1,"¡Alabado sea Yahvé!\nDad gracias a Yahvé, porque él es bueno,\nporque su misericordia es eterna."],[2,"¿Quién podrá proclamar las proezas de Yahvé,\no declarar plenamente todas sus alabanzas?"],[3,"Dichosos los que guardan el derecho,\ndichoso el que hace justicia en todo tiempo."],[4,"Acuérdate de mí, Yahvé, con el favor que muestras a tu pueblo.\nVisítame con tu salvación,"],[5,"para que vea yo la prosperidad de tus elegidos,\npara que me regocije con la alegría de tu nación,\npara que me gloríe con tu heredad."],[6,"Pecamos al igual que nuestros padres.\nHemos cometido iniquidad.\nHemos hecho el mal."],[7,"Nuestros padres no comprendieron tus maravillas en Egipto.\nNo recordaron la multitud de tus misericordias,\nsino que se rebelaron junto al mar, en el Mar Rojo.",[[51,57,0],[149,157,1]]],[8,"Sin embargo, los salvó por amor de su nombre,\npara dar a conocer su gran poder."],[9,"Reprendió al Mar Rojo, y se secó;\ny los condujo por los abismos como por un desierto.",[[13,21,1]]],[10,"Los salvó de la mano del que los odiaba,\ny los redimió de la mano del enemigo."],[11,"Las aguas cubrieron a sus adversarios.\nNo quedó ni uno solo de ellos."],[12,"Entonces creyeron en sus palabras,\ny cantaron sus alabanzas."],[13,"Pero pronto olvidaron sus obras.\nNo esperaron su consejo,"],[14,"sino que se entregaron a la codicia en el desierto,\ny tentaron a Dios en el páramo."],[15,"Él les concedió lo que pedían,\npero envió mortandad sobre ellos."],[16,"Tuvieron envidia de Moisés en el campamento,\ny de Aarón, el consagrado a Yahvé."],[17,"La tierra se abrió y se tragó a Datán,\ny cubrió a la cuadrilla de Abiram."],[18,"Se encendió un fuego en su grupo,\ny la llama consumió a los impíos."],[19,"Hicieron un becerro en Horeb,\ny adoraron una imagen de fundición.",[[23,28,2]]],[20,"Así cambiaron su gloria\npor la imagen de un buey que come hierba."],[21,"Se olvidaron de Dios, su Salvador,\nque había hecho grandezas en Egipto,",[[64,70,0]]],[22,"obras maravillosas en la tierra de Cam,\ny cosas formidables junto al Mar Rojo.",[[35,38,3],[69,77,1]]],[23,"Por eso dijo que los destruiría,\nsi Moisés, su elegido, no se hubiera puesto en la brecha delante de él,\npara apartar su ira y que no los destruyese."],[24,"Además, despreciaron la tierra deseable.\nNo creyeron en su palabra,"],[25,"sino que murmuraron en sus tiendas,\ny no escucharon la voz de Yahvé."],[26,"Por eso les juró con mano alzada\nque los haría caer en el desierto,"],[27,"que haría caer a su descendencia entre las naciones,\ny los dispersaría por las tierras."],[28,"Se unieron también a Baal Peor,\ny comieron de los sacrificios ofrecidos a los muertos.",[[26,30,4]]],[29,"Así provocaron su ira con sus malas obras,\ny la peste se desató sobre ellos."],[30,"Entonces Finees se levantó e hizo justicia,\ny la plaga se detuvo."],[31,"Y le fue contado por justicia,\nde generación en generación, para siempre."],[32,"También le enfurecieron en las aguas de Meribá,\ny le fue mal a Moisés por causa de ellos;"],[33,"porque amargaron su espíritu,\ny él habló precipitadamente con sus labios."],[34,"No destruyeron a los pueblos,\ncomo Yahvé les había ordenado,"],[35,"sino que se mezclaron con las naciones,\ny aprendieron sus costumbres."],[36,"Sirvieron a sus ídolos,\nlos cuales se convirtieron en una trampa para ellos."],[37,"Sí, sacrificaron a sus hijos y a sus hijas a los demonios."],[38,"Derramaron sangre inocente,\nla sangre de sus hijos y de sus hijas,\na quienes sacrificaron a los ídolos de Canaán;\ny la tierra fue profanada con sangre.",[[106,112,5]]],[39,"Así se contaminaron con sus obras,\ny se prostituyeron con sus hechos."],[40,"Por eso se encendió la ira de Yahvé contra su pueblo,\ny abominó su heredad."],[41,"Los entregó en manos de las naciones,\ny los que los odiaban se enseñorearon de ellos."],[42,"Sus enemigos también los oprimieron,\ny fueron sometidos bajo su mano."],[43,"Muchas veces los libró,\npero ellos se rebelaron contra su consejo,\ny fueron humillados por su iniquidad."],[44,"Sin embargo, él miró su angustia,\ncuando escuchó su clamor."],[45,"Se acordó de su pacto con ellos,\ny se compadeció conforme a la multitud de sus misericordias."],[46,"Hizo además que se apiadaran de ellos\ntodos los que los tenían cautivos."],[47,"Sálvanos, Yahvé, Dios nuestro,\ny reúnenos de entre las naciones,\npara dar gracias a tu santo nombre,\ny para gloriarnos en tu alabanza."],[48,"Bendito sea Yahvé, el Dios de Israel,\n¡desde la eternidad y hasta la eternidad!\nQue todo el pueblo diga: «Amén».\n¡Alabado sea Yah!"]],"l":[[353,"Egipto",30.10809,31.33822],[965,"Mar Rojo",27.08847,34.77173],[563,"Horeb",28.53972,33.97333],[503,"Cam",30.10809,31.33822],[912,"Peor",31.76503,35.71856],[265,"Canaán",31.69353,34.84388]]},{"i":[[0,"LIBRO 5"],[1,"Dad gracias a Yahvé, porque él es bueno,\nporque su misericordia es eterna."],[2,"Que lo digan los redimidos de Yahvé,\na quienes ha redimido de la mano del adversario,"],[3,"y ha congregado de las tierras,\ndel oriente y del occidente,\ndel norte y del sur."],[4,"Vagaron por el desierto, por caminos desolados.\nNo hallaron ciudad donde habitar."],[5,"Hambrientos y sedientos,\nsu alma desfallecía en ellos."],[6,"Entonces clamaron a Yahvé en su angustia,\ny él los libró de sus aflicciones."],[7,"Los condujo por un camino recto,\npara que llegaran a una ciudad habitable."],[8,"¡Alaben a Yahvé por su misericordia,\ny por sus maravillas para con los hijos de los hombres!"],[9,"Porque él satisface al alma sedienta,\ny llena de bienes al alma hambrienta."],[10,"Algunos moraban en tinieblas y en sombra de muerte,\naprisionados en aflicción y en hierros,"],[11,"porque se rebelaron contra las palabras de Dios,\ny despreciaron el consejo del Altísimo."],[12,"Por eso humilló sus corazones con trabajo pesado.\nTropezaron, y no hubo quien los ayudase."],[13,"Entonces clamaron a Yahvé en su angustia,\ny los salvó de sus aflicciones."],[14,"Los sacó de las tinieblas y de la sombra de muerte,\ny rompió sus cadenas."],[15,"¡Alaben a Yahvé por su misericordia,\ny por sus maravillas para con los hijos de los hombres!"],[16,"Porque ha destrozado las puertas de bronce,\ny ha hecho pedazos los cerrojos de hierro."],[17,"Los necios, a causa de su camino rebelde,\ny por sus iniquidades, fueron afligidos."],[18,"Su alma aborreció todo tipo de alimento.\nLlegaron hasta las puertas de la muerte."],[19,"Entonces clamaron a Yahvé en su angustia,\ny los salvó de sus aflicciones."],[20,"Envió su palabra y los sanó,\ny los libró de sus sepulcros."],[21,"¡Alaben a Yahvé por su misericordia,\ny por sus maravillas para con los hijos de los hombres!"],[22,"Que ofrezcan sacrificios de acción de gracias,\ny declaren sus obras con cantos de júbilo."],[23,"Los que descienden al mar en naves,\nlos que hacen negocios en las inmensas aguas,"],[24,"estos han visto las obras de Yahvé,\ny sus maravillas en las profundidades."],[25,"Porque él manda y levanta el viento tempestuoso,\nque encrespa sus olas."],[26,"Suben a los cielos, descienden a los abismos.\nSu alma se derrite ante el peligro."],[27,"Tiemblan y titubean como un ebrio,\ny toda su pericia se desvanece."],[28,"Entonces claman a Yahvé en su angustia,\ny los libra de sus aflicciones."],[29,"Cambia la tempestad en sosiego,\ny se apaciguan sus olas."],[30,"Se alegran entonces porque se han calmado,\ny así los guía al puerto deseado."],[31,"¡Alaben a Yahvé por su misericordia,\ny por sus maravillas para con los hijos de los hombres!"],[32,"Que lo exalten en la congregación del pueblo,\ny lo alaben en la reunión de los ancianos."],[33,"Convierte los ríos en desierto,\ny los manantiales en tierra sedienta,"],[34,"y la tierra fructífera en salinas,\npor la maldad de los que la habitan."],[35,"Convierte el desierto en estanques de agua,\ny la tierra seca en manantiales."],[36,"Allí establece a los hambrientos,\npara que funden una ciudad donde habitar,"],[37,"siembren campos, planten viñedos,\ny recojan el fruto de sus cosechas."],[38,"Los bendice, y se multiplican en gran manera.\nNo permite que disminuya su ganado."],[39,"Pero si luego son reducidos y humillados\na causa de la opresión, la desgracia y el dolor,"],[40,"él derrama menosprecio sobre los príncipes,\ny los hace vagar por un desierto sin caminos."],[41,"Sin embargo, levanta al pobre de su miseria,\ny multiplica sus familias como a un rebaño."],[42,"Los rectos lo verán y se alegrarán.\nY toda iniquidad cerrará su boca."],[43,"Quien sea sabio, que observe estas cosas,\ny considere las misericordias de Yahvé."]],"l":[]},{"i":[[0,"Cántico. Salmo de David."],[1,"Mi corazón está dispuesto, oh Dios.\nCantaré y entonaré salmos con todo mi ser."],[2,"¡Despertad, arpa y lira!\n¡Despertaré a la aurora!"],[3,"Te daré gracias, Yahvé, entre los pueblos.\nTe cantaré alabanzas entre las naciones."],[4,"Porque tu misericordia es más grande que los cielos,\ny tu fidelidad alcanza hasta las nubes."],[5,"¡Exáltate, oh Dios, sobre los cielos!\n¡Que tu gloria sea sobre toda la tierra!"],[6,"Para que tus amados sean librados,\nsalva con tu diestra y respóndenos."],[7,"Dios ha hablado en su santuario: «Me regocijaré;\nrepartiré a Siquem, y mediré el valle de Sucot.",[[61,67,0],[90,95,1]]],[8,"Mío es Galaad, mío es Manasés.\nEfraín es el yelmo de mi cabeza;\nJudá es mi cetro.",[[7,13,2]]],[9,"Moab es la jofaina en que me lavo.\nSobre Edom arrojaré mi sandalia.\nSobre Filistea gritaré triunfante».",[[0,4,3],[41,45,4],[74,82,5]]],[10,"¿Quién me llevará a la ciudad fortificada?\n¿Quién me guiará hasta Edom?",[[66,70,4]]],[11,"¿No eres tú, oh Dios, quien nos ha rechazado?\nYa no sales, oh Dios, con nuestros ejércitos."],[12,"Danos socorro contra el adversario,\nporque vana es la ayuda del hombre."],[13,"En Dios haremos proezas,\nporque él pisoteará a nuestros enemigos."]],"l":[[1047,"Siquem",32.21369,35.2818],[1199,"Valle de Sucot",32.19998,35.63331],[466,"Galaad",32.04252,35.72424],[800,"Moab",31.49685,35.78284],[348,"Edom",30.73469,35.60625],[922,"Filistea",33.56317,35.36635]]},{"i":[[0,"Para el director del coro. Salmo de David."],[1,"Oh Dios de mi alabanza, no guardes silencio,"],[2,"porque han abierto contra mí la boca del impío y la boca del engaño.\nHan hablado contra mí con lengua mentirosa."],[3,"Me han rodeado de palabras de odio,\ny han peleado contra mí sin causa."],[4,"En pago de mi amor me son adversarios,\nmas yo me entrego a la oración."],[5,"Me han devuelto mal por bien,\ny odio por mi amor."],[6,"Pon a un impío sobre él,\ny que un adversario se ponga a su diestra."],[7,"Cuando sea juzgado, que salga culpable.\nQue su oración se convierta en pecado."],[8,"Que sus días sean pocos.\nQue otro tome su cargo."],[9,"Que sus hijos queden huérfanos,\ny su mujer viuda."],[10,"Que sus hijos anden vagabundos y mendiguen;\nque sean expulsados de sus ruinas."],[11,"Que el usurero se apodere de todo lo que tiene.\nQue los extraños saqueen el fruto de su trabajo."],[12,"Que no haya quien le extienda misericordia,\nni haya quien se apiade de sus hijos huérfanos."],[13,"Que su descendencia sea cortada.\nQue en la generación siguiente sea borrado su nombre."],[14,"Que la iniquidad de sus padres sea recordada ante Yahvé,\ny no dejes que el pecado de su madre sea borrado."],[15,"Que estén continuamente delante de Yahvé,\npara que él corte de la tierra su memoria;"],[16,"porque no se acordó de hacer misericordia,\nsino que persiguió al pobre y al necesitado,\ny al quebrantado de corazón, para darle muerte."],[17,"Amó la maldición, y esta recayó sobre él;\nno se deleitó en la bendición, y ella se alejó de él."],[18,"Se vistió de maldición como si fuera su ropa;\ny entró en sus entrañas como el agua,\ncomo aceite en sus huesos."],[19,"Que le sea como el manto con que se cubre,\ny como el cinto que siempre lo ciñe."],[20,"Esta sea la recompensa de Yahvé para mis adversarios,\npara los que hablan mal contra mi alma."],[21,"Pero tú, Yahvé el Señor, obra en mi favor por amor a tu nombre;\nporque tu misericordia es buena, líbrame;"],[22,"porque soy pobre y necesitado,\ny mi corazón está herido dentro de mí."],[23,"Me desvanezco como la sombra que declina.\nSoy sacudido como la langosta."],[24,"Mis rodillas se han debilitado a causa del ayuno,\ny mi carne ha enflaquecido y perdido su gordura."],[25,"Me he convertido en el oprobio de ellos;\ncuando me ven, sacuden la cabeza."],[26,"Ayúdame, Yahvé, Dios mío.\nSálvame conforme a tu misericordia,"],[27,"para que sepan que esta es tu mano;\nque tú, Yahvé, lo has hecho."],[28,"Ellos podrán maldecir, pero tú bendecirás.\nCuando se levanten, serán avergonzados,\npero tu siervo se alegrará."],[29,"Que mis adversarios sean vestidos de ignominia.\nQue se cubran con su propia vergüenza como con un manto."],[30,"Daré muchas gracias a Yahvé con mi boca.\nSí, lo alabaré en medio de la multitud."],[31,"Porque él se pondrá a la diestra del necesitado,\npara salvarle de los que juzgan su alma."]],"l":[]},{"i":[[0,"Un salmo de David."],[1,"Yahvé dice a mi Señor: «Siéntate a mi diestra,\nhasta que ponga a tus enemigos por estrado de tus pies»."],[2,"Yahvé enviará desde Sión el cetro de tu poder.\n¡Domina en medio de tus enemigos!",[[20,24,0]]],[3,"Tu pueblo se ofrecerá voluntariamente en el día de tu poder, en el esplendor de la santidad.\nDesde el seno de la aurora, tienes el rocío de tu juventud."],[4,"Yahvé ha jurado y no se arrepentirá:\n«Tú eres sacerdote para siempre, según el orden de Melquisedec»."],[5,"El Señor está a tu diestra.\nQuebrantará a los reyes en el día de su ira."],[6,"Él juzgará entre las naciones.\nLas llenará de cadáveres.\nQuebrantará cabezas sobre la extensa tierra."],[7,"Beberá del arroyo en el camino;\npor tanto, levantará la cabeza."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[1,"¡Alabado sea Yah!\nDaré gracias a Yahvé con todo mi corazón,\nen el consejo de los rectos y en la congregación."],[2,"Grandes son las obras de Yahvé,\nbuscadas por todos los que se deleitan en ellas."],[3,"Esplendor y majestad es su obra,\ny su justicia permanece para siempre."],[4,"Ha hecho memorables sus maravillas.\nClemente y compasivo es Yahvé."],[5,"Ha dado alimento a los que le temen.\nSiempre se acuerda de su pacto."],[6,"Ha mostrado a su pueblo el poder de sus obras,\nal darles la heredad de las naciones."],[7,"Las obras de sus manos son verdad y justicia.\nFieles son todos sus preceptos."],[8,"Están afirmados eternamente y para siempre,\ny son ejecutados con verdad y rectitud."],[9,"Ha enviado redención a su pueblo.\nHa ordenado su pacto para siempre.\nSanto y temible es su nombre."],[10,"El temor de Yahvé es el principio de la sabiduría.\nBuen entendimiento tienen todos los que practican sus mandamientos.\nSu alabanza permanece para siempre."]],"l":[]},{"i":[[1,"¡Alabado sea Yah!\nBienaventurado el hombre que teme a Yahvé,\ny que se deleita grandemente en sus mandamientos."],[2,"Su linaje será poderoso en la tierra.\nLa generación de los rectos será bendita."],[3,"En su casa hay riquezas y abundancia,\ny su justicia permanece para siempre."],[4,"La luz resplandece en las tinieblas para los rectos;\nél es clemente, compasivo y justo."],[5,"Bien le va al hombre que se compadece y presta,\nque gobierna sus asuntos con justicia."],[6,"Porque nunca será conmovido.\nEl justo será recordado para siempre."],[7,"No tendrá temor de las malas noticias.\nSu corazón está firme, confiado en Yahvé."],[8,"Su corazón está seguro;\nno temerá, hasta que vea la ruina de sus adversarios."],[9,"Él reparte, da a los pobres.\nSu justicia permanece para siempre.\nSu poder será exaltado con gloria."],[10,"El impío lo verá y se irritará.\nRechinará los dientes y se consumirá.\nEl anhelo de los malvados perecerá."]],"l":[]},{"i":[[1,"¡Alabado sea Yah!\nAlabad, siervos de Yahvé,\nalabad el nombre de Yahvé."],[2,"Bendito sea el nombre de Yahvé,\ndesde ahora y para siempre."],[3,"Desde la salida del sol hasta su ocaso,\nalabado sea el nombre de Yahvé."],[4,"Excelso sobre todas las naciones es Yahvé,\ny su gloria está sobre los cielos."],[5,"¿Quién como Yahvé, nuestro Dios,\nque tiene su morada en las alturas,"],[6,"que se humilla a mirar en el cielo y en la tierra?"],[7,"Él levanta del polvo al pobre,\ny alza al necesitado del muladar,"],[8,"para hacerle sentar con los príncipes,\ncon los príncipes de su pueblo."],[9,"Él hace habitar en familia a la estéril,\ngozosa de ser madre de hijos.\n¡Alabado sea Yah!"]],"l":[]},{"i":[[1,"Cuando Israel salió de Egipto,\nla casa de Jacob de un pueblo de lengua extraña,",[[23,29,0]]],[2,"Judá se convirtió en su santuario,\ne Israel en su señorío."],[3,"El mar lo vio y huyó;\nel Jordán se volvió atrás.",[[25,31,1]]],[4,"Los montes saltaron como carneros,\nlos collados como corderitos."],[5,"¿Qué tuviste, oh mar, que huiste?\nY tú, oh Jordán, ¿por qué te volviste atrás?",[[43,49,1]]],[6,"Oh montes, ¿por qué saltasteis como carneros,\ny vosotros, collados, como corderitos?"],[7,"Tiembla, oh tierra, ante la presencia del Señor,\nante la presencia del Dios de Jacob,"],[8,"el cual convirtió la peña en estanque de agua,\ny el pedernal en manantial de aguas."]],"l":[[353,"Egipto",30.10809,31.33822],[638,"Jordán",32.3091,35.5599]]},{"i":[[1,"No a nosotros, Yahvé, no a nosotros,\nsino a tu nombre da gloria,\npor tu misericordia y por tu verdad."],[2,"¿Por qué han de decir las naciones:\n«¿Dónde está ahora su Dios?»"],[3,"Nuestro Dios está en los cielos;\nél hace todo lo que le place."],[4,"Los ídolos de ellos son de plata y oro,\nobra de manos de hombres."],[5,"Tienen boca, mas no hablan;\ntienen ojos, mas no ven;"],[6,"tienen orejas, mas no oyen;\ntienen nariz, mas no huelen;"],[7,"tienen manos, mas no palpan;\ntienen pies, mas no caminan;\nni emiten sonido alguno con su garganta."],[8,"Semejantes a ellos son los que los hacen,\ny cualquiera que en ellos confía."],[9,"¡Oh Israel, confía en Yahvé!\nÉl es vuestra ayuda y vuestro escudo."],[10,"¡Oh casa de Aarón, confiad en Yahvé!\nÉl es vuestra ayuda y vuestro escudo."],[11,"¡Los que teméis a Yahvé, confiad en Yahvé!\nÉl es vuestra ayuda y vuestro escudo."],[12,"Yahvé se acuerda de nosotros; él nos bendecirá.\nBendecirá a la casa de Israel,\nbendecirá a la casa de Aarón."],[13,"Bendecirá a los que temen a Yahvé,\na los pequeños junto con los grandes."],[14,"Que Yahvé os multiplique más y más,\na vosotros y a vuestros hijos."],[15,"Benditos seáis vosotros de Yahvé,\nque hizo los cielos y la tierra."],[16,"Los cielos son los cielos de Yahvé,\npero la tierra la ha dado a los hijos de los hombres."],[17,"Los muertos no alaban a Yah,\nni ninguno de los que descienden al silencio;"],[18,"pero nosotros bendeciremos a Yah,\ndesde ahora y para siempre.\n¡Alabado sea Yah!"]],"l":[]},{"i":[[1,"Amo a Yahvé, porque escucha mi voz\ny mis súplicas."],[2,"Porque ha inclinado a mí su oído,\npor lo tanto lo invocaré mientras viva."],[3,"Me rodearon las ligaduras de la muerte,\nlos dolores del Seol se apoderaron de mí;\nhallé angustia y dolor."],[4,"Entonces invoqué el nombre de Yahvé:\n«Oh Yahvé, te ruego que libres mi alma»."],[5,"Clemente es Yahvé y justo;\nsí, nuestro Dios es misericordioso."],[6,"Yahvé guarda a los sencillos;\nestaba yo postrado, y él me salvó."],[7,"Vuelve, oh alma mía, a tu reposo,\nporque Yahvé te ha colmado de bienes."],[8,"Porque tú has librado mi alma de la muerte,\nmis ojos de las lágrimas,\ny mis pies de resbalar."],[9,"Andaré delante de Yahvé en la tierra de los vivientes."],[10,"Creí, por tanto hablé,\naunque estaba muy afligido."],[11,"Dije en mi apresuramiento:\n«Todo hombre es mentiroso»."],[12,"¿Qué pagaré a Yahvé por todos sus beneficios para conmigo?"],[13,"Alzaré la copa de la salvación e invocaré el nombre de Yahvé."],[14,"Pagaré mis votos a Yahvé,\nsí, en presencia de todo su pueblo."],[15,"Estimada es a los ojos de Yahvé la muerte de sus santos."],[16,"Oh Yahvé, ciertamente soy tu siervo.\nSoy tu siervo, hijo de tu sierva;\ntú has roto mis prisiones."],[17,"Te ofreceré sacrificio de alabanza,\ne invocaré el nombre de Yahvé."],[18,"Pagaré mis votos a Yahvé,\nsí, en presencia de todo su pueblo,"],[19,"en los atrios de la casa de Yahvé,\nen medio de ti, oh Jerusalén.\n¡Alabado sea Yah!",[[54,63,0]]]],"l":[[622,"Jerusalén",31.77744,35.23494]]},{"i":[[1,"¡Alabad a Yahvé, todas las naciones!\n¡Exaltadle, todos los pueblos!"],[2,"Porque su misericordia es grande para con nosotros.\nLa fidelidad de Yahvé es eterna.\n¡Alabado sea Yah!"]],"l":[]},{"i":[[1,"Dad gracias a Yahvé, porque él es bueno,\nporque su misericordia es eterna."],[2,"Diga ahora Israel\nque su misericordia es eterna."],[3,"Diga ahora la casa de Aarón\nque su misericordia es eterna."],[4,"Digan ahora los que temen a Yahvé\nque su misericordia es eterna."],[5,"Desde la angustia invoqué a Yah;\ny me respondió Yah, poniéndome en lugar espacioso."],[6,"Yahvé está conmigo; no temeré.\n¿Qué puede hacerme el hombre?"],[7,"Yahvé está conmigo entre los que me ayudan;\npor tanto, miraré triunfante a los que me aborrecen."],[8,"Mejor es refugiarse en Yahvé\nque confiar en el hombre."],[9,"Mejor es refugiarse en Yahvé\nque confiar en los príncipes."],[10,"Todas las naciones me rodearon,\npero en el nombre de Yahvé yo las destruí."],[11,"Me rodearon, sí, me rodearon,\npero en el nombre de Yahvé las destruí."],[12,"Me rodearon como abejas;\nfueron apagadas como fuego de espinos.\nEn el nombre de Yahvé las destruí."],[13,"Me empujaste con violencia para hacerme caer,\npero Yahvé me ayudó."],[14,"Yah es mi fortaleza y mi cántico,\ny se ha convertido en mi salvación."],[15,"Voz de júbilo y de salvación hay en las tiendas de los justos:\n«¡La diestra de Yahvé hace proezas!"],[16,"¡La diestra de Yahvé es exaltada!\n¡La diestra de Yahvé hace proezas!»."],[17,"No moriré, sino que viviré,\ny contaré las obras de Yah."],[18,"Yah me ha castigado duramente,\npero no me ha entregado a la muerte."],[19,"Abridme las puertas de la justicia;\nentraré por ellas,\ny daré gracias a Yah."],[20,"Esta es la puerta de Yahvé;\npor ella entrarán los justos."],[21,"Te daré gracias, porque me has respondido,\ny te has convertido en mi salvación."],[22,"La piedra que desecharon los edificadores\nse ha convertido en la piedra angular."],[23,"Obra de Yahvé es esta;\nes una maravilla a nuestros ojos."],[24,"Este es el día que Yahvé ha hecho;\nnos gozaremos y alegraremos en él."],[25,"¡Sálvanos ahora, te lo rogamos, oh Yahvé!\n¡Oh Yahvé, te rogamos que nos des prosperidad ahora!"],[26,"¡Bendito el que viene en el nombre de Yahvé!\nDesde la casa de Yahvé os bendecimos."],[27,"Yahvé es Dios, y nos ha dado luz.\nAtad la víctima festiva con cuerdas, a los cuernos del altar."],[28,"Tú eres mi Dios, y te daré gracias;\ntú eres mi Dios, y te exaltaré."],[29,"Dad gracias a Yahvé, porque él es bueno,\nporque su misericordia es eterna."]],"l":[]},{"i":[[0,"ALEF"],[1,"Bienaventurados los de perfecto camino,\nlos que andan en la ley de Yahvé."],[2,"Bienaventurados los que guardan sus testimonios,\ny con todo el corazón le buscan;"],[3,"pues no cometen iniquidad,\nsino que andan en sus caminos."],[4,"Tú has ordenado tus mandamientos,\npara que sean guardados con diligencia."],[5,"¡Ojalá fuesen ordenados mis caminos\npara guardar tus estatutos!"],[6,"Entonces no sería yo avergonzado,\ncuando considerase todos tus mandamientos."],[7,"Te alabaré con rectitud de corazón,\ncuando aprenda tus justos juicios."],[8,"Tus estatutos guardaré;\nno me abandones del todo."],[0,"BET"],[9,"¿Con qué limpiará el joven su camino?\nCon guardar tu palabra."],[10,"Con todo mi corazón te he buscado;\nno me dejes desviarme de tus mandamientos."],[11,"En mi corazón he guardado tus dichos,\npara no pecar contra ti."],[12,"Bendito tú, oh Yahvé;\nenséñame tus estatutos."],[13,"Con mis labios\nhe declarado todos los juicios de tu boca."],[14,"Me he gozado en el camino de tus testimonios,\nmás que en todas las riquezas."],[15,"En tus mandamientos meditaré;\nconsideraré tus caminos."],[16,"Me regocijaré en tus estatutos;\nno me olvidaré de tus palabras."],[0,"GUÍMEL"],[17,"Haz bien a tu siervo;\nque viva y guarde tu palabra."],[18,"Abre mis ojos,\ny miraré las maravillas de tu ley."],[19,"Forastero soy yo en la tierra;\nno encubras de mí tus mandamientos."],[20,"Quebrantada está mi alma de desear tus juicios en todo tiempo."],[21,"Reprendiste a los soberbios, los malditos,\nque se desvían de tus mandamientos."],[22,"Aparta de mí el oprobio y el menosprecio,\nporque tus testimonios he guardado."],[23,"Aunque príncipes se sienten y hablen contra mí,\ntu siervo meditará en tus estatutos."],[24,"Pues tus testimonios son mis delicias,\ny mis consejeros."],[0,"DÁLET"],[25,"Abatida hasta el polvo está mi alma;\n¡vivifícame según tu palabra!"],[26,"Te he manifestado mis caminos, y me has respondido;\nenséñame tus estatutos."],[27,"Hazme entender el camino de tus mandamientos,\npara que medite en tus maravillas."],[28,"Se deshace mi alma de ansiedad;\nsusténtame según tu palabra."],[29,"Aparta de mí el camino de la mentira,\ny en tu misericordia concédeme tu ley."],[30,"Escogí el camino de la verdad;\nhe puesto tus juicios delante de mí."],[31,"Me he apegado a tus testimonios;\noh Yahvé, no me avergüences."],[32,"Por el camino de tus mandamientos correré,\ncuando ensanches mi corazón."],[0,"HE"],[33,"Enséñame, oh Yahvé, el camino de tus estatutos,\ny lo guardaré hasta el fin."],[34,"Dame entendimiento, y guardaré tu ley;\ny la cumpliré de todo corazón."],[35,"Guíame por la senda de tus mandamientos,\nporque en ella me deleito."],[36,"Inclina mi corazón a tus testimonios,\ny no a la avaricia."],[37,"Aparta mis ojos de mirar la vanidad;\nvivifícame en tu camino."],[38,"Confirma tu palabra a tu siervo,\nque está dedicada a tu temor."],[39,"Quita de mí el oprobio que temo,\nporque buenos son tus juicios."],[40,"He aquí yo he anhelado tus mandamientos;\nvivifícame en tu justicia."],[0,"VAV"],[41,"Venga a mí tu misericordia, oh Yahvé;\ntu salvación, conforme a tu dicho."],[42,"Y daré por respuesta a mi avergonzador\nque en tu palabra he confiado."],[43,"No quites de mi boca en ningún tiempo la palabra de verdad,\nporque en tus juicios espero."],[44,"Guardaré tu ley siempre,\npara siempre y eternamente."],[45,"Y andaré en libertad,\nporque busqué tus mandamientos."],[46,"Hablaré de tus testimonios delante de los reyes,\ny no me avergonzaré."],[47,"Y me regocijaré en tus mandamientos,\nlos cuales he amado."],[48,"Alzaré asimismo mis manos a tus mandamientos que amé,\ny meditaré en tus estatutos."],[0,"ZAIN"],[49,"Acuérdate de la palabra dada a tu siervo,\nen la cual me has hecho esperar."],[50,"Este es mi consuelo en mi aflicción:\nque tu dicho me ha vivificado."],[51,"Los soberbios se burlaron mucho de mí,\nmas no me he apartado de tu ley."],[52,"Me acordé, oh Yahvé, de tus juicios antiguos,\ny me consolé."],[53,"Horror se apoderó de mí,\na causa de los impíos que dejan tu ley."],[54,"Cánticos fueron para mí tus estatutos\nen la casa de mi peregrinación."],[55,"Me acordé en la noche de tu nombre, oh Yahvé,\ny guardé tu ley."],[56,"Estas bendiciones tuve\nporque guardé tus mandamientos."],[0,"HET"],[57,"Mi porción es Yahvé;\nhe dicho que guardaré tus palabras."],[58,"Tu presencia supliqué de todo corazón;\nten misericordia de mí según tu palabra."],[59,"Consideré mis caminos,\ny volví mis pasos a tus testimonios."],[60,"Me apresuré y no me retardé\nen guardar tus mandamientos."],[61,"Lazos de impíos me han rodeado,\nmas no me he olvidado de tu ley."],[62,"A medianoche me levanto para alabarte\npor tus justos juicios."],[63,"Compañero soy yo de todos los que te temen\ny guardan tus mandamientos."],[64,"De tu misericordia, oh Yahvé, está llena la tierra;\nenséñame tus estatutos."],[0,"TET"],[65,"Bien has hecho con tu siervo,\noh Yahvé, conforme a tu palabra."],[66,"Enséñame buen sentido y sabiduría,\nporque tus mandamientos he creído."],[67,"Antes que fuera yo humillado, desvarié;\nmas ahora guardo tu palabra."],[68,"Bueno eres tú, y bienhechor;\nenséñame tus estatutos."],[69,"Los soberbios han forjado mentira contra mí,\nmas yo guardaré de todo corazón tus mandamientos."],[70,"Se engrosó el corazón de ellos como sebo,\nmas yo en tu ley me he regocijado."],[71,"Bueno me es haber sido humillado,\npara que aprenda tus estatutos."],[72,"Mejor me es la ley de tu boca que millares de oro y plata."],[0,"YOD"],[73,"Tus manos me hicieron y me formaron;\nhazme entender, y aprenderé tus mandamientos."],[74,"Los que te temen me verán, y se alegrarán,\nporque en tu palabra he esperado."],[75,"Conozco, oh Yahvé, que tus juicios son justos,\ny que conforme a tu fidelidad me afligiste."],[76,"Sea ahora tu misericordia para consolarme,\nconforme a lo que has dicho a tu siervo."],[77,"Vengan a mí tus misericordias, para que viva,\nporque tu ley es mi delicia."],[78,"Sean avergonzados los soberbios, porque sin causa me han calumniado;\npero yo meditaré en tus mandamientos."],[79,"Vuélvanse a mí los que te temen\ny conocen tus testimonios."],[80,"Sea mi corazón íntegro en tus estatutos,\npara que no sea yo avergonzado."],[0,"CAF"],[81,"Desfallece mi alma por tu salvación,\nmas espero en tu palabra."],[82,"Desfallecieron mis ojos por tu palabra,\ndiciendo: «¿Cuándo me consolarás?»"],[83,"Porque estoy como el odre al humo,\npero no he olvidado tus estatutos."],[84,"¿Cuántos son los días de tu siervo?\n¿Cuándo harás juicio contra los que me persiguen?"],[85,"Los soberbios me han cavado hoyos,\nlo cual no es conforme a tu ley."],[86,"Todos tus mandamientos son verdad;\nsin causa me persiguen;\n¡ayúdame!"],[87,"Casi me han echado por tierra,\nmas yo no he dejado tus mandamientos."],[88,"Vivifícame conforme a tu misericordia,\ny guardaré los testimonios de tu boca."],[0,"LÁMED"],[89,"Para siempre, oh Yahvé,\npermanece tu palabra en los cielos."],[90,"De generación en generación es tu fidelidad;\ntú afirmaste la tierra, y subsiste."],[91,"Por tu ordenación subsisten todas las cosas hasta hoy,\npues todas ellas te sirven."],[92,"Si tu ley no hubiese sido mi delicia,\nya en mi aflicción hubiera perecido."],[93,"Nunca jamás me olvidaré de tus mandamientos,\nporque con ellos me has vivificado."],[94,"Tuyo soy yo, sálvame,\nporque he buscado tus mandamientos."],[95,"Los impíos me han aguardado para destruirme,\nmas yo consideraré tus testimonios."],[96,"A toda perfección he visto fin;\namplio sobremanera es tu mandamiento."],[0,"MEM"],[97,"¡Oh, cuánto amo yo tu ley!\nTodo el día es ella mi meditación."],[98,"Me has hecho más sabio que mis enemigos con tus mandamientos,\nporque siempre están conmigo."],[99,"Más que todos mis enseñadores he entendido,\nporque tus testimonios son mi meditación."],[100,"Más que los ancianos he entendido,\nporque he guardado tus mandamientos."],[101,"De todo mal camino contuve mis pies,\npara guardar tu palabra."],[102,"No me aparté de tus juicios,\nporque tú me enseñaste."],[103,"¡Cuán dulces son a mi paladar tus palabras!\n¡Más que la miel a mi boca!"],[104,"De tus mandamientos he adquirido inteligencia;\npor tanto, he aborrecido todo camino de mentira."],[0,"NUN"],[105,"Lámpara es a mis pies tu palabra,\ny lumbrera a mi camino."],[106,"Juré y ratifiqué\nque guardaré tus justos juicios."],[107,"Afligido estoy en gran manera;\nvivifícame, oh Yahvé, conforme a tu palabra."],[108,"Te ruego, oh Yahvé, que aceptes las ofrendas voluntarias de mi boca,\ny me enseñes tus juicios."],[109,"Mi vida está de continuo en peligro,\nmas no me he olvidado de tu ley."],[110,"Me pusieron lazo los impíos,\npero yo no me desvié de tus mandamientos."],[111,"Por heredad he tomado tus testimonios para siempre,\nporque son el gozo de mi corazón."],[112,"Mi corazón incliné a cumplir tus estatutos\nde continuo, hasta el fin."],[0,"SÁMEC"],[113,"Aborrezco a los hombres de doble ánimo,\nmas amo tu ley."],[114,"Mi escondedero y mi escudo eres tú;\nen tu palabra he esperado."],[115,"Apartaos de mí, malignos,\npues yo guardaré los mandamientos de mi Dios."],[116,"Susténtame conforme a tu palabra, y viviré;\ny no quedes yo avergonzado de mi esperanza."],[117,"Sosténme, y seré salvo,\ny me regocijaré siempre en tus estatutos."],[118,"Hollaste a todos los que se desvían de tus estatutos,\nporque su falsedad es engaño."],[119,"Como a escoria hiciste consumir a todos los impíos de la tierra;\npor tanto, yo he amado tus testimonios."],[120,"Mi carne se ha estremecido por temor a ti,\ny de tus juicios tengo miedo."],[0,"AYIN"],[121,"Juicio y justicia he hecho;\nno me abandones a mis opresores."],[122,"Afianza a tu siervo para bien;\nno dejes que los soberbios me opriman."],[123,"Mis ojos desfallecen por tu salvación,\ny por la palabra de tu justicia."],[124,"Haz con tu siervo según tu misericordia,\ny enséñame tus estatutos."],[125,"Tu siervo soy yo, dame entendimiento\npara conocer tus testimonios."],[126,"Tiempo es de actuar, oh Yahvé,\nporque han invalidado tu ley."],[127,"Por eso he amado tus mandamientos\nmás que el oro, y más que oro muy puro."],[128,"Por eso estimé rectos todos tus mandamientos sobre todas las cosas,\ny aborrecí todo camino de mentira."],[0,"PE"],[129,"Maravillosos son tus testimonios;\npor tanto, los ha guardado mi alma."],[130,"La exposición de tus palabras alumbra;\nhace entender a los simples."],[131,"Mi boca abrí y suspiré,\nporque deseaba tus mandamientos."],[132,"Mírame, y ten misericordia de mí,\ncomo acostumbras con los que aman tu nombre."],[133,"Ordena mis pasos con tu palabra,\ny ninguna iniquidad se enseñoree de mí."],[134,"Líbrame de la violencia de los hombres,\ny guardaré tus mandamientos."],[135,"Haz resplandecer tu rostro sobre tu siervo,\ny enséñame tus estatutos."],[136,"Ríos de agua descendieron de mis ojos,\nporque no guardaban tu ley."],[0,"TSADE"],[137,"Justo eres tú, oh Yahvé,\ny rectos tus juicios."],[138,"Tus testimonios, que has recomendado,\nson rectos y muy fieles."],[139,"Mi celo me ha consumido,\nporque mis enemigos se olvidaron de tus palabras."],[140,"Sumamente pura es tu palabra,\ny la ama tu siervo."],[141,"Pequeño soy yo, y desechado,\nmas no me he olvidado de tus mandamientos."],[142,"Tu justicia es justicia eterna,\ny tu ley la verdad."],[143,"Aflicción y angustia se han apoderado de mí,\nmas tus mandamientos fueron mi delicia."],[144,"Justicia eterna son tus testimonios;\ndame entendimiento, y viviré."],[0,"COF"],[145,"Clamé con todo mi corazón; ¡respóndeme, oh Yahvé!\nY guardaré tus estatutos."],[146,"A ti clamé; ¡sálvame!\nY guardaré tus testimonios."],[147,"Me anticipé al alba, y clamé;\nesperé en tu palabra."],[148,"Se anticiparon mis ojos a las vigilias de la noche,\npara meditar en tus mandatos."],[149,"Oye mi voz conforme a tu misericordia;\noh Yahvé, vivifícame conforme a tu juicio."],[150,"Se acercaron a la maldad los que me persiguen;\nse alejaron de tu ley."],[151,"Cercano estás tú, oh Yahvé,\ny todos tus mandamientos son verdad."],[152,"Hace ya mucho que he entendido tus testimonios,\nque para siempre los has establecido."],[0,"RESH"],[153,"Mira mi aflicción, y líbrame,\nporque de tu ley no me he olvidado."],[154,"Defiende mi causa, y redímeme;\nvivifícame con tu palabra."],[155,"Lejos está de los impíos la salvación,\nporque no buscan tus estatutos."],[156,"Muchas son tus misericordias, oh Yahvé;\nvivifícame conforme a tus juicios."],[157,"Muchos son mis perseguidores y mis enemigos,\nmas de tus testimonios no me he apartado."],[158,"Veía a los prevaricadores, y me disgustaba,\nporque no guardaban tus palabras."],[159,"Mira, oh Yahvé, que amo tus mandamientos;\nvivifícame conforme a tu misericordia."],[160,"La suma de tu palabra es verdad,\ny eterno es todo juicio de tu justicia."],[0,"SIN Y SHIN"],[161,"Príncipes me han perseguido sin causa,\npero mi corazón tuvo temor de tus palabras."],[162,"Me regocijo en tu palabra\ncomo el que halla muchos despojos."],[163,"La mentira aborrezco y abomino;\ntu ley amo."],[164,"Siete veces al día te alabo\na causa de tus justos juicios."],[165,"Mucha paz tienen los que aman tu ley,\ny no hay para ellos tropiezo."],[166,"Tu salvación he esperado, oh Yahvé,\ny tus mandamientos he puesto por obra."],[167,"Mi alma ha guardado tus testimonios,\ny los he amado en gran manera."],[168,"He guardado tus mandamientos y tus testimonios,\nporque todos mis caminos están delante de ti."],[0,"TAV"],[169,"Llegue mi clamor delante de ti, oh Yahvé;\ndame entendimiento conforme a tu palabra."],[170,"Llegue mi súplica delante de ti;\nlíbrame conforme a tu dicho."],[171,"Mis labios rebosarán alabanza\ncuando me enseñes tus estatutos."],[172,"Hablará mi lengua tus dichos,\nporque todos tus mandamientos son justicia."],[173,"Esté tu mano pronta para socorrerme,\nporque tus mandamientos he escogido."],[174,"He deseado tu salvación, oh Yahvé,\ny tu ley es mi delicia."],[175,"Viva mi alma y te alabe,\ny tus juicios me ayuden."],[176,"Yo anduve errante como oveja extraviada;\nbusca a tu siervo, porque no me he olvidado de tus mandamientos."]],"l":[]},{"i":[[0,"Cántico gradual."],[1,"En mi angustia clamé a Yahvé,\ny él me respondió."],[2,"Libra mi alma, oh Yahvé, de los labios mentirosos,\ny de la lengua engañosa."],[3,"¿Qué te dará, o qué te añadirá,\noh lengua engañosa?"],[4,"¡Agudas saetas de valiente,\ncon brasas de retama!"],[5,"¡Ay de mí, que peregrino en Mesec,\ny habito entre las tiendas de Cedar!",[[65,70,0]]],[6,"Mucho tiempo ha morado mi alma\ncon los que aborrecen la paz."],[7,"Yo soy pacífico,\nmas cuando hablo, ellos son para la guerra."]],"l":[[659,"Cedar",27.4,37.7]]},{"i":[[0,"Cántico gradual."],[1,"Alzaré mis ojos a los montes.\n¿De dónde vendrá mi socorro?"],[2,"Mi socorro viene de Yahvé,\nque hizo los cielos y la tierra."],[3,"No dará tu pie al resbaladero,\nni se adormecerá el que te guarda."],[4,"He aquí, no se adormecerá ni dormirá\nel que guarda a Israel."],[5,"Yahvé es tu guardador;\nYahvé es tu sombra a tu diestra."],[6,"El sol no te fatigará de día,\nni la luna de noche."],[7,"Yahvé te guardará de todo mal;\nél guardará tu alma."],[8,"Yahvé guardará tu salida y tu entrada,\ndesde ahora y para siempre."]],"l":[]},{"i":[[0,"Cántico gradual. De David."],[1,"Yo me alegré con los que me decían:\n«A la casa de Yahvé iremos»."],[2,"Nuestros pies se detuvieron dentro de tus puertas, oh Jerusalén.",[[54,63,0]]],[3,"Jerusalén, que se ha edificado como una ciudad bien unida entre sí,",[[0,9,0]]],[4,"adonde suben las tribus, las tribus de Yah,\nconforme al testimonio dado a Israel,\npara dar gracias al nombre de Yahvé."],[5,"Porque allí están los tronos para el juicio,\nlos tronos de la casa de David."],[6,"Pedid por la paz de Jerusalén;\nsean prosperados los que te aman.",[[20,29,0]]],[7,"Haya paz dentro de tus muros,\ny prosperidad en tus palacios."],[8,"Por amor a mis hermanos y a mis compañeros,\ndiré ahora: «La paz sea contigo»."],[9,"Por amor a la casa de Yahvé nuestro Dios,\nbuscaré tu bien."]],"l":[[622,"Jerusalén",31.77744,35.23494]]},{"i":[[0,"Cántico gradual."],[1,"A ti alzo mis ojos,\na ti que habitas en los cielos."],[2,"He aquí, como los ojos de los siervos miran a la mano de sus señores,\ny como los ojos de la sierva a la mano de su señora,\nasí nuestros ojos miran a Yahvé, nuestro Dios,\nhasta que tenga misericordia de nosotros."],[3,"Ten misericordia de nosotros, oh Yahvé, ten misericordia de nosotros,\nporque estamos muy hastiados de menosprecio."],[4,"Hastiada está nuestra alma de la burla de los que viven holgadamente,\ny del menosprecio de los soberbios."]],"l":[]},{"i":[[0,"Cántico gradual. De David."],[1,"Si no hubiese estado Yahvé por nosotros,\ndiga ahora Israel;"],[2,"si no hubiese estado Yahvé por nosotros,\ncuando los hombres se levantaron contra nosotros,"],[3,"vivos nos habrían tragado entonces,\ncuando su furor se encendió contra nosotros;"],[4,"entonces las aguas nos habrían inundado,\nel torrente habría pasado sobre nuestra alma."],[5,"Entonces habrían pasado sobre nuestra alma\nlas aguas impetuosas."],[6,"Bendito sea Yahvé,\nque no nos dio por presa a sus dientes."],[7,"Nuestra alma escapó como un ave del lazo de los cazadores;\nse rompió el lazo, y nosotros escapamos."],[8,"Nuestro socorro está en el nombre de Yahvé,\nque hizo los cielos y la tierra."]],"l":[]},{"i":[[0,"Cántico gradual."],[1,"Los que confían en Yahvé son como el monte Sión,\nque no se conmueve, sino que permanece para siempre.",[[37,47,0]]],[2,"Como Jerusalén tiene montes a su alrededor,\nasí Yahvé está alrededor de su pueblo, desde ahora y para siempre.",[[5,14,1]]],[3,"Porque el cetro de la impiedad no reposará sobre la heredad de los justos,\nno sea que los justos extiendan sus manos a la iniquidad."],[4,"Haz bien, oh Yahvé, a los buenos,\ny a los que son rectos de corazón."],[5,"Mas a los que se desvían por sus caminos torcidos,\nYahvé los llevará con los que obran iniquidad.\n¡La paz sea sobre Israel!"]],"l":[[844,"Monte Sión",31.77744,35.23494],[622,"Jerusalén",31.77744,35.23494]]},{"i":[[0,"Cántico gradual."],[1,"Cuando Yahvé hizo volver a los cautivos de Sión,\néramos como los que sueñan.",[[43,47,0]]],[2,"Entonces nuestra boca se llenó de risa,\ny nuestra lengua de alabanza.\nEntonces decían entre las naciones:\n«Grandes cosas ha hecho Yahvé con estos»."],[3,"Grandes cosas ha hecho Yahvé con nosotros;\nestaremos alegres."],[4,"Haz volver a nuestros cautivos, oh Yahvé,\ncomo los arroyos del Néguev."],[5,"Los que sembraron con lágrimas, con regocijo segarán."],[6,"Irá andando y llorando el que lleva la semilla para sembrar,\nmas ciertamente volverá con regocijo, trayendo sus gavillas."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Cántico gradual. De Salomón."],[1,"Si Yahvé no edifica la casa,\nen vano trabajan los que la edifican.\nSi Yahvé no guarda la ciudad,\nen vano vela la guardia."],[2,"Por demás es que os levantéis de madrugada,\ny vayáis tarde a reposar,\ny que comáis pan de dolores,\npues a su amado dará Dios el sueño."],[3,"He aquí, herencia de Yahvé son los hijos;\ncosa de estima el fruto del vientre."],[4,"Como saetas en mano del valiente,\nasí son los hijos habidos en la juventud."],[5,"Bienaventurado el hombre que llenó su aljaba de ellos;\nno será avergonzado cuando hable con los enemigos en la puerta."]],"l":[]},{"i":[[0,"Cántico gradual."],[1,"Bienaventurado todo aquel que teme a Yahvé,\nque anda en sus caminos."],[2,"Cuando comas del trabajo de tus manos,\nbienaventurado serás, y te irá bien."],[3,"Tu mujer será como vid que lleva fruto a los lados de tu casa;\ntus hijos como plantas de olivo alrededor de tu mesa."],[4,"He aquí que así será bendecido el hombre\nque teme a Yahvé."],[5,"Bendígate Yahvé desde Sión,\ny veas el bien de Jerusalén todos los días de tu vida.",[[22,26,0],[46,55,1]]],[6,"Y veas a los hijos de tus hijos.\n¡Paz sea sobre Israel!"]],"l":[[1239,"Sión",31.77744,35.23494],[622,"Jerusalén",31.77744,35.23494]]},{"i":[[0,"Cántico gradual."],[1,"Mucho me han angustiado desde mi juventud,\ndiga ahora Israel;"],[2,"mucho me han angustiado desde mi juventud,\nmas no prevalecieron contra mí."],[3,"Sobre mis espaldas araron los aradores;\nhicieron largos sus surcos."],[4,"Yahvé es justo;\nha cortado las ataduras de los impíos."],[5,"Sean avergonzados y vueltos atrás\ntodos los que aborrecen a Sión.",[[60,64,0]]],[6,"Sean como la hierba de los tejados,\nque se seca antes de crecer;"],[7,"de la cual no llena el segador su mano,\nni su regazo el que ata las gavillas."],[8,"Ni dicen los que pasan:\n«La bendición de Yahvé sea sobre vosotros;\nos bendecimos en el nombre de Yahvé»."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Cántico gradual."],[1,"De lo profundo, oh Yahvé, a ti clamo."],[2,"Señor, escucha mi voz;\nestén atentos tus oídos a la voz de mis súplicas."],[3,"Si tú, oh Yah, miraras las iniquidades,\n¿quién, oh Señor, podría mantenerse en pie?"],[4,"Pero en ti hay perdón,\npara que seas temido."],[5,"Esperé yo a Yahvé,\nesperó mi alma;\nen su palabra he esperado."],[6,"Mi alma espera al Señor más que los centinelas a la mañana,\nmás que los centinelas a la mañana."],[7,"Espere Israel a Yahvé,\nporque en Yahvé hay misericordia,\ny abundante redención con él."],[8,"Y él redimirá a Israel de todos sus pecados."]],"l":[]},{"i":[[0,"Cántico gradual. De David."],[1,"Yahvé, mi corazón no se ha enaltecido, ni mis ojos son altivos;\nni ando tras grandezas,\nni en cosas demasiado sublimes para mí."],[2,"En verdad he acallado y calmado mi alma;\ncomo un niño destetado en el regazo de su madre,\ncomo un niño destetado está mi alma dentro de mí."],[3,"Espera, oh Israel, en Yahvé,\ndesde ahora y para siempre."]],"l":[]},{"i":[[0,"Cántico gradual."],[1,"Acuérdate, oh Yahvé, de David,\ny de toda su aflicción;"],[2,"de cómo juró a Yahvé,\ne hizo voto al Fuerte de Jacob:"],[3,"«Ciertamente no entraré en la morada de mi casa,\nni subiré a mi lecho;"],[4,"no daré sueño a mis ojos,\nni adormecimiento a mis párpados,"],[5,"hasta que halle un lugar para Yahvé,\nuna morada para el Fuerte de Jacob»."],[6,"He aquí, oímos de ella en Efrata;\nla hallamos en los campos del bosque."],[7,"«Entraremos en su morada;\nnos postraremos ante el estrado de sus pies»."],[8,"Levántate, oh Yahvé, al lugar de tu reposo,\ntú y el arca de tu poder."],[9,"Vístanse de justicia tus sacerdotes,\ny canten de júbilo tus santos."],[10,"Por amor a tu siervo David,\nno hagas volver el rostro de tu ungido."],[11,"En verdad juró Yahvé a David,\ny no se apartará de ello:\n«Del fruto de tu vientre pondré sobre tu trono."],[12,"Si tus hijos guardan mi pacto\ny mi testimonio que yo les enseñaré,\nsus hijos también se sentarán sobre tu trono para siempre»."],[13,"Porque Yahvé ha elegido a Sión;\nla quiso por habitación para sí.",[[26,30,0]]],[14,"«Este es para siempre el lugar de mi reposo;\naquí habitaré, porque la he deseado."],[15,"Bendeciré abundantemente su provisión;\na sus pobres saciaré de pan."],[16,"Vestiré a sus sacerdotes de salvación,\ny sus santos darán voces de júbilo."],[17,"Allí haré retoñar el cuerno de David;\nhe dispuesto una lámpara para mi ungido."],[18,"A sus enemigos vestiré de confusión,\nmas sobre él florecerá su corona»."]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Cántico gradual. De David."],[1,"¡Mirad cuán bueno y cuán delicioso es\nhabitar los hermanos juntos en armonía!"],[2,"Es como el buen óleo sobre la cabeza,\nel cual desciende sobre la barba,\nla barba de Aarón,\ny baja hasta el borde de sus vestiduras;"],[3,"como el rocío de Hermón,\nque desciende sobre los montes de Sión;\nporque allí envía Yahvé bendición,\ny vida eterna.",[[17,23,0],[59,63,1]]]],"l":[[551,"Hermón",33.41616,35.85726],[1239,"Sión",31.77744,35.23494]]},{"i":[[0,"Cántico gradual."],[1,"¡Mirad! Bendecid a Yahvé, vosotros todos los siervos de Yahvé,\nlos que de noche estáis en la casa de Yahvé."],[2,"Alzad vuestras manos al santuario,\ny bendecid a Yahvé."],[3,"Desde Sión te bendiga Yahvé,\nel cual hizo los cielos y la tierra.",[[6,10,0]]]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[1,"¡Alabado sea Yah!\nAlabad el nombre de Yahvé;\nalabadle, siervos de Yahvé,"],[2,"los que estáis en la casa de Yahvé,\nen los atrios de la casa de nuestro Dios."],[3,"Alabad a Yah, porque Yahvé es bueno;\ncantad alabanzas a su nombre, porque es agradable."],[4,"Porque Yah ha escogido a Jacob para sí,\na Israel como su tesoro especial."],[5,"Porque yo sé que Yahvé es grande,\ny que nuestro Señor está por encima de todos los dioses."],[6,"Todo lo que Yahvé quiere, lo hace,\nen los cielos y en la tierra, en los mares y en todos los abismos."],[7,"Él hace subir las nubes desde los extremos de la tierra;\nhace los relámpagos para la lluvia;\nsaca de sus depósitos los vientos."],[8,"Él hirió a los primogénitos de Egipto,\ndesde el hombre hasta la bestia.",[[31,37,0]]],[9,"Envió señales y prodigios en medio de ti, oh Egipto,\nsobre Faraón y sobre todos sus siervos.",[[45,51,0]]],[10,"Destruyó a muchas naciones,\ny mató a reyes poderosos:"],[11,"a Sehón, rey de los amorreos,\na Og, rey de Basán,\ny a todos los reinos de Canaán;",[[43,48,1],[74,80,2]]],[12,"y dio la tierra de ellos en heredad,\nen heredad a Israel, su pueblo."],[13,"Tu nombre, oh Yahvé, es eterno;\ntu memoria, oh Yahvé, por todas las generaciones."],[14,"Porque Yahvé juzgará a su pueblo,\ny se compadecerá de sus siervos."],[15,"Los ídolos de las naciones son de plata y oro,\nobra de manos de hombres."],[16,"Tienen boca, mas no hablan;\ntienen ojos, mas no ven;"],[17,"tienen orejas, mas no oyen,\nni hay aliento en sus bocas."],[18,"Semejantes a ellos son los que los hacen,\ny cualquiera que en ellos confía."],[19,"Casa de Israel, ¡bendecid a Yahvé!\nCasa de Aarón, ¡bendecid a Yahvé!"],[20,"Casa de Leví, ¡bendecid a Yahvé!\nLos que teméis a Yahvé, bendecid a Yahvé."],[21,"Bendito sea de Sión Yahvé,\nque mora en Jerusalén.\n¡Alabado sea Yah!",[[15,19,3],[39,48,4]]]],"l":[[353,"Egipto",30.10809,31.33822],[154,"Basán",32.80007,35.9373],[265,"Canaán",31.69353,34.84388],[1239,"Sión",31.77744,35.23494],[622,"Jerusalén",31.77744,35.23494]]},{"i":[[1,"Dad gracias a Yahvé, porque él es bueno,\nporque para siempre es su misericordia."],[2,"Dad gracias al Dios de los dioses,\nporque para siempre es su misericordia."],[3,"Dad gracias al Señor de los señores,\nporque para siempre es su misericordia."],[4,"Al único que hace grandes maravillas,\nporque para siempre es su misericordia."],[5,"Al que hizo los cielos con entendimiento,\nporque para siempre es su misericordia."],[6,"Al que extendió la tierra sobre las aguas,\nporque para siempre es su misericordia."],[7,"Al que hizo las grandes lumbreras,\nporque para siempre es su misericordia."],[8,"El sol para que señoree en el día,\nporque para siempre es su misericordia."],[9,"La luna y las estrellas para que señoreen en la noche,\nporque para siempre es su misericordia."],[10,"Al que hirió a Egipto en sus primogénitos,\nporque para siempre es su misericordia.",[[15,21,0]]],[11,"Y sacó a Israel de en medio de ellos,\nporque para siempre es su misericordia."],[12,"Con mano fuerte y brazo extendido,\nporque para siempre es su misericordia."],[13,"Al que dividió el Mar Rojo en dos,\nporque para siempre es su misericordia.",[[18,26,1]]],[14,"E hizo pasar a Israel por en medio de él,\nporque para siempre es su misericordia."],[15,"Y arrojó a Faraón y a su ejército en el Mar Rojo,\nporque para siempre es su misericordia.",[[40,48,1]]],[16,"Al que guio a su pueblo por el desierto,\nporque para siempre es su misericordia."],[17,"Al que hirió a grandes reyes,\nporque para siempre es su misericordia."],[18,"Y mató a reyes poderosos,\nporque para siempre es su misericordia."],[19,"A Sehón, rey de los amorreos,\nporque para siempre es su misericordia."],[20,"Y a Og, rey de Basán,\nporque para siempre es su misericordia.",[[15,20,2]]],[21,"Y dio la tierra de ellos en heredad,\nporque para siempre es su misericordia."],[22,"En heredad a Israel, su siervo,\nporque para siempre es su misericordia."],[23,"Al que en nuestra humillación se acordó de nosotros,\nporque para siempre es su misericordia."],[24,"Y nos libró de nuestros adversarios,\nporque para siempre es su misericordia."],[25,"El que da alimento a todo ser viviente,\nporque para siempre es su misericordia."],[26,"Dad gracias al Dios de los cielos,\nporque para siempre es su misericordia."]],"l":[[353,"Egipto",30.10809,31.33822],[965,"Mar Rojo",27.08847,34.77173],[154,"Basán",32.80007,35.9373]]},{"i":[[1,"Junto a los ríos de Babilonia, allí nos sentábamos,\ny aun llorábamos, al acordarnos de Sión.",[[20,29,0],[87,91,1]]],[2,"Sobre los sauces en medio de ella\ncolgamos nuestras arpas."],[3,"Porque allí, los que nos habían llevado cautivos nos pedían cánticos;\ny los que nos habían desolado nos pedían alegría, diciendo:\n«¡Cantadnos algunos de los cánticos de Sión!»",[[169,173,1]]],[4,"¿Cómo cantaremos cántico de Yahvé\nen tierra de extraños?"],[5,"Si me olvido de ti, oh Jerusalén,\npierda mi diestra su destreza.",[[23,32,2]]],[6,"Mi lengua se pegue a mi paladar, si de ti no me acordare;\nsi no enalteciere a Jerusalén por encima de mi mayor alegría.",[[78,87,2]]],[7,"Acuérdate, oh Yahvé, de los hijos de Edom en el día de Jerusalén,\nquienes decían: «¡Arrasadla!\n¡Arrasadla hasta sus cimientos!»",[[55,64,2]]],[8,"Hija de Babilonia, la desolada,\nbienaventurado el que te diere el pago\nde lo que tú nos hiciste.",[[8,17,0]]],[9,"Bienaventurado el que tomare y estrellare tus niños\ncontra la peña."]],"l":[[146,"Babilonia",32.5365,44.42088],[1239,"Sión",31.77744,35.23494],[622,"Jerusalén",31.77744,35.23494]]},{"i":[[0,"De David."],[1,"Te alabaré con todo mi corazón;\ndelante de los dioses te cantaré salmos."],[2,"Me postraré hacia tu santo templo,\ny daré gracias a tu nombre por tu misericordia y tu verdad;\nporque has engrandecido tu nombre y tu palabra sobre todas las cosas."],[3,"El día que clamé, me respondiste;\nme fortaleciste con vigor en mi alma."],[4,"Te alabarán, oh Yahvé, todos los reyes de la tierra,\nporque han oído los dichos de tu boca."],[5,"Y cantarán de los caminos de Yahvé,\nporque la gloria de Yahvé es grande."],[6,"Porque Yahvé es excelso, y atiende al humilde,\nmas al altivo mira de lejos."],[7,"Si anduviere en medio de la angustia, tú me vivificarás;\nextenderás tu mano contra la ira de mis enemigos,\ny me salvará tu diestra."],[8,"Yahvé cumplirá su propósito en mí;\ntu misericordia, oh Yahvé, es para siempre;\nno desampares la obra de tus manos."]],"l":[]},{"i":[[0,"Al músico principal. Salmo de David."],[1,"Yahvé, tú me has examinado\ny me conoces."],[2,"Tú has conocido mi sentarme y mi levantarme;\nhas entendido desde lejos mis pensamientos."],[3,"Has escudriñado mi andar y mi reposo,\ny todos mis caminos te son conocidos."],[4,"Pues aún no está la palabra en mi lengua,\ny he aquí, oh Yahvé, tú la sabes toda."],[5,"Detrás y delante me rodeaste,\ny sobre mí pusiste tu mano."],[6,"Tal conocimiento es demasiado maravilloso para mí;\nalto es,\nno lo puedo comprender."],[7,"¿A dónde me iré de tu Espíritu?\n¿Y a dónde huiré de tu presencia?"],[8,"Si subiere a los cielos, allí estás tú;\ny si en el Seol hiciere mi estrado, ¡he aquí, allí tú estás!"],[9,"Si tomare las alas del alba,\ny habitare en el extremo del mar,"],[10,"aun allí me guiará tu mano,\ny me asirá tu diestra."],[11,"Si dijere: «Ciertamente las tinieblas me encubrirán;\naun la noche resplandecerá en torno a mí»;"],[12,"aun las tinieblas no encubren de ti,\ny la noche resplandece como el día;\nlo mismo te son las tinieblas que la luz."],[13,"Porque tú formaste mis entrañas;\ntú me entretejiste en el vientre de mi madre."],[14,"Te alabaré,\nporque formidables, maravillosas son tus obras;\nestoy maravillado,\ny mi alma lo sabe muy bien."],[15,"No fue encubierto de ti mi cuerpo,\nbien que en oculto fui formado,\ny entretejido en lo más profundo de la tierra."],[16,"Mi embrión vieron tus ojos,\ny en tu libro estaban escritas todas aquellas cosas\nque fueron luego formadas,\nsin faltar una de ellas."],[17,"¡Cuán preciosos me son, oh Dios, tus pensamientos!\n¡Cuán grande es la suma de ellos!"],[18,"Si los enumero, se multiplican más que la arena;\ndespierto, y aún estoy contigo."],[19,"De cierto, oh Dios, matarás al impío;\n¡apartaos, pues, de mí, hombres sanguinarios!"],[20,"Porque blasfeman contra ti;\ntus enemigos toman tu nombre en vano."],[21,"¿No odio, oh Yahvé, a los que te aborrecen?\n¿Y no me enardezco contra los que se levantan contra ti?"],[22,"Los aborrezco por completo;\nlos tengo por enemigos."],[23,"Examíname, oh Dios, y conoce mi corazón;\npruébame y conoce mis pensamientos;"],[24,"y ve si hay en mí camino de perversidad,\ny guíame en el camino eterno."]],"l":[]},{"i":[[0,"Al músico principal. Salmo de David."],[1,"Líbrame, oh Yahvé, del hombre malo;\nguárdame de hombres violentos,"],[2,"los cuales maquinan males en el corazón;\ncada día provocan guerras."],[3,"Aguzaron su lengua como la serpiente;\nveneno de áspid hay debajo de sus labios. Selah"],[4,"Guárdame, oh Yahvé, de las manos del impío;\nlíbrame de hombres violentos, que han pensado trastornar mis pasos."],[5,"Me han escondido lazo y cuerdas los soberbios;\nhan tendido red junto a la senda;\nme han puesto trampas. Selah"],[6,"He dicho a Yahvé: «Mi Dios eres tú;\nescucha, oh Yahvé, la voz de mis ruegos»."],[7,"Yahvé, Señor, potente salvador mío,\ntú pusiste a cubierto mi cabeza en el día de la batalla."],[8,"No concedas, oh Yahvé, al impío sus deseos;\nno saques adelante su pensamiento, para que no se enorgullezca. Selah"],[9,"En cuanto a los que por todas partes me rodean,\nla maldad de sus propios labios cubra su cabeza."],[10,"Caigan sobre ellos brasas;\nsean echados en el fuego,\nen abismos profundos de donde no salgan."],[11,"El hombre deslenguado no será firme en la tierra;\nel mal cazará al hombre injusto para derribarle."],[12,"Yo sé que Yahvé tomará a su cargo la causa del afligido,\ny el derecho de los necesitados."],[13,"Ciertamente los justos alabarán tu nombre;\nlos rectos morarán en tu presencia."]],"l":[]},{"i":[[0,"Salmo de David."],[1,"Yahvé, a ti he clamado; ¡apresúrate a mí!\nEscucha mi voz cuando te invoco."],[2,"Suba mi oración delante de ti como el incienso,\ny el alzar de mis manos como la ofrenda de la tarde."],[3,"Pon guarda, oh Yahvé, a mi boca;\nguarda la puerta de mis labios."],[4,"No inclines mi corazón a cosa mala,\npara hacer obras impías con los que obran iniquidad;\ny no coma yo de sus deleites."],[5,"Que el justo me castigue, será un favor;\nque me reprenda, será como excelente bálsamo\nque mi cabeza no rechazará;\npues mi oración será continuamente contra sus maldades."],[6,"Sus jueces serán despeñados por los peñascos,\ny oirán mis palabras, que son agradables."],[7,"«Como quien hiende y rompe la tierra,\nson esparcidos nuestros huesos a la boca del Seol»."],[8,"Por tanto, a ti, oh Yahvé, Señor, miran mis ojos;\nen ti me refugio;\nno desampares mi alma."],[9,"Guárdame del lazo que me han tendido,\ny de las trampas de los que obran iniquidad."],[10,"Caigan los impíos a una en sus propias redes,\nmientras yo paso a salvo."]],"l":[]},{"i":[[0,"Masquil de David. Oración que hizo cuando estaba en la cueva."],[1,"Con mi voz clamo a Yahvé;\ncon mi voz pido a Yahvé misericordia."],[2,"Delante de él derramo mi querella;\ndelante de él declaro mi angustia."],[3,"Cuando mi espíritu desmayaba dentro de mí,\ntú conociste mi senda.\nEn el camino en que andaba,\nme escondieron lazo."],[4,"Mira a mi diestra y observa,\npues no hay quien me quiera conocer;\nno tengo refugio,\nni hay quien cuide de mi vida."],[5,"Clamé a ti, oh Yahvé;\ndije: «Tú eres mi refugio,\nmi porción en la tierra de los vivientes»."],[6,"Escucha mi clamor,\nporque estoy muy abatido.\nLíbrame de los que me persiguen,\nporque son más fuertes que yo."],[7,"Saca mi alma de la cárcel,\npara que alabe tu nombre;\nme rodearán los justos,\nporque tú me serás propicio."]],"l":[]},{"i":[[0,"Salmo de David."],[1,"Oh Yahvé, escucha mi oración,\nescucha mis súplicas;\nrespóndeme por tu verdad y por tu justicia."],[2,"Y no entres en juicio con tu siervo,\nporque no se justificará delante de ti ningún ser humano."],[3,"Porque el enemigo ha perseguido mi alma;\nha postrado en tierra mi vida;\nme ha hecho habitar en tinieblas como los ya muertos."],[4,"Y mi espíritu se angustió dentro de mí;\nmi corazón está desolado."],[5,"Me acordé de los días antiguos;\nmedito en todas tus obras,\nreflexiono en la obra de tus manos."],[6,"Extiendo mis manos a ti;\nmi alma tiene sed de ti como la tierra seca. Selah"],[7,"Respóndeme pronto, oh Yahvé,\nque desmaya mi espíritu;\nno escondas de mí tu rostro,\npara que no sea yo como los que descienden a la fosa."],[8,"Hazme oír por la mañana tu misericordia,\nporque en ti he confiado;\nhazme saber el camino por donde ande,\nporque a ti he elevado mi alma."],[9,"Líbrame de mis enemigos, oh Yahvé;\nen ti me refugio."],[10,"Enséñame a hacer tu voluntad,\nporque tú eres mi Dios;\ntu buen Espíritu\nme guíe a tierra de rectitud."],[11,"Por tu nombre, oh Yahvé, me vivificarás;\npor tu justicia sacarás mi alma de la angustia."],[12,"Y por tu misericordia disiparás a mis enemigos,\ny destruirás a todos los que afligen mi alma,\nporque yo soy tu siervo."]],"l":[]},{"i":[[0,"De David."],[1,"Bendito sea Yahvé, mi roca,\nquien adiestra mis manos para la batalla,\ny mis dedos para la guerra;"],[2,"misericordia mía y mi castillo,\nfortaleza mía y mi libertador,\nescudo mío, en quien me he refugiado;\nel que sujeta a mi pueblo debajo de mí."],[3,"Oh Yahvé, ¿qué es el hombre, para que en él pienses?\n¿O el hijo de hombre, para que lo estimes?"],[4,"El hombre es semejante a la vanidad;\nsus días son como la sombra que pasa."],[5,"Inclina, oh Yahvé, tus cielos, y desciende;\ntoca los montes, y humeen."],[6,"Despide relámpagos y disípalos,\nenvía tus saetas y túrbalos."],[7,"Envía tu mano desde lo alto;\nrescátame, y sácame de las muchas aguas,\nde la mano de los hombres extraños,"],[8,"cuya boca habla vanidad,\ny cuya diestra es diestra de mentira."],[9,"Oh Dios, a ti cantaré un cántico nuevo;\ncon salterio de diez cuerdas cantaré a ti,"],[10,"el que da salvación a los reyes,\nel que rescata a su siervo David de la espada maligna."],[11,"Rescátame, y líbrame de la mano de los hombres extraños,\ncuya boca habla vanidad,\ny cuya diestra es diestra de mentira."],[12,"Sean nuestros hijos como plantas crecidas en su juventud,\nnuestras hijas como esquinas labradas a manera de las de un palacio."],[13,"Nuestros graneros estén llenos, provistos de toda suerte de grano;\nnuestros rebaños se multipliquen por millares y decenas de millares en nuestros campos."],[14,"Nuestros bueyes estén fuertes para el trabajo;\nno haya asalto, ni que hacer salida,\nni grito de alarma en nuestras plazas."],[15,"Bienaventurado el pueblo que tiene esto;\nbienaventurado el pueblo cuyo Dios es Yahvé."]],"l":[]},{"i":[[0,"Salmo de alabanza. De David."],[1,"Te exaltaré, mi Dios, mi Rey,\ny bendeciré tu nombre eternamente y para siempre."],[2,"Cada día te bendeciré,\ny alabaré tu nombre eternamente y para siempre."],[3,"¡Grande es Yahvé, y digno de suprema alabanza!\nSu grandeza es insondable."],[4,"Generación a generación celebrará tus obras,\ny anunciará tus poderosos hechos."],[5,"En la hermosura de la gloria de tu majestad,\ny en tus maravillosas obras meditaré."],[6,"Del poder de tus hechos estupendos hablarán los hombres,\ny yo publicaré tu grandeza."],[7,"Proclamarán el recuerdo de tu inmensa bondad,\ny cantarán tu justicia."],[8,"Clemente y misericordioso es Yahvé,\nlento para la ira, y grande en misericordia."],[9,"Bueno es Yahvé para con todos,\ny sus misericordias sobre todas sus obras."],[10,"Te alaben, oh Yahvé, todas tus obras,\ny tus santos te bendigan."],[11,"Hablarán de la gloria de tu reino,\ny hablarán de tu poder,"],[12,"para hacer saber a los hijos de los hombres tus proezas,\ny la gloria de la majestad de tu reino."],[13,"Tu reino es reino de todos los siglos,\ny tu señorío en todas las generaciones.\nFiel es Yahvé en todas sus palabras,\ny misericordioso en todas sus obras."],[14,"Sostiene Yahvé a todos los que caen,\ny levanta a todos los oprimidos."],[15,"Los ojos de todos esperan en ti,\ny tú les das su comida a su tiempo."],[16,"Abres tu mano,\ny colmas de bendición a todo ser viviente."],[17,"Justo es Yahvé en todos sus caminos,\ny misericordioso en todas sus obras."],[18,"Cercano está Yahvé a todos los que le invocan,\na todos los que le invocan de veras."],[19,"Cumplirá el deseo de los que le temen;\noirá asimismo el clamor de ellos, y los salvará."],[20,"Yahvé guarda a todos los que le aman,\nmas destruirá a todos los impíos."],[21,"La alabanza de Yahvé proclamará mi boca;\ny todos bendigan su santo nombre eternamente y para siempre."]],"l":[]},{"i":[[1,"¡Alabado sea Yah!\n¡Alaba, oh alma mía, a Yahvé!"],[2,"Alabaré a Yahvé en mi vida;\ncantaré salmos a mi Dios mientras viva."],[3,"No confiéis en los príncipes,\nni en hijo de hombre, porque no hay en él salvación."],[4,"Pues sale su aliento, y vuelve a la tierra;\nen ese mismo día perecen sus pensamientos."],[5,"Bienaventurado aquel cuyo ayudador es el Dios de Jacob,\ncuya esperanza está en Yahvé su Dios,"],[6,"el cual hizo los cielos y la tierra,\nel mar, y todo lo que en ellos hay;\nel que guarda la verdad para siempre,"],[7,"el que hace justicia a los oprimidos,\nel que da pan a los hambrientos.\nYahvé liberta a los cautivos;"],[8,"Yahvé abre los ojos a los ciegos;\nYahvé levanta a los caídos;\nYahvé ama a los justos."],[9,"Yahvé guarda a los forasteros;\nal huérfano y a la viuda sostiene,\ny el camino de los impíos trastorna."],[10,"Reinará Yahvé para siempre;\ntu Dios, oh Sión, por todas las generaciones.\n¡Alabado sea Yah!",[[40,44,0]]]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[1,"¡Alabado sea Yah!\nPorque es bueno cantar salmos a nuestro Dios;\nporque suave y hermosa es la alabanza."],[2,"Yahvé edifica a Jerusalén;\na los desterrados de Israel recogerá.",[[16,25,0]]],[3,"Él sana a los quebrantados de corazón,\ny venda sus heridas."],[4,"Él cuenta el número de las estrellas;\na todas ellas llama por sus nombres."],[5,"Grande es nuestro Señor, y de inmenso poder;\nsu entendimiento es infinito."],[6,"Yahvé exalta a los humildes,\ny humilla a los impíos hasta la tierra."],[7,"Cantad a Yahvé con acción de gracias;\ncantad con arpa a nuestro Dios."],[8,"Él es quien cubre de nubes los cielos,\nel que prepara la lluvia para la tierra,\nel que hace a los montes producir hierba."],[9,"Él da a la bestia su mantenimiento,\ny a los críos de los cuervos que claman."],[10,"No se deleita en la fuerza del caballo,\nni se complace en la agilidad del hombre."],[11,"Se complace Yahvé en los que le temen,\ny en los que esperan en su misericordia."],[12,"¡Alaba a Yahvé, Jerusalén!\n¡Alaba a tu Dios, oh Sión!",[[16,25,0],[48,52,1]]],[13,"Porque fortificó los cerrojos de tus puertas;\nbendijo a tus hijos dentro de ti."],[14,"Él pone paz en tus fronteras,\ny te sacia con lo mejor del trigo."],[15,"Él envía su palabra a la tierra;\nvelozmente corre su mandato."],[16,"Da la nieve como lana,\ny esparce la escarcha como ceniza."],[17,"Echa su granizo como pedazos;\nante su frío, ¿quién podrá resistir?"],[18,"Envía su palabra, y los derrite;\nhace soplar su viento, y fluyen las aguas."],[19,"Ha manifestado sus palabras a Jacob,\nsus estatutos y sus juicios a Israel."],[20,"No ha hecho esto con ninguna otra nación;\ny en cuanto a sus juicios, no los conocieron.\n¡Alabado sea Yah!"]],"l":[[622,"Jerusalén",31.77744,35.23494],[1239,"Sión",31.77744,35.23494]]},{"i":[[1,"¡Alabado sea Yah!\n¡Alabad a Yahvé desde los cielos!\n¡Alabadle en las alturas!"],[2,"¡Alabadle, vosotros todos sus ángeles!\n¡Alabadle, vosotros todos sus ejércitos!"],[3,"¡Alabadle, sol y luna!\n¡Alabadle, todas las estrellas lucientes!"],[4,"¡Alabadle, cielos de los cielos,\ny las aguas que están sobre los cielos!"],[5,"Alaben el nombre de Yahvé,\nporque él mandó, y fueron creados."],[6,"Los estableció eternamente y para siempre;\nles puso ley que no será quebrantada."],[7,"Alabad a Yahvé desde la tierra,\nlos monstruos marinos y todos los abismos;"],[8,"el fuego y el granizo, la nieve y el vapor,\nel viento tempestuoso que ejecuta su palabra;"],[9,"los montes y todos los collados,\nel árbol de fruto y todos los cedros;"],[10,"las bestias y todo animal,\nlos reptiles y las aves;"],[11,"los reyes de la tierra y todos los pueblos,\nlos príncipes y todos los jueces de la tierra;"],[12,"los jóvenes y también las doncellas,\nlos ancianos y los niños."],[13,"Alaben el nombre de Yahvé,\nporque solo su nombre es excelso.\nSu gloria es sobre tierra y cielos."],[14,"Él ha exaltado el cuerno de su pueblo;\nalaben todos sus santos,\nlos hijos de Israel, el pueblo a él cercano.\n¡Alabado sea Yah!"]],"l":[]},{"i":[[1,"¡Alabado sea Yah!\nCantad a Yahvé cántico nuevo;\nsu alabanza en la congregación de los santos."],[2,"Alégrese Israel en su Hacedor;\nlos hijos de Sión se gocen en su Rey.",[[44,48,0]]],[3,"Alaben su nombre con danza;\ncon pandero y arpa a él canten."],[4,"Porque Yahvé tiene contentamiento en su pueblo;\nhermoseará a los humildes con la salvación."],[5,"Regocíjense los santos por su gloria,\ny canten aun sobre sus lechos."],[6,"Exalten a Dios con sus gargantas,\ny espadas de dos filos en sus manos,"],[7,"para ejecutar venganza entre las naciones,\ny castigo entre los pueblos;"],[8,"para aprisionar a sus reyes con cadenas,\ny a sus nobles con grillos de hierro;"],[9,"para ejecutar en ellos el juicio decretado;\ngloria será esto para todos sus santos.\n¡Alabado sea Yah!"]],"l":[[1239,"Sión",31.77744,35.23494]]},{"i":[[1,"¡Alabado sea Yah!\n¡Alabad a Dios en su santuario!\n¡Alabadle en la magnificencia de su firmamento!"],[2,"¡Alabadle por sus proezas!\n¡Alabadle conforme a la inmensidad de su grandeza!"],[3,"¡Alabadle a son de bocina!\n¡Alabadle con salterio y arpa!"],[4,"¡Alabadle con pandero y danza!\n¡Alabadle con cuerdas y flautas!"],[5,"¡Alabadle con címbalos resonantes!\n¡Alabadle con címbalos de júbilo!"],[6,"¡Todo lo que respira alabe a Yah!\n¡Alabado sea Yah!"]],"l":[]}]});
